        if (t && !bg) { info.pedido_venda = t.pedido_venda || ''; info.nfe_ref = t.referencia || ''; info.cliente = t.cliente_nome || r.sacado; info.parcela = t.numero_parcela || ''; info.achado_por = _tr.como; }
