  app.post('/api/produtos-fiscais/aplicar-ncm-tinta', rota((req, res) => {
    const ncmUsar = (req.body?.ncm || '').replace(/\D/g,'');
    if (ncmUsar.length !== 8) return res.status(400).json({ erro: 'NCM deve ter 8 dígitos.' });

    const todos = queryAll('SELECT id, descricao FROM produtos_fiscais');
    const semAcento = s => (s||'').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
    const ehTintaMassa = d => {
      const t = semAcento(d);
      if (/REJUNTE|ARGAMASSA|\bAC\s*-?\s*[123]\b|\bPSP\b|PISO\s*S(OBRE)?\s*PISO/.test(t)) return false;
      return /TINTA|MASSA|SELADOR|ACRILIC|PVA|LATEX|ESMALTE|VERNIZ|ECONOMICA/.test(t);
    };

    const alvos = todos.filter(p => ehTintaMassa(p.descricao));
    alvos.forEach(p => {
      db.run("UPDATE produtos_fiscais SET ncm=?, atualizado_em=datetime('now','localtime') WHERE id=?", [ncmUsar, p.id]);
    });
    if (alvos.length) { registrarLog('APLICAÇÃO DE NCM EM TINTAS/MASSAS', `${alvos.length} produtos — NCM ${ncmUsar}`, '', '', req.usuario?.nome || 'sistema'); salvarArquivo(); }
    res.json({ ok: true, aplicados: alvos.length, produtos: alvos.map(p => p.descricao) });
  }));

  // ─── PEDIDOS ────────────────────────────────────────────────────────────────
  // Grupos de produtos para comissão: rejuntes viram UM grupo só (as cores não mudam a comissão)
  function grupoDoProduto(desc) {
    const t = (desc||'').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
    if (/REJUNTE/.test(t)) return 'REJUNTES';
    return (desc||'').trim().toUpperCase();
  }

  app.get('/api/produtos-grupos', rota((req, res) => {
    // A lista de comissão usa SOMENTE os produtos cadastrados (Produtos Fiscais),
    // para ficar igual ao cadastro. (Antes misturava nomes vindos dos pedidos importados.)
    const grupos = new Map(); // grupo → quantos produtos cadastrados ele reúne
    queryAll('SELECT descricao FROM produtos_fiscais').forEach(p => {
      if (!p.descricao) return;
      const g = grupoDoProduto(p.descricao.trim());
      grupos.set(g, (grupos.get(g) || 0) + 1);
    });
    const lista = [...grupos.entries()].map(([grupo, itens]) => ({ grupo, itens })).sort((a,b) => a.grupo.localeCompare(b.grupo));
    res.json(lista);
  }));

  // Produtos que JÁ FORAM VENDIDOS (aparecem nos pedidos) mas cujo nome NÃO bate com
  // nenhum produto cadastrado — logo não têm % de comissão até o nome ser padronizado.
  app.get('/api/produtos-grupos/divergentes', rota((req, res) => {
    const cadastrados = new Set();
    queryAll('SELECT descricao FROM produtos_fiscais').forEach(p => {
      if (p.descricao) cadastrados.add(grupoDoProduto(p.descricao.trim()));
    });
    const vendidos = new Map(); // grupo vendido → quantidade de pedidos-linha
    queryAll(`SELECT produto, COUNT(*) AS n FROM pedidos
              WHERE produto IS NOT NULL AND produto!='' AND produto!='-'
                AND (cancelado IS NULL OR cancelado=0)
                AND (ef_remessa IS NULL OR ef_remessa=0)
              GROUP BY produto`).forEach(p => {
      const g = grupoDoProduto((p.produto||'').trim());
      if (!g || cadastrados.has(g)) return;               // já bate com o cadastro → ok
      vendidos.set(g, (vendidos.get(g) || 0) + (+p.n || 0));
    });
    const lista = [...vendidos.entries()].map(([produto, ocorrencias]) => ({ produto, ocorrencias }))
      .sort((a,b) => b.ocorrencias - a.ocorrencias);
    res.json(lista);
  }));

