  // Copia as comissões de um representante para outro (ou para vários)
  app.post('/api/representantes/replicar-comissoes', rota((req, res) => {
    const { origem_id, destino_ids, substituir } = req.body || {};
    if (!origem_id) return res.status(400).json({ erro: 'Informe o representante de origem.' });
    if (!Array.isArray(destino_ids) || !destino_ids.length)
      return res.status(400).json({ erro: 'Selecione ao menos um representante de destino.' });

    const origem = queryOne('SELECT nome FROM representantes WHERE id=?', [origem_id]);
    if (!origem) return res.status(404).json({ erro: 'Representante de origem não encontrado.' });
    const comissoes = queryAll('SELECT grupo, percentual FROM representante_comissoes WHERE representante_id=?', [origem_id]);
    if (!comissoes.length) return res.status(400).json({ erro: `${origem.nome} não tem comissões cadastradas para copiar.` });

    const aplicados = [];
    destino_ids.forEach(did => {
      if (String(did) === String(origem_id)) return; // não copia para si mesmo
      const dest = queryOne('SELECT nome FROM representantes WHERE id=?', [did]);
      if (!dest) return;
      if (substituir) db.run('DELETE FROM representante_comissoes WHERE representante_id=?', [did]);
      comissoes.forEach(c => {
        // substituir = sobrescreve tudo; senão, só preenche o que estiver faltando
        const existe = queryOne('SELECT id FROM representante_comissoes WHERE representante_id=? AND grupo=?', [did, c.grupo]);
        if (existe && !substituir) return;
        if (existe) db.run('UPDATE representante_comissoes SET percentual=? WHERE id=?', [c.percentual, existe.id]);
        else db.run('INSERT INTO representante_comissoes (representante_id, grupo, percentual) VALUES (?,?,?)',
          [did, c.grupo, c.percentual]);
      });
      aplicados.push(dest.nome);
    });
    registrarLog('REPLICAÇÃO DE COMISSÕES', `de ${origem.nome} para ${aplicados.length} representante(s)`, '', '', req.usuario?.nome || 'sistema');
    salvarArquivo();
    res.json({ ok: true, origem: origem.nome, grupos: comissoes.length, aplicados });
  }));

