  // Lista unificada de TODOS os produtos do sistema (cadastro fiscal + os que aparecem em pedidos)
  // Categoria do produto para agrupar nas listas de escolha
  function categoriaProduto(desc) {
    const t = (desc||'').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
    if (/REJUNTE/.test(t))                                  return 'REJUNTES';
    if (/ARGAMASSA|\bAC\s*-?\s*[123]\b|\bACI{1,3}\b|\bPSP\b|PISO\s*S(OBRE)?\s*PISO/.test(t)) return 'ARGAMASSAS';
    if (/TINTA|MASSA\s*(PVA|ACRILICA|CORRIDA)|SELADOR|TEXTURA|VERNIZ/.test(t)) return 'TINTAS E MASSAS';
    return 'OUTROS';
  }

  // ─── PRODUTOS EXCLUSIVOS DE CLIENTE (marca própria) ──────────────────────────
  // Produto com a marca no nome (ex.: "MASSA PVA COROA 13 KG") só pode ser vendido
  // para o cliente daquela marca. Para os demais clientes ele nem aparece na lista.
  const MARCAS_EXCLUSIVAS = ['COROA', 'CONDEC'];
  const _semAcento = s => String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toUpperCase();
  // Marca da qual o produto é exclusivo ('' = produto normal, vende para todo mundo)
  function marcaExclusivaDe(nomeProduto) {
    const n = _semAcento(nomeProduto);
    return MARCAS_EXCLUSIVAS.find(m => new RegExp('(^|[^A-Z])' + m + '([^A-Z]|$)').test(n)) || '';
  }
  // Marcas exclusivas que ESTE cliente pode comprar (pelo nome/fantasia dele)
  function marcasDoCliente(nomeCliente) {
    const cli = queryOne('SELECT razao_social, nome_fantasia FROM clientes_fiscais WHERE razao_social=? COLLATE NOCASE', [String(nomeCliente||'').trim()]);
    const alvo = _semAcento([nomeCliente, cli?.razao_social, cli?.nome_fantasia].filter(Boolean).join(' '));
    return MARCAS_EXCLUSIVAS.filter(m => new RegExp('(^|[^A-Z])' + m + '([^A-Z]|$)').test(alvo));
  }
  // Devolve o 1º item barrado, ou '' se estiver tudo liberado para esse cliente
  function itemProibidoParaCliente(itens, nomeCliente) {
    const permitidas = marcasDoCliente(nomeCliente);
    for (const it of (itens || [])) {
      const marca = marcaExclusivaDe(it && (it.produto || it));
      if (marca && !permitidas.includes(marca)) return { produto: (it.produto || it), marca };
    }
    return null;
  }

  app.get('/api/produtos-todos', rota((req, res) => {
    // v.119: a lista de escolha usa SOMENTE os produtos cadastrados (menu Produtos NF-e).
    // Antes ela misturava nomes de produtos vindos de pedidos importados de PDF, o que
    // criava duplicados ("ARGAMASSA AC2" x "ARGAMASSA AC2 20KG" etc.).
    const nomes = new Set();
    queryAll('SELECT descricao FROM produtos_fiscais').forEach(p => { if (p.descricao) nomes.add(p.descricao.trim()); });
    if (!nomes.size) {
      // Segurança: se ainda não há nenhum produto cadastrado, usa os nomes dos pedidos
      // para não deixar as telas de pedido/orçamento com a lista vazia.
      queryAll(`SELECT DISTINCT produto FROM pedidos WHERE produto IS NOT NULL AND produto!='' AND produto!='-'
        AND produto NOT LIKE '%Nenhum produto%'`).forEach(p => { if (p.produto) nomes.add(p.produto.trim()); });
      if (nomes.size) console.log('  ⚠️ produtos-todos: sem produtos cadastrados — usando nomes dos pedidos como reserva.');
    }
    // valor de referência: pega o valor unitário do cadastro fiscal, se houver
    const precos = {};
    queryAll('SELECT descricao, valor_unitario FROM produtos_fiscais WHERE valor_unitario>0').forEach(p => {
      precos[p.descricao.trim()] = p.valor_unitario;
    });
    // ordem das categorias na lista de escolha
    const ordem = { 'ARGAMASSAS': 1, 'TINTAS E MASSAS': 2, 'REJUNTES': 3, 'OUTROS': 4 };
    let lista = [...nomes].map(nome => ({
      produto: nome, valor_ref: precos[nome] || 0, categoria: categoriaProduto(nome),
      marca_exclusiva: marcaExclusivaDe(nome)     // '' = vende para qualquer cliente
    })).sort((a,b) => (ordem[a.categoria]-ordem[b.categoria]) || a.produto.localeCompare(b.produto));
    // ?cliente=NOME já devolve a lista pronta para aquele cliente
    const _cliQ = String(req.query.cliente||'').trim();
    if (_cliQ) {
      const permitidas = marcasDoCliente(_cliQ);
      lista = lista.filter(p => !p.marca_exclusiva || permitidas.includes(p.marca_exclusiva));
    }
    res.json(lista);
  }));

  /* v.340: NUMERAÇÃO DE PEDIDO POR UNIDADE. Simões Filho continua na sequência de sempre
     (o maior número + 1, ex.: 095144071). Petrolina e Barreiras têm faixa própria, com
     prefixo: Petrolina 2 + 8 dígitos (200000001, 200000002…), Barreiras 3 + 8 dígitos
     (300000001…). Cada faixa anda sozinha, e um número de uma unidade nunca cai na outra.
     O prefixo/largura fica em fluxo_config (numeracao_pedido_json) e o gestor ajusta em
     Configuração NF-e → "Numeração de pedidos por unidade". */
  const NUMERACAO_UNIDADE_PADRAO = { emp2: { prefixo: '2', largura: 9 }, emp3: { prefixo: '3', largura: 9 } };
  function _numeracaoTab(){
    let tab = {}; try { const r = queryOne("SELECT valor FROM fluxo_config WHERE chave='numeracao_pedido_json'"); if (r && r.valor) tab = JSON.parse(r.valor) || {}; } catch(e) {}
    const out = Object.assign({}, NUMERACAO_UNIDADE_PADRAO);
    Object.keys(tab).forEach(k => { const v = tab[k] || {}; if (k === 'emp1') return;
      const p = String(v.prefixo || '').replace(/\D/g, ''), l = parseInt(v.largura, 10);
      if (!p) { delete out[k]; return; }                       // sem prefixo = usa a sequência da matriz
      out[k] = { prefixo: p, largura: (l >= p.length + 3 && l <= 12) ? l : Math.max(9, p.length + 3) }; });
    return out;
  }
  function _regraNumeracao(unidade){ const u = String(unidade || '').trim(); return (u && u !== 'emp1') ? (_numeracaoTab()[u] || null) : null; }
  const _numeroSegueRegra = (nr, regra) => { const d = String(nr || '').replace(/\D/g, ''); return !!regra && d.length === regra.largura && d.startsWith(regra.prefixo); };
  function proximoNumeroPedidoLivre(unidade) {
    const regra = _regraNumeracao(unidade);
    const tab = _numeracaoTab(); const regras = Object.values(tab);
    let maior = 0, largura = 6;
    queryAll('SELECT DISTINCT pedido_venda FROM pedidos').forEach(r => {
      const dig = String(r.pedido_venda).replace(/\D/g,'');
      const n = parseInt(dig, 10);
      if (isNaN(n)) return;
      if (regra) { if (!_numeroSegueRegra(dig, regra)) return; }                 // só a faixa desta unidade
      else if (regras.some(g => _numeroSegueRegra(dig, g))) return;             // matriz: ignora as faixas das outras
      if (n > maior) { maior = n; largura = Math.max(largura, dig.length); }
    });
    if (regra) {
      const base = parseInt(regra.prefixo + '0'.repeat(regra.largura - regra.prefixo.length), 10);
      const prox = maior > 0 ? maior + 1 : base + 1;
      return { nr: String(prox).padStart(regra.largura, '0'), base_pdf: maior, unidade: String(unidade), regra };
    }
    return { nr: String(maior + 1).padStart(largura, '0'), base_pdf: maior, unidade: 'emp1', regra: null };
  }
  /* devolve '' se o número serve para a unidade; senão, a mensagem de erro */
  function _confereNumeroDaUnidade(nr, unidade){
    const regra = _regraNumeracao(unidade);
    if (!regra) return '';
    if (_numeroSegueRegra(nr, regra)) return '';
    const nome = (queryOne('SELECT nome FROM cp_empresas WHERE id=?', [unidade]) || {}).nome || unidade;
    return `Pedido de ${nome} usa número que começa com ${regra.prefixo} e tem ${regra.largura} dígitos (próximo: ${proximoNumeroPedidoLivre(unidade).nr}). O número ${nr} é da faixa de outra unidade.`;
  }

  // Cria um pedido manual com vários itens
  // Sugere o próximo número de pedido (maior número existente + 1, preservando dígitos)
  app.get('/api/pedidos/proximo-numero', rota((req, res) => {
    const r = proximoNumeroPedidoLivre(_unidadeDeQuemLanca(req));   // v.340: da unidade de quem lança
    res.json({ proximo: r.nr, base_pdf: r.base_pdf, unidade: r.unidade, regra: r.regra });
  }));
  /* v.340: configuração da numeração por unidade */
  /* ═══ v.363: CIDADES POR UNIDADE ═══
     Pedido de cliente de Luís Eduardo Magalhães é da unidade de Barreiras, seja quem for que lance.
     Tabela cidade → unidade (fluxo_config 'cidades_unidade_json'), editável em Configuração NF-e.
     Vale ao criar pedido (manual, portal do representante, orçamento, importação de PDF). */
  const CIDADES_UNIDADE_PADRAO = { emp2: ['PETROLINA', 'JUAZEIRO'], emp3: ['BARREIRAS', 'LUIS EDUARDO MAGALHAES'] };   // v.382: Juazeiro → Petrolina
  const _normCid = c => String(c || '').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^A-Z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
  function _cidadesUnidadeTab(){
    let tab = null; try { const r = queryOne("SELECT valor FROM fluxo_config WHERE chave='cidades_unidade_json'"); if (r && r.valor) tab = JSON.parse(r.valor); } catch(e) {}
    if (!tab || typeof tab !== 'object') tab = CIDADES_UNIDADE_PADRAO;
    const out = {}; Object.keys(tab).forEach(k => { if (k === 'emp1') return; out[k] = [...new Set((Array.isArray(tab[k]) ? tab[k] : []).map(_normCid).filter(Boolean))]; });
    return out;
  }
  function _unidadePelaCidade(cidade){
    const c = _normCid(cidade); if (!c) return '';
    const tab = _cidadesUnidadeTab();
    for (const u of Object.keys(tab)) if (tab[u].some(x => c === x || c.startsWith(x + ' ') || c.startsWith(x + '/') || c.startsWith(x + '-'))) return u;
    return '';
  }
  /* v.381: REPRESENTANTE → UNIDADE. Pedido do Sebastião Clarentino é de Petrolina, em qualquer cidade.
     Tabela em fluxo_config 'reps_unidade_json' (mesmo card das cidades). Ordem: cidade → representante → quem lança. */
  /* v.391: a MATRIZ também pode ter representante fixo (Janaina Carla é de Simões Filho; a
     outra Janaina, Duarte, é de Petrolina). E o nome da regra casa de forma ESTRITA: ou é o
     nome inteiro, ou todas as palavras da regra (pelo menos duas) estão no nome do
     representante. Antes "JANAINA" sozinho casava com as duas Janainas, e os pedidos da
     QUALY ENGENHARIA (Janaina Carla, Lauro de Freitas) foram parar em Petrolina. */
  const REPS_UNIDADE_PADRAO = { emp1: ['JANAINA CARLA DA SILVA'], emp2: ['SEBASTIAO CLARENTINO', 'JANAINA DUARTE'] };
  function _repsUnidadeTab(){
    let tab = null; try { const r = queryOne("SELECT valor FROM fluxo_config WHERE chave='reps_unidade_json'"); if (r && r.valor) tab = JSON.parse(r.valor); } catch(e) {}
    if (!tab || typeof tab !== 'object') tab = REPS_UNIDADE_PADRAO;
    const out = {}; Object.keys(tab).forEach(k => { out[k] = [...new Set((Array.isArray(tab[k]) ? tab[k] : []).map(x => _normCid(x)).filter(Boolean))]; });
    return out;
  }
  function _repBateRegra(rep, regra){
    const R = _normCid(rep), X = _normCid(regra); if (!R || !X) return false;
    if (R === X) return true;
    const tx = X.split(' ').filter(t => t.length > 1), tr = R.split(' ');
    return tx.length >= 2 && tx.every(t => tr.includes(t));
  }
  function _unidadePeloRep(rep){
    const r = String(rep || '').trim(); if (!r) return '';
    const tab = _repsUnidadeTab();
    for (const u of Object.keys(tab)) if (tab[u].some(x => _repBateRegra(r, x))) return u;
    return '';
  }
  // unidade do pedido NOVO: a da cidade do cliente; senão a do representante; senão a de quem lança
  function _unidadeDoPedidoNovo(req, cidade, rep){ return _unidadePelaCidade(cidade) || _unidadePeloRep(rep) || _unidadeDeQuemLanca(req); }
  app.get('/api/config/cidades-unidade', rota((req, res) => {
    const tab = _cidadesUnidadeTab(); const reps = _repsUnidadeTab(); const emps = queryAll('SELECT id, nome FROM cp_empresas ORDER BY id') || [];
    res.json({ ok: true, unidades: emps.map(e => ({ empresa_id: e.id, nome: e.nome, cidades: tab[e.id] || [], representantes: reps[e.id] || [], so_representantes: e.id === 'emp1' ? 1 : 0 })) });
  }));
  app.put('/api/config/reps-unidade', rota((req, res) => {
    if (!ehDono(req.usuario)) return res.status(403).json({ erro: 'Só o administrador altera os representantes por unidade.' });
    const b = req.body || {}; const tab = {};
    Object.keys(b).forEach(k => { const v = b[k]; tab[k] = [...new Set((Array.isArray(v) ? v : String(v || '').split(/[;\n,]/)).map(x => _normCid(x)).filter(Boolean))]; });
    db.run("DELETE FROM fluxo_config WHERE chave='reps_unidade_json'");
    db.run("INSERT INTO fluxo_config (chave, valor) VALUES ('reps_unidade_json', ?)", [JSON.stringify(tab)]);
    registrarLog('REPRESENTANTES POR UNIDADE', Object.keys(tab).map(u => `${u}: ${tab[u].join(', ') || '(nenhum)'}`).join(' · '), '', '', req.usuario?.nome || 'sistema');
    salvarArquivo(); res.json({ ok: true });
  }));
  app.put('/api/config/cidades-unidade', rota((req, res) => {
    if (!ehDono(req.usuario)) return res.status(403).json({ erro: 'Só o administrador altera as cidades por unidade.' });
    const b = req.body || {}; const tab = {};
    Object.keys(b).forEach(k => { if (k === 'emp1') return; const v = b[k]; tab[k] = [...new Set((Array.isArray(v) ? v : String(v || '').split(/[;\n,]/)).map(_normCid).filter(Boolean))]; });
    db.run("DELETE FROM fluxo_config WHERE chave='cidades_unidade_json'");
    db.run("INSERT INTO fluxo_config (chave, valor) VALUES ('cidades_unidade_json', ?)", [JSON.stringify(tab)]);
    registrarLog('CIDADES POR UNIDADE', Object.keys(tab).map(u => `${u}: ${tab[u].join(', ') || '(nenhuma)'}`).join(' · '), '', '', req.usuario?.nome || 'sistema');
    salvarArquivo(); res.json({ ok: true });
  }));
  /* move para a unidade certa os pedidos já lançados cuja cidade tem regra (não mexe em pedido com NF-e autorizada em outra empresa) */
  function _aplicarCidadesUnidade(quem, soPrevia){
    const tab = _cidadesUnidadeTab(); const nomes = new Map((queryAll('SELECT id, nome FROM cp_empresas') || []).map(e => [e.id, e.nome]));
    const movidos = [], recusados = [];
    const peds = queryAll("SELECT DISTINCT pedido_venda, cidade, representante, COALESCE(empresa_id,'emp1') AS empresa_id, MAX(COALESCE(unidade_fixa,0)) AS fixa FROM pedidos WHERE pedido_venda IS NOT NULL AND pedido_venda<>'' AND COALESCE(cancelado,0)=0 GROUP BY pedido_venda");
    peds.forEach(p => {
      const alvo = _unidadePelaCidade(p.cidade) || _unidadePeloRep(p.representante); if (!alvo || alvo === p.empresa_id) return;   // v.381: representante também
      if (p.fixa) { recusados.push({ pedido: p.pedido_venda, cidade: p.cidade || '', motivo: 'movido à mão (fica onde está)' }); return; }   // v.407
      /* v.380: a cidade manda SEMPRE — mesmo que a nota tenha saído por outro CNPJ, o pedido vai para a
         logística da unidade da cidade (Luís Eduardo Magalhães/Barreiras → Barreiras). A nota fica
         onde foi emitida; só avisa. */
      const nfOutra = !!queryOne(`SELECT id FROM nfe_emitidas WHERE pedido_venda=? AND status='autorizado' AND COALESCE(ambiente,'producao')='producao' AND COALESCE(empresa_id,'')<>? LIMIT 1`, [p.pedido_venda, alvo]);
      if (!soPrevia) db.run('UPDATE pedidos SET empresa_id=? WHERE pedido_venda=?', [alvo, p.pedido_venda]);
      movidos.push({ pedido: p.pedido_venda, cidade: (p.cidade || '') + (!_unidadePelaCidade(p.cidade) && _unidadePeloRep(p.representante) ? ' · rep. ' + p.representante : ''), de: nomes.get(p.empresa_id) || p.empresa_id, para: nomes.get(alvo) || alvo, nf_outra_empresa: nfOutra ? 1 : 0 });
    });
    if (!soPrevia && movidos.length) registrarLog('PEDIDOS MOVIDOS PELA CIDADE', movidos.map(m => `${m.pedido} (${m.cidade}) ${m.de} → ${m.para}`).join(' · ').slice(0, 900), '', '', quem || 'sistema');
    return { movidos, recusados };
  }
  /* v.407: A REGRA DA CIDADE RODA SOZINHA. Pedido de Juazeiro na logística de Simões Filho,
     pedido de Luís Eduardo Magalhães fora de Barreiras — não importa por onde entrou (portal,
     orçamento, edição, remessa): no boot e de meia em meia hora o sistema leva cada pedido
     para a unidade da cidade/representante. Pedido movido à mão (unidade_fixa) não é tocado. */
  function _cidadesUnidadeRotina(){
    try {
      const r = _aplicarCidadesUnidade('sistema (rotina)', false);
      if (r.movidos.length) { salvarArquivo(); console.log(`🏭 ${r.movidos.length} pedido(s) levados para a unidade da cidade: ${r.movidos.slice(0, 8).map(m => m.pedido + '→' + m.para).join(', ')}`); }
    } catch(e) { console.warn('cidades por unidade (rotina):', e && e.message); }
  }
  setTimeout(_cidadesUnidadeRotina, 40000);
  setInterval(_cidadesUnidadeRotina, 30 * 60 * 1000).unref();
  app.post('/api/config/cidades-unidade/aplicar', rota((req, res) => {
    if (!ehDono(req.usuario)) return res.status(403).json({ erro: 'Só o administrador.' });
    const r = _aplicarCidadesUnidade(req.usuario?.nome, !req.body?.confirmar); if (req.body?.confirmar) salvarArquivo(); res.json({ ok: true, previa: req.body?.confirmar ? 0 : 1, ...r });
  }));
  // v.391: as duas Janainas entram na tabela salva (se o dono já tinha editado o card) e os
  // pedidos da Janaina Carla que foram parar em Petrolina pela regra antiga voltam para a matriz
  try {
    if (!queryOne("SELECT 1 FROM fluxo_config WHERE chave='reps_unidade_v391'")) {
      const r = queryOne("SELECT valor FROM fluxo_config WHERE chave='reps_unidade_json'");
      if (r && r.valor) {
        let tab = {}; try { tab = JSON.parse(r.valor) || {}; } catch(e) {}
        tab.emp1 = Array.isArray(tab.emp1) ? tab.emp1 : []; tab.emp2 = Array.isArray(tab.emp2) ? tab.emp2 : [];
        // nome solto "JANAINA" em qualquer unidade era o que confundia as duas — sai
        Object.keys(tab).forEach(k => { tab[k] = (tab[k] || []).filter(x => _normCid(x) !== 'JANAINA'); });
        if (!tab.emp1.some(x => _normCid(x) === 'JANAINA CARLA DA SILVA')) tab.emp1.push('JANAINA CARLA DA SILVA');
        if (!tab.emp2.some(x => _normCid(x) === 'JANAINA DUARTE')) tab.emp2.push('JANAINA DUARTE');
        db.run("UPDATE fluxo_config SET valor=? WHERE chave='reps_unidade_json'", [JSON.stringify(tab)]);
      }
      const movidos = [];
      queryAll("SELECT DISTINCT pedido_venda, cidade, representante FROM pedidos WHERE COALESCE(empresa_id,'emp1')='emp2' AND COALESCE(cancelado,0)=0 AND representante IS NOT NULL").forEach(p => {
        if (!_repBateRegra(p.representante, 'JANAINA CARLA DA SILVA')) return;
        if (_unidadePelaCidade(p.cidade) === 'emp2') return;          // cidade de Petrolina fica lá
        db.run("UPDATE pedidos SET empresa_id='emp1' WHERE pedido_venda=?", [p.pedido_venda]); movidos.push(p.pedido_venda + ' (' + (p.cidade || '') + ')');
      });
      db.run("INSERT INTO fluxo_config (chave, valor) VALUES ('reps_unidade_v391', ?)", [JSON.stringify({ em: new Date().toISOString(), movidos: movidos.length })]);
      if (movidos.length) { registrarLog('PEDIDOS DEVOLVIDOS À MATRIZ (v.391)', movidos.join(' · ').slice(0, 900), 'Janaina Carla da Silva é de Simões Filho — a regra antiga confundia com Janaina Duarte (Petrolina)', '', 'sistema'); console.log(`  🏭 v.391: ${movidos.length} pedido(s) da Janaina Carla devolvido(s) à matriz`); }
      salvarArquivo();
    }
  } catch(e) { console.warn('migração v.391:', e && e.message); }
  // migração única v.363 (refeita na v.380, agora sem a trava da nota): pedidos de Luís Eduardo Magalhães e Barreiras → Barreiras
  try {
    if (!queryOne("SELECT 1 FROM fluxo_config WHERE chave='cidades_unidade_v382'")) {
      db.run("INSERT INTO fluxo_config (chave, valor) VALUES ('cidades_unidade_v382', ?)", [new Date().toISOString()]);
      db.run("DELETE FROM fluxo_config WHERE chave='cidades_unidade_v363'");
      // v.382: JUAZEIRO entra em Petrolina também na tabela já salva pelo card (caso o dono a tenha editado antes)
      try {
        const r = queryOne("SELECT valor FROM fluxo_config WHERE chave='cidades_unidade_json'");
        if (r && r.valor) {
          const tab = JSON.parse(r.valor) || {}; tab.emp2 = Array.isArray(tab.emp2) ? tab.emp2 : [];
          if (!tab.emp2.map(_normCid).includes('JUAZEIRO')) {
            tab.emp2.push('JUAZEIRO');
            db.run("UPDATE fluxo_config SET valor=? WHERE chave='cidades_unidade_json'", [JSON.stringify(tab)]);
          }
        }
      } catch(e) {}
    }
    if (!queryOne("SELECT 1 FROM fluxo_config WHERE chave='cidades_unidade_v363'")) {
      const r = _aplicarCidadesUnidade('sistema (v.363)', false);
      db.run("INSERT INTO fluxo_config (chave, valor) VALUES ('cidades_unidade_v363', ?)", [JSON.stringify({ movidos: r.movidos.length, recusados: r.recusados.length, em: new Date().toISOString() })]);
      if (r.movidos.length) console.log(`  🏭 v.363/380: ${r.movidos.length} pedido(s) movido(s) pela cidade → unidade${r.movidos.some(m => m.nf_outra_empresa) ? ' (' + r.movidos.filter(m => m.nf_outra_empresa).length + ' com nota emitida por outro CNPJ)' : ''}`);
      salvarArquivo();
    }
  } catch(e) { console.warn('migração v.363:', e && e.message); }

  app.get('/api/config/numeracao-unidade', rota((req, res) => {
    const tab = _numeracaoTab();
    const emps = queryAll('SELECT id, nome FROM cp_empresas ORDER BY id') || [];
    res.json({ ok: true, unidades: emps.map(e => { const r = tab[e.id] || null; const px = proximoNumeroPedidoLivre(e.id);
      return { empresa_id: e.id, nome: e.nome, prefixo: r ? r.prefixo : '', largura: r ? r.largura : 0, proximo: px.nr, usa_sequencia_matriz: !r }; }) });
  }));
  app.put('/api/config/numeracao-unidade', rota((req, res) => {
    if (!ehDono(req.usuario)) return res.status(403).json({ erro: 'Só o administrador altera a numeração.' });
    const b = req.body || {}; const tab = {};
    Object.keys(b).forEach(k => { if (k === 'emp1') return; const v = b[k] || {}; tab[k] = { prefixo: String(v.prefixo || '').replace(/\D/g, ''), largura: parseInt(v.largura, 10) || 9 }; });
    db.run("DELETE FROM fluxo_config WHERE chave='numeracao_pedido_json'");
    db.run("INSERT INTO fluxo_config (chave, valor) VALUES ('numeracao_pedido_json', ?)", [JSON.stringify(tab)]);
    registrarLog('NUMERAÇÃO DE PEDIDOS POR UNIDADE', Object.keys(tab).map(u => `${u}: prefixo ${tab[u].prefixo || '(sequência da matriz)'} · ${tab[u].largura} dígitos`).join(' · '), '', '', req.usuario?.nome || 'sistema');
    salvarArquivo(); res.json({ ok: true });
  }));

  // Retorna os dados cadastrais de um cliente (do cadastro fiscal) pela razão social
  app.get('/api/clientes-fiscais/por-nome/:nome', rota((req, res) => {
    const c = queryOne('SELECT * FROM clientes_fiscais WHERE razao_social=? COLLATE NOCASE', [req.params.nome]);
    if (!c) {
      // fallback: pega dados de cabeçalho de um pedido desse cliente
      const p = queryOne('SELECT razao_social, nome_fantasia, cidade, regiao FROM pedidos WHERE razao_social=? COLLATE NOCASE ORDER BY id DESC LIMIT 1', [req.params.nome]);
      return res.json(p || null);
    }
    res.json(c);
  }));

  // Últimos preços praticados por um cliente, por produto (do histórico de pedidos)
  app.get('/api/precos-cliente/:nome', rota((req, res) => {
    const rows = queryAll(`SELECT produto, vlr_unit, id FROM pedidos
      WHERE razao_social=? COLLATE NOCASE AND vlr_unit>0 ORDER BY id DESC`, [req.params.nome]);
    const ultimo = {};
    rows.forEach(r => { if (!(r.produto in ultimo)) ultimo[r.produto] = r.vlr_unit; }); // primeiro = mais recente (ORDER BY id DESC)
    res.json(ultimo);
  }));

  // ─── ORÇAMENTOS (proposta comercial — não gera nota) ─────────────────────────
  app.get('/api/orcamentos/proximo-numero', rota((req, res) => {
    const rows = queryAll('SELECT numero FROM orcamentos');
    let maior = 0;
    rows.forEach(r => { const n = parseInt(String(r.numero).replace(/\D/g,''),10); if (!isNaN(n) && n > maior) maior = n; });
    res.json({ proximo: String(maior + 1).padStart(5,'0') });
  }));

  app.get('/api/orcamentos', rota((req, res) => {
    const f = _filtroUnidade(req);                       // v.290
    const lista = queryAll(`SELECT * FROM orcamentos WHERE 1=1${f.sql} ORDER BY id DESC`, f.params);
    lista.forEach(o => { o.qtd_itens = queryAll('SELECT id FROM orcamento_itens WHERE orcamento_id=?', [o.id]).length; });
    res.json(lista);
  }));

  app.get('/api/orcamentos/:id', rota((req, res) => {
    const o = queryOne('SELECT * FROM orcamentos WHERE id=?', [req.params.id]);
    if (!o) return res.status(404).json({ erro: 'Orçamento não encontrado.' });
    o.itens = queryAll('SELECT produto, quantidade, vlr_unit, valor_total FROM orcamento_itens WHERE orcamento_id=? ORDER BY id', [req.params.id]);
    res.json(o);
  }));

  // Dados do orçamento para impressão (mesmo padrão do pedido)
  app.get('/api/orcamentos/:id/impressao', rota((req, res) => {
    const o = queryOne('SELECT * FROM orcamentos WHERE id=?', [req.params.id]);
    if (!o) return res.status(404).json({ erro: 'Orçamento não encontrado.' });
    const itens = queryAll('SELECT produto, quantidade, vlr_unit FROM orcamento_itens WHERE orcamento_id=? ORDER BY id', [req.params.id]);
    const cli = queryOne('SELECT * FROM clientes_fiscais WHERE razao_social=? COLLATE NOCASE', [o.razao_social]) || {};
    const emit = _emitentePadrao(o.empresa_id);        // v.294: a empresa da unidade do orçamento
    const en = enriquecerItensImpressao(itens, cli, false, emit.uf_emitente);   // v.371
    const rep = queryOne('SELECT * FROM representantes WHERE nome=? COLLATE NOCASE', [o.representante]) || {};
    // validade: data + dias
    let validade = '';
    try {
      const [d,m,a] = (o.data||'').split('/');
      const base = (d&&m&&a) ? new Date(+a, +m-1, +d) : new Date();
      base.setDate(base.getDate() + (+o.validade_dias || 15));
      validade = base.toLocaleDateString('pt-BR');
    } catch(e) {}
    res.json({
      numero: o.numero, data: o.data, validade, validade_dias: o.validade_dias,
      frete: o.frete, obs: o.obs, status: o.status,
      representante: o.representante, representante_codigo: rep.codigo || '',
      cliente: {
        razao_social: o.razao_social, nome_fantasia: o.nome_fantasia || cli.nome_fantasia || '',
        cpf_cnpj: cli.cpf_cnpj || '', ie: cli.ie || '',
        logradouro: cli.logradouro || '', numero: cli.numero || '', bairro: cli.bairro || '',
        municipio: cli.municipio || o.cidade || '', uf: cli.uf || '', cep: cli.cep || '',
        telefone: cli.telefone || '', email: cli.email || '',
        cond_texto: condicaoTexto(o.condicao_pagamento, o.forma_pagamento)
      },
      emitente: {
        nome: emit.nome_emitente || 'USINA MASSA TOP ARGAMASSAS E REVESTIMENT',
        cnpj: emit.cnpj_emitente || '21820732000106', ie: emit.ie_emitente || '122492398',
        logradouro: emit.logradouro_emitente || 'V URBANA', numero: emit.numero_emitente || '2479',
        bairro: emit.bairro_emitente || 'CIA SUL', municipio: emit.municipio_emitente || 'SIMOES FILHO',
        uf: emit.uf_emitente || 'BA', cep: emit.cep_emitente || '43700000',
        email: 'atendimento@massatop.com.br', fone: '(71) 9 9999-6180'
      },
      itens: en.itens,
      total_produtos: en.totalProdutos, total_st: en.totalST, total: en.totalGeral
    });
  }));

  app.post('/api/orcamentos', rota((req, res) => {
    const b = req.body || {};
    if (!b.razao_social || !b.razao_social.trim()) return res.status(400).json({ erro: 'Informe o cliente.' });
    // v.123: condição, forma de pagamento e representante são OBRIGATÓRIOS no orçamento
    if (!String(b.condicao_pagamento||'').trim()) return res.status(400).json({ erro: 'Informe a condição de pagamento.', campo:'condicao_pagamento' });
    if (!String(b.forma_pagamento||'').trim()) return res.status(400).json({ erro: 'Informe a forma de pagamento.', campo:'forma_pagamento' });
    if (!String(b.representante||'').trim()) return res.status(400).json({ erro: 'Informe o representante.', campo:'representante' });
    if (!Array.isArray(b.itens) || !b.itens.length) return res.status(400).json({ erro: 'Adicione ao menos um produto.' });
    for (const it of b.itens) {
      const q = +it.quantidade || 0;
      if (!Number.isInteger(q) || q <= 0)
        return res.status(400).json({ erro: `Quantidade inválida em "${it.produto}": use números inteiros.` });
    }
    let numero = String(b.numero || '').replace(/\D/g,'');
    if (!numero) {
      const rows = queryAll('SELECT numero FROM orcamentos');
      let maior = 0; rows.forEach(r => { const n = parseInt(String(r.numero).replace(/\D/g,''),10); if (!isNaN(n) && n > maior) maior = n; });
      numero = String(maior + 1).padStart(5,'0');
    }
    const total = b.itens.reduce((s,i) => s + (+i.quantidade||0)*(+i.vlr_unit||0), 0);
    db.run(`INSERT INTO orcamentos (numero,data,validade_dias,razao_social,nome_fantasia,cidade,regiao,
              representante,condicao_pagamento,forma_pagamento,frete,obs,valor_total,empresa_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
      [numero, b.data || new Date().toLocaleDateString('pt-BR'), +b.validade_dias || 15,
       b.razao_social.trim(), b.nome_fantasia||'', b.cidade||'', b.regiao||'', b.representante||'',
       b.condicao_pagamento||'', b.forma_pagamento||'', b.frete||'CIF', b.obs||'', +total.toFixed(2),
       _unidadeDoPedidoNovo(req, b.cidade, b.representante)   /* v.363 / v.381 */]);   // v.290
    const id = queryOne('SELECT last_insert_rowid() AS id')?.id;
    b.itens.forEach(it => {
      const qtd = Math.round(+it.quantidade||0), vun = +it.vlr_unit||0;
      db.run('INSERT INTO orcamento_itens (orcamento_id,produto,quantidade,vlr_unit,valor_total) VALUES (?,?,?,?,?)',
        [id, it.produto, qtd, vun, +(qtd*vun).toFixed(2)]);
    });
    registrarLog('CADASTRO DE ORÇAMENTO', `${numero} — ${b.razao_social} — ${b.itens.length} item(ns)`, '', '', req.usuario?.nome || 'sistema');
    salvarArquivo();
    res.json({ ok: true, id, numero, total: +total.toFixed(2) });
  }));

  /* v.282: corrigir um orçamento já salvo, da tela do dono.
     Só enquanto ele NÃO virou pedido — depois disso a proposta e o pedido têm de contar
     a mesma história. O número e a data originais são mantidos. */
  app.put('/api/orcamentos/:id', rota((req, res) => {
    const b = req.body || {};
    const o = queryOne('SELECT * FROM orcamentos WHERE id=?', [req.params.id]);
    if (!o) return res.status(404).json({ erro: 'Orçamento não encontrado.' });
    if (o.pedido_gerado) return res.status(400).json({
      erro: `Este orçamento já virou o pedido ${o.pedido_gerado} — não dá para alterar. Altere o pedido.` });

    if (!String(b.razao_social || '').trim()) return res.status(400).json({ erro: 'Informe o cliente.' });
    if (!String(b.condicao_pagamento||'').trim()) return res.status(400).json({ erro: 'Informe a condição de pagamento.', campo:'condicao_pagamento' });
    if (!String(b.forma_pagamento||'').trim())   return res.status(400).json({ erro: 'Informe a forma de pagamento.', campo:'forma_pagamento' });
    if (!String(b.representante||'').trim())     return res.status(400).json({ erro: 'Informe o representante.', campo:'representante' });
    if (!Array.isArray(b.itens) || !b.itens.length) return res.status(400).json({ erro: 'Adicione ao menos um produto.' });
    for (const it of b.itens) {
      const q = +it.quantidade || 0;
      if (!Number.isInteger(q) || q <= 0)
        return res.status(400).json({ erro: `Quantidade inválida em "${it.produto}": use números inteiros.` });
    }

    const total = b.itens.reduce((s2, i) => s2 + (+i.quantidade||0) * (+i.vlr_unit||0), 0);
    db.run(`UPDATE orcamentos SET validade_dias=?, razao_social=?, nome_fantasia=?, cidade=?, regiao=?,
                                  representante=?, condicao_pagamento=?, forma_pagamento=?, frete=?, obs=?, valor_total=?
             WHERE id=?`,
      [+b.validade_dias || 15, b.razao_social.trim(), b.nome_fantasia||'', b.cidade||'', b.regiao||'',
       b.representante||'', b.condicao_pagamento||'', b.forma_pagamento||'', b.frete||'CIF', b.obs||'',
       +total.toFixed(2), o.id]);
    db.run('DELETE FROM orcamento_itens WHERE orcamento_id=?', [o.id]);
    b.itens.forEach(it => {
      const qtd = Math.round(+it.quantidade||0), vun = +it.vlr_unit||0;
      db.run('INSERT INTO orcamento_itens (orcamento_id,produto,quantidade,vlr_unit,valor_total) VALUES (?,?,?,?,?)',
        [o.id, it.produto, qtd, vun, +(qtd*vun).toFixed(2)]);
    });
    registrarLog('ORÇAMENTO ALTERADO',
      `${o.numero} — ${b.razao_social} — ${b.itens.length} item(ns)`,
      `de ${(+o.valor_total||0).toFixed(2)} para ${total.toFixed(2)}`, '', req.usuario?.nome || 'sistema');
    salvarArquivo();
    res.json({ ok: true, id: o.id, numero: o.numero, total: +total.toFixed(2) });
  }));

  app.put('/api/orcamentos/:id/status', rota((req, res) => {
    const st = (req.body?.status || '').toLowerCase();
    if (!['aberto','aprovado','recusado'].includes(st)) return res.status(400).json({ erro: 'Status inválido.' });
    const o = queryOne('SELECT numero FROM orcamentos WHERE id=?', [req.params.id]);
    if (!o) return res.status(404).json({ erro: 'Orçamento não encontrado.' });
    db.run('UPDATE orcamentos SET status=? WHERE id=?', [st, req.params.id]);
    registrarLog('ORÇAMENTO ' + st.toUpperCase(), o.numero, '', '', req.usuario?.nome || 'sistema');
    salvarArquivo();
    res.json({ ok: true });
  }));

  app.delete('/api/orcamentos/:id', rota((req, res) => {
    const o = queryOne('SELECT numero, pedido_gerado FROM orcamentos WHERE id=?', [req.params.id]);
    if (!o) return res.status(404).json({ erro: 'Orçamento não encontrado.' });
    // Aprovado (virou pedido) pode ser excluído: apaga só a PROPOSTA, o pedido continua no fluxo.
    db.run('DELETE FROM orcamento_itens WHERE orcamento_id=?', [req.params.id]);
    db.run('DELETE FROM orcamentos WHERE id=?', [req.params.id]);
    registrarLog('EXCLUSÃO DE ORÇAMENTO', o.numero, '', '', req.usuario?.nome || 'sistema');
    salvarArquivo();
    res.json({ ok: true });
  }));

  // Fecha o orçamento: vira pedido de verdade (aí sim entra no fluxo normal e pode gerar NF-e)
  app.post('/api/orcamentos/:id/converter-pedido', rota((req, res) => {
    const o = queryOne('SELECT * FROM orcamentos WHERE id=?', [req.params.id]);
    if (!o) return res.status(404).json({ erro: 'Orçamento não encontrado.' });
    if (o.pedido_gerado) return res.status(400).json({ erro: `Este orçamento já virou o pedido ${o.pedido_gerado}.` });
    const itens = queryAll('SELECT produto, quantidade, vlr_unit FROM orcamento_itens WHERE orcamento_id=?', [req.params.id]);
    if (!itens.length) return res.status(400).json({ erro: 'Orçamento sem itens.' });

    // número do pedido: o informado ou o próximo da sequência de pedidos
    let nr = String(req.body?.pedido_venda || '').replace(/\D/g,'');
    const _orcUni = queryOne('SELECT empresa_id, cidade, representante FROM orcamentos WHERE id=?', [req.params.id]) || {};
    const _uniConv = _unidadePelaCidade(_orcUni.cidade) || _unidadePeloRep(_orcUni.representante) || _orcUni.empresa_id || _unidadeDeQuemLanca(req);   // v.340 / v.407: cidade → representante → unidade do orçamento
    if (!nr) nr = proximoNumeroPedidoLivre(_uniConv).nr;
    if (queryOne('SELECT id FROM pedidos WHERE pedido_venda=?', [nr]))
      return res.status(400).json({ erro: `Já existe um pedido com o número ${nr}.` });
    { const _eN = _confereNumeroDaUnidade(nr, _uniConv); if (_eN) return res.status(400).json({ erro: _eN, numero_fora_da_faixa: 1 }); }   // v.340

    // Forma/condição do orçamento (com fallback para o cadastro do cliente)
    const _cliF = queryOne('SELECT condicao_pagamento, forma_pagamento FROM clientes_fiscais WHERE razao_social=? COLLATE NOCASE', [o.razao_social]) || {};
    const _cond  = o.condicao_pagamento || _cliF.condicao_pagamento || '';
    const _forma = o.forma_pagamento    || _cliF.forma_pagamento    || '';
    // MESMA REGRA DO PEDIDO: venda CIF com mais de 50% em AC1 / massa PVA / tinta econômica
    // faz o pedido nascer BLOQUEADO - AGUARDANDO APROVAÇÃO (alguém precisa liberar).
    const _mixOrc = conferirMixCif(o.frete || 'CIF', itens);
    const _bloqOrc = _mixOrc.bloqueia ? 'mix_cif' : '';
    const _bloqMotOrc = _mixOrc.bloqueia
      ? `Venda CIF com ${_mixOrc.percentual}% em AC1/massa PVA/tinta econômica (limite ${_mixOrc.limite}%)`
      : '';
    // Se for à vista (PIX / Transferência / Dinheiro / prazo 0) o pedido NÃO precisa de análise:
    // nasce em AGUARDANDO PAGAMENTO e, após confirmar o recebimento, vai para AGUARDANDO ROTA (logística).
    // Caso contrário (a prazo) mantém a regra antiga: AGUARDANDO ANÁLISE para as consultas cadastrais.
    // O bloqueio do mix CIF tem prioridade sobre os dois.
    const _avista = ehAVista(_cond, _forma);
    let _situacaoOrc, _semAnaliseOrc;
    if (_bloqOrc)      { _situacaoOrc = 'BLOQUEADO - AGUARDANDO APROVAÇÃO'; _semAnaliseOrc = 0; }
    else if (_avista)  { _situacaoOrc = 'AGUARDANDO PAGAMENTO';            _semAnaliseOrc = 0; }
    else               { _situacaoOrc = 'AGUARDANDO ANÁLISE';              _semAnaliseOrc = 1; }
    itens.forEach(it => {
      const qtd = Math.round(+it.quantidade||0), vun = +it.vlr_unit||0;
      const vtot = +(qtd*vun).toFixed(2);
      db.run(`INSERT INTO pedidos (pedido_venda, data, razao_social, nome_fantasia, cidade, regiao,
                produto, quantidade, vlr_unit, valor_total, situacao, frete, obs, representante,
                condicao_pagamento, forma_pagamento, bloqueio, bloqueio_motivo, sem_analise, empresa_id)
              VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
        [nr, new Date().toLocaleDateString('pt-BR'), o.razao_social, o.nome_fantasia, o.cidade, o.regiao,
         it.produto, qtd, vun, vtot, _situacaoOrc, o.frete || 'CIF',
         (o.obs ? o.obs + ' — ' : '') + `Origem: orçamento ${o.numero}`, _grafiaOficialRep(o.representante),
         _cond, _forma, _bloqOrc, _bloqMotOrc, _semAnaliseOrc,
         _uniConv || o.empresa_id || 'emp1']);   // v.290 / v.407: cidade → representante → unidade do orçamento
      db.run('INSERT INTO pedido_itens (pedido_venda, produto, quantidade, vlr_unit, valor_total) VALUES (?,?,?,?,?)',
        [nr, it.produto, qtd, vun, vtot]);
    });
    db.run("UPDATE orcamentos SET status='aprovado', pedido_gerado=? WHERE id=?", [nr, req.params.id]);
    registrarLog('ORÇAMENTO CONVERTIDO EM PEDIDO', `${o.numero} → pedido ${nr} (${_situacaoOrc})`, '', '', req.usuario?.nome || 'sistema');
    salvarArquivo();
    res.json({ ok: true, pedido_venda: nr, itens: itens.length, situacao: _situacaoOrc, aguardando_pagamento: _avista, bloqueado: !!_bloqOrc, bloqueio_motivo: _bloqMotOrc, forma_pagamento: _forma });
  }));

  // ─── REGRA DE MIX EM VENDA CIF ───────────────────────────────────────────────
  // Em venda CIF (frete por nossa conta), os produtos de menor margem — AC1,
  // massa PVA e tinta econômica — não podem passar de 50% do valor do pedido.
  // Passando disso, o pedido nasce BLOQUEADO e depende de aprovação, para que
  // alguém olhe o histórico do cliente antes de liberar.
  const LIMITE_MIX_CIF = 50; // percentual

  function ehProdutoRestrito(desc) {
    const t = (desc || '').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
    if (/\bAC\s*-?\s*1\b|\bACI\b/.test(t) && /ARGAMASSA/.test(t)) return true;  // argamassa AC1
    if (/MASSA\s*PVA/.test(t)) return true;                                     // massa PVA
    if (/TINTA\s*ECONOMICA/.test(t)) return true;                               // tinta econômica
    return false;
  }

  // Retorna { bloqueia, percentual, valorRestrito, total, itens }
  function ehArgamassaACI(desc){
    const t=(desc||'').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
    return (/\bAC\s*-?\s*1\b|\bACI\b/.test(t)) && /ARGAMASSA/.test(t);
  }
  function _maxPrazoCondicao(desc){
    if(!desc) return 0;
    const c = queryOne('SELECT prazos FROM condicoes_pagamento WHERE descricao=? COLLATE NOCASE', [String(desc)]);
    const prazos = (c && c.prazos) ? c.prazos : String(desc);
    const nums = String(prazos).match(/\d+/g) || [];
    let mx=0; nums.forEach(n=>{ const v=parseInt(n,10); if(!isNaN(v)&&v>mx)mx=v; });
    return mx;
  }
  // Regras que fazem o pedido nascer BLOQUEADO aguardando aprovação
  function regrasAprovacaoPedido(itens, condicaoPag){
    const motivos=[];
    const MIN_ACI=7.90;
    const abaixo=(itens||[]).filter(it=>ehArgamassaACI(it.produto) && (+it.vlr_unit||0) < MIN_ACI - 1e-9);
    if(abaixo.length) motivos.push('Argamassa ACI abaixo do preço mínimo (R$ '+MIN_ACI.toFixed(2).replace('.',',')+'): '+abaixo.map(i=>(i.produto+' a R$ '+(+i.vlr_unit||0).toFixed(2).replace('.',','))).join(', '));
    const mx=_maxPrazoCondicao(condicaoPag);
    if(mx>56) motivos.push('Condição de pagamento acima do limite 28/42/56 (máx. 56 dias): '+condicaoPag+' ('+mx+' dias)');
    return { bloqueia: motivos.length>0, motivos };
  }
  // Pedido à vista / confirmação de pagamento:
  // 1) se a FORMA está cadastrada com a flag "à vista" → à vista;
  // 2) senão, fallback: Dinheiro / PIX / Transferência;
  // 3) OU condição de pagamento com prazo 0 dias.
  function ehAVista(condicao, forma){
    const fbruto=String(forma||'').trim();
    if(fbruto){
      try{
        const reg=queryOne('SELECT avista FROM formas_pagamento WHERE descricao=? COLLATE NOCASE AND ativo=1', [fbruto]);
        if(reg) return !!reg.avista;   // respeita o cadastro (à vista ou a prazo)
      }catch(e){}
    }
    const f=fbruto.toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g,''); // tira acento (TRANSFERÊNCIA→TRANSFERENCIA)
    if(f==='DINHEIRO'||f==='PIX'||f.startsWith('TRANSFER')) return true;
    const c=String(condicao||'').trim();
    if(!c) return false;
    return _maxPrazoCondicao(c)===0;
  }
  // Destino de um pedido depois de aprovado/liberado, quando ele está pronto para a logística:
  //  • SPG (não gera nota) → vai direto para AGUARDANDO ROTA.
  //  • NF (SPG=Não) → fica em AGUARDANDO NF e só entra na logística (AGUARDANDO ROTA)
  //    depois que a NF-e for emitida e AUTORIZADA pela SEFAZ.
  //  • Nota mãe (entrega futura) tem fluxo próprio → mantém AGUARDANDO ROTA.
  function situacaoLogistica(spg, notaMae){
    return (spg || notaMae) ? 'AGUARDANDO ROTA' : 'AGUARDANDO NF';
  }

  // ─── PEDIDO EM BOLETO: SÓ VAI PARA A LOGÍSTICA COM OS DOCUMENTOS PRONTOS ──────
  // Cliente que paga em BOLETO só libera o carregamento quando:
  //   • SPG = Não (gera nota) → NF-e AUTORIZADA  +  boleto gerado
  //   • SPG = Sim (não gera nota) → pedido IMPRESSO  +  boleto gerado
  // Enquanto faltar algum, o pedido fica em AGUARDANDO NF / AGUARDANDO BOLETO e não
  // aparece no dashboard nem na sugestão de carga.
  const SIT_AJUSTAVEIS = ['AGUARDANDO ROTA', 'AGUARDANDO NF', 'AGUARDANDO BOLETO'];
  function _boletoResolvido(nr){
    // boleto IMPRESSO (é o que vai junto com a entrega) — libera o pedido
    try { if (queryOne('SELECT id FROM boletos_impressos WHERE pedido_venda=? LIMIT 1', [nr])) return true; } catch(e) {}
    // boleto já enviado ao banco na remessa
    if (queryOne('SELECT id FROM boletos_gerados WHERE pedido_venda=? LIMIT 1', [nr])) return true;
    // boleto dispensado manualmente também libera (o financeiro decidiu não cobrar em boleto)
    if (queryOne('SELECT id FROM boletos_dispensados WHERE pedido_venda=? LIMIT 1', [nr])) return true;
    return false;
  }
  function _pedidoImpresso(nr){
    return !!queryOne('SELECT id FROM boletos_fila WHERE pedido_venda=? LIMIT 1', [nr]);
  }
  function _pedidoEhBoleto(nr, cliente){
    try { return ehFormaBoleto(pagamentoDoPedido(nr, cliente || '').forma); }
    catch(e) { return false; }
  }
  // Situação correta do pedido considerando os documentos já emitidos
  function situacaoLogisticaDoc(nr, spg, notaMae, cliente){
    if (notaMae) return 'AGUARDANDO ROTA';            // nota mãe (entrega futura) tem fluxo próprio
    /* v.319: PEDIDO QUE GERA NOTA NÃO VAI PARA A ROTA SEM A NF-e AUTORIZADA. Ponto.
       A liberação manual ("Liberar") só dispensa o BOLETO — a nota, nunca: mercadoria
       não sai sem nota. Os pedidos da KONKISTI estavam na logística para entregar sem
       nota nenhuma emitida. */
    if (!spg && !temNotaAutorizada(nr)) return 'AGUARDANDO NF';
    // Liberado manualmente pelo gestor → vai para a rota sem exigir o boleto
    try { const _lm = queryOne('SELECT liberado_manual FROM pedidos WHERE pedido_venda=? LIMIT 1', [nr]);
          if (_lm && _lm.liberado_manual) return 'AGUARDANDO ROTA'; } catch(e) {}
    const ehBoleto = _pedidoEhBoleto(nr, cliente);
    if (!spg) {
      if (!temNotaAutorizada(nr)) return 'AGUARDANDO NF';          // falta emitir a nota
      if (ehBoleto && !_boletoResolvido(nr)) return 'AGUARDANDO BOLETO';
      return 'AGUARDANDO ROTA';
    }
    // SPG: não gera nota — precisa do pedido impresso e do boleto
    if (ehBoleto && (!_pedidoImpresso(nr) || !_boletoResolvido(nr))) return 'AGUARDANDO BOLETO';
    return 'AGUARDANDO ROTA';
  }
  // Recalcula e grava a situação de um pedido. NUNCA mexe em pedido já em rota,
  // carregando, entregue, cancelado, bloqueado, em análise ou aguardando pagamento.
  function recalcularSituacaoPedido(nr){
    const pv = String(nr || '').trim(); if (!pv) return null;
    const l0 = queryOne(`SELECT spg, nota_mae, razao_social, situacao, cancelado, bloqueio, sem_analise, ef_remessa,
                                condicao_pagamento, forma_pagamento
                         FROM pedidos WHERE pedido_venda=? LIMIT 1`, [pv]);
    if (!l0) return null;
    if (l0.cancelado || l0.sem_analise || l0.ef_remessa) return null;
    if (l0.bloqueio && String(l0.bloqueio).trim()) return null;
    const atual = String(l0.situacao || '').toUpperCase().trim();
    if (atual === 'AGUARDANDO PAGAMENTO') {
      // Pedido À VISTA continua esperando a confirmação do pagamento (tela da Priscila).
      // Mas se a forma foi trocada para BOLETO/a prazo, ele não é mais à vista e precisa
      // sair daqui, senão fica preso com o botão "Confirmar pagamento" para sempre.
      if (ehAVista(l0.condicao_pagamento || '', l0.forma_pagamento || '')) return null;
    } else if (!SIT_AJUSTAVEIS.includes(atual)) return null;
    const nova = situacaoLogisticaDoc(pv, l0.spg, l0.nota_mae, l0.razao_social);
    if (nova !== l0.situacao) {
      db.run(`UPDATE pedidos SET situacao=? WHERE pedido_venda=?
                AND UPPER(TRIM(situacao)) IN ('AGUARDANDO ROTA','AGUARDANDO NF','AGUARDANDO BOLETO','AGUARDANDO PAGAMENTO')`, [nova, pv]);
      return nova;
    }
    return l0.situacao;
  }
  /* v.336: "POR QUE ESSE PEDIDO NÃO ESTÁ NA LOGÍSTICA?" — o mesmo tipo de resposta que o
     "Verificar" da remessa dá, só que para a rota. Olha unidade, situação gravada,
     cancelado/bloqueio/análise, nota, boleto, liberação manual, e diz o que fazer. */
  function _diagLogistica(nr, req) {
    const p = queryOne(`SELECT pedido_venda, razao_social, situacao, cancelado, bloqueio, sem_analise, ef_remessa, spg, nota_mae,
                               liberado_manual, condicao_pagamento, forma_pagamento, COALESCE(empresa_id,'emp1') AS empresa_id, data, cidade
                        FROM pedidos WHERE pedido_venda=? OR ltrim(pedido_venda,'0')=ltrim(?,'0') ORDER BY id LIMIT 1`, [nr, nr]);
    if (!p) return { encontrado: 0, erro: `Não achei o pedido ${nr} no sistema.` };
    const emp = queryOne('SELECT id, nome FROM cp_empresas WHERE id=?', [p.empresa_id]) || { id: p.empresa_id, nome: p.empresa_id };
    const ativa = _unidadeAtiva(req) || '';
    const empAtiva = ativa ? (queryOne('SELECT nome FROM cp_empresas WHERE id=?', [ativa]) || { nome: ativa }).nome : '';
    const nota = temNotaAutorizada(p.pedido_venda);
    const nf = queryOne(`SELECT numero, status, criado_em FROM nfe_emitidas WHERE pedido_venda=? AND COALESCE(ambiente,'producao')='producao' ORDER BY id DESC LIMIT 1`, [p.pedido_venda]);
    const ehBoleto = _pedidoEhBoleto(p.pedido_venda, p.razao_social);
    const boletoOk = _boletoResolvido(p.pedido_venda);
    const bg = queryAll('SELECT nosso_numero, arquivo_remessa FROM boletos_gerados WHERE pedido_venda=?', [p.pedido_venda]);
    const sitAtual = String(p.situacao || '').toUpperCase().trim();
    const sitCalc = situacaoLogisticaDoc(p.pedido_venda, p.spg, p.nota_mae, p.razao_social);
    const naLogistica = ['AGUARDANDO ROTA', 'ATRASADO', 'CARREGANDO'].includes(sitAtual) && !p.nota_mae;
    const motivos = [], acoes = [];
    /* v.337: NOTA MÃE (entrega futura, CFOP 5922) fica de fora da logística de propósito:
       a mercadoria sai aos poucos, em remessas 5116 — cada remessa é que entra na rota. */
    if (p.nota_mae) {
      motivos.push(`É NOTA MÃE (entrega futura, CFOP 5922): o pedido não vai para a rota — a mercadoria sai em REMESSAS (CFOP 5116), e cada remessa entra na logística quando é emitida. O saldo a entregar fica em "Saldo Entrega Futura".`);
      acoes.push('entrega_futura');
    }
    if (p.cancelado) motivos.push('O pedido está CANCELADO.');
    if (p.sem_analise) { motivos.push('O pedido está AGUARDANDO ANÁLISE (lançado por vendedor e ainda não aprovado).'); acoes.push('aprovar'); }
    if (p.bloqueio && String(p.bloqueio).trim()) { motivos.push(`O pedido está BLOQUEADO: ${String(p.bloqueio).trim()}.`); acoes.push('aprovar'); }
    if (p.ef_remessa) motivos.push('É remessa de entrega futura — segue o fluxo da nota mãe.');
    if (ativa && ativa !== p.empresa_id) { motivos.push(`O pedido é da unidade ${emp.nome}, e a tela está mostrando ${empAtiva}. A logística só lista os pedidos da unidade escolhida no seletor "Unidade".`); acoes.push('unidade'); }
    if (sitAtual === 'PEDIDO ENTREGUE') motivos.push('O pedido já está como PEDIDO ENTREGUE — ele aparece em "Pedidos Entregues", não na fila da logística.');
    if (sitAtual === 'AGUARDANDO PAGAMENTO') { motivos.push('O pedido está AGUARDANDO PAGAMENTO (venda à vista esperando a confirmação do financeiro).'); acoes.push('pagamento'); }
    if (sitAtual === 'AGUARDANDO NF' || (!p.spg && !nota && !p.nota_mae)) { motivos.push('Falta a NF-e AUTORIZADA — pedido que gera nota não vai para a rota sem ela.'); acoes.push('emitir_nfe'); }
    if (!p.cancelado && sitAtual === 'AGUARDANDO BOLETO') {
      if (boletoOk) { motivos.push('A situação gravada é AGUARDANDO BOLETO, mas o boleto já está resolvido (impresso, no banco ou dispensado) — a situação ficou velha.'); acoes.push('recalcular'); }
      else { motivos.push('Falta o boleto: imprima o boleto do pedido (ou gere a remessa), ou use "Liberar" para mandar sem boleto.'); acoes.push('boleto'); }
    }
    if (!p.cancelado && !naLogistica && sitCalc !== sitAtual && ['AGUARDANDO ROTA','AGUARDANDO NF','AGUARDANDO BOLETO'].includes(sitAtual) && !acoes.includes('recalcular')) {
      motivos.push(`A situação gravada é "${p.situacao}" e pelos documentos deveria ser "${sitCalc}".`); acoes.push('recalcular');
    }
    if (!motivos.length) {
      motivos.push(naLogistica
        ? `O pedido ESTÁ na logística como "${p.situacao}" (unidade ${emp.nome}). Se não aparece, confira os filtros da tela (cidade, situação, busca) ou o seletor de unidade.`
        : `Situação gravada: "${p.situacao || '—'}". Não achei um motivo claro — use "Recalcular situação".`);
      if (!naLogistica) acoes.push('recalcular');
    }
    return { encontrado: 1, pedido: p.pedido_venda, cliente: p.razao_social || '', data: p.data || '', cidade: p.cidade || '',
      unidade: emp.id, unidade_nome: emp.nome, unidade_ativa: ativa, unidade_ativa_nome: empAtiva,
      situacao: p.situacao || '', situacao_calculada: sitCalc, na_logistica: naLogistica ? 1 : 0,
      spg: p.spg ? 1 : 0, nota_mae: p.nota_mae ? 1 : 0, cancelado: p.cancelado ? 1 : 0, bloqueio: String(p.bloqueio || ''), sem_analise: p.sem_analise ? 1 : 0,
      liberado_manual: p.liberado_manual ? 1 : 0, forma: p.forma_pagamento || '', condicao: p.condicao_pagamento || '',
      nota: nota ? { status: nota, numero: nf && nf.numero || '', emitida_em: nf && nf.criado_em || '' } : null,
      eh_boleto: ehBoleto ? 1 : 0, boleto_resolvido: boletoOk ? 1 : 0, boletos_no_banco: bg.length,
      arquivo_remessa: (bg.find(b => b.arquivo_remessa) || {}).arquivo_remessa || '',
      motivos, acoes: [...new Set(acoes)] };
  }
  app.get('/api/pedidos/:nr/diagnostico-logistica', rota((req, res) => {
    const nr = String(req.params.nr || '').trim();
    if (!nr) return res.status(400).json({ erro: 'Informe o pedido.' });
    res.json(_diagLogistica(nr, req));
  }));
  app.post('/api/pedidos/:nr/recalcular-situacao', rota((req, res) => {
    const nr = String(req.params.nr || '').trim();
    const antes = queryOne('SELECT situacao FROM pedidos WHERE pedido_venda=? LIMIT 1', [nr]);
    if (!antes) return res.status(404).json({ erro: 'Pedido não encontrado.' });
    const nova = recalcularSituacaoPedido(nr);
    if (nova && nova !== antes.situacao) {
      registrarLog('SITUAÇÃO RECALCULADA', `${nr}: ${antes.situacao} → ${nova}`, 'Pedido pelo diagnóstico da logística (v.336)', '', req.usuario?.nome || 'sistema');
      salvarArquivo();
    }
    res.json({ ok: true, antes: antes.situacao, depois: nova || antes.situacao, mudou: !!(nova && nova !== antes.situacao) });
  }));

  // Libera um pedido preso em AGUARDANDO BOLETO / AGUARDANDO NF direto para a rota.
  // Serve para o boleto impresso fora do sistema (ou antes desta regra existir).
  app.post('/api/pedidos/:nr/liberar-para-rota', rota((req, res) => {
    const nr = String(req.params.nr || '').trim();
    if (!nr) return res.status(400).json({ erro: 'Informe o pedido.' });
    const l0 = queryOne('SELECT situacao, cancelado FROM pedidos WHERE pedido_venda=? LIMIT 1', [nr]);
    if (!l0) return res.status(404).json({ erro: 'Pedido não encontrado.' });
    if (l0.cancelado) return res.status(400).json({ erro: 'Pedido cancelado.' });
    const atual = String(l0.situacao || '').toUpperCase().trim();
    if (!['AGUARDANDO BOLETO', 'AGUARDANDO NF'].includes(atual))
      return res.status(400).json({ erro: `O pedido está em "${l0.situacao}" — a liberação manual vale para quem está aguardando boleto.` });
    /* v.319: sem nota não vai. A liberação manual dispensa só o boleto. */
    if (atual === 'AGUARDANDO NF')
      return res.status(400).json({ erro: `O pedido ${nr} gera NOTA FISCAL e ainda não tem NF-e autorizada. Mercadoria não sai sem nota: emita a NF-e em "Emitir NF-e" e ele entra na logística sozinho.`, precisa_nota: 1 });
    db.run("UPDATE pedidos SET liberado_manual=1, situacao='AGUARDANDO ROTA' WHERE pedido_venda=?", [nr]);
    registrarLog('LIBERAÇÃO MANUAL PARA A ROTA', `${nr} — liberado sem a exigência de nota/boleto`,
      req.body?.motivo || '', '', req.usuario?.nome || 'sistema');
    salvarArquivo();
    res.json({ ok: true, pedido_venda: nr, situacao: 'AGUARDANDO ROTA' });
  }));

  // Recalcula vários pedidos de uma vez (ex.: depois de gerar uma remessa de boletos)
  function recalcularSituacaoPedidos(numeros){
    let n = 0;
    [...new Set((numeros || []).filter(Boolean).map(String))].forEach(nr => { if (recalcularSituacaoPedido(nr)) n++; });
    return n;
  }
  // ─── PEDIDO MÍNIMO POR CIDADE ────────────────────────────────────────────────
  // Cidades próximas (região metropolitana): mínimo R$ 2.000 por pedido.
  // Demais cidades: mínimo R$ 3.000 por pedido.
  const MINIMO_PEDIDO_PADRAO   = 3000;
  const MINIMO_PEDIDO_REDUZIDO = 2000;
  const CIDADES_MINIMO_REDUZIDO = ['SIMOES FILHO', 'LAURO DE FREITAS', 'CAMACARI', 'SALVADOR', 'CANDEIAS'];   // v.224: Candeias é RMS
  function _normCidadeMin(s){
    return String(s||'').toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g,'')
      .replace(/[^A-Z ]/g,' ').replace(/\s+/g,' ').trim();
  }
  /* v.304: MÍNIMO MENOR PARA UM VENDEDOR. O Brito lança pedido pequeno na região
     metropolitana; para ele o mínimo de lá cai de R$ 2.000 para R$ 1.200. Fora da
     metropolitana ele continua com os R$ 3.000 — frete de cidade distante não fecha
     com pedido pequeno. Só vale para quem está nesta lista. */
  const MINIMO_POR_REPRESENTANTE = { 'BRITO': 1200 };
  function _minimoEspecial(usuario, repNome){
    const campos = [usuario && usuario.nome, usuario && usuario.usuario, repNome]
      .map(_normRegraRep).filter(Boolean);
    for (const alvo of Object.keys(MINIMO_POR_REPRESENTANTE)) {
      const a = _normRegraRep(alvo);
      if (campos.some(c => c === a || (' '+c+' ').includes(' '+a+' '))) return MINIMO_POR_REPRESENTANTE[alvo];
    }
    return 0;
  }
  /* v.339: PEDIDO MÍNIMO POR UNIDADE. Petrolina e Barreiras têm mínimo próprio (R$ 1.500
     de início), independente da cidade — a regra de cidade (RMS R$ 2.000 / demais
     R$ 3.000) é da matriz. O valor fica em fluxo_config (minimo_pedido_unidade_json) e
     o gestor ajusta em Configuração NF-e → "Pedido mínimo por unidade". */
  const MINIMO_UNIDADE_PADRAO = { emp2: 1500, emp3: 1500 };
  function _minimoPorUnidadeTab(){
    let tab = {}; try { const r = queryOne("SELECT valor FROM fluxo_config WHERE chave='minimo_pedido_unidade_json'"); if (r && r.valor) tab = JSON.parse(r.valor) || {}; } catch(e) {}
    return Object.assign({}, MINIMO_UNIDADE_PADRAO, tab);
  }
  function minimoDaUnidade(unidade){
    const u = String(unidade || '').trim(); if (!u || u === 'emp1') return 0;
    const v = +(_minimoPorUnidadeTab()[u]); return v > 0 ? v : 0;
  }
  function minimoPedidoCidade(cidade, usuario, repNome, unidade){
    const _mu = minimoDaUnidade(unidade);
    if (_mu > 0) return _mu;                                   // v.339: a unidade manda
    const daCidade = CIDADES_MINIMO_REDUZIDO.includes(_normCidadeMin(cidade))
      ? MINIMO_PEDIDO_REDUZIDO : MINIMO_PEDIDO_PADRAO;
    /* o valor especial só substitui o mínimo REDUZIDO (região metropolitana) */
    if (daCidade !== MINIMO_PEDIDO_REDUZIDO) return daCidade;
    const esp = _minimoEspecial(usuario, repNome);
    return esp > 0 ? esp : daCidade;
  }
  function _minimoTexto(v){
    return 'R$ ' + Number(v||0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
  // ─── REGRA RÍGIDA POR REPRESENTANTE (v.123) ──────────────────────────────────
  // Para estes usuários do portal, PEDIDO MÍNIMO e MIX CIF bloqueiam o lançamento de
  // verdade: NADA é gravado (nem como "aguardando aprovação"). Gestor/admin não é travado.
  const REPS_REGRA_RIGIDA = ['JUNIOR SANTIAGO'];
  const _normRegraRep = s => String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'')
    .toUpperCase().replace(/[^A-Z0-9]+/g,' ').trim();
  function repRegraRigida(usuario, repNome){
    if (ehDono(usuario)) return false;                       // dono/gestor lançando não é travado
    const campos = [usuario && usuario.nome, usuario && usuario.usuario, repNome]
      .map(_normRegraRep).filter(Boolean);
    return REPS_REGRA_RIGIDA.some(alvo => {
      const a = _normRegraRep(alvo);
      return campos.some(c => c === a || (' '+c+' ').includes(' '+a+' '));
    });
  }
  function conferirMixCif(frete, itens) {
    const total = itens.reduce((s, it) => s + ((+it.quantidade||0) * (+it.vlr_unit||0)), 0);
    const restritos = itens.filter(it => ehProdutoRestrito(it.produto));
    const valorRestrito = restritos.reduce((s, it) => s + ((+it.quantidade||0) * (+it.vlr_unit||0)), 0);
    const percentual = total > 0 ? +(valorRestrito / total * 100).toFixed(1) : 0;
    const ehCif = String(frete || 'CIF').toUpperCase() === 'CIF';
    return {
      bloqueia: ehCif && percentual > LIMITE_MIX_CIF,
      ehCif, percentual, limite: LIMITE_MIX_CIF,
      valor_restrito: +valorRestrito.toFixed(2),
      total: +total.toFixed(2),
      itens: restritos.map(it => it.produto)
    };
  }

  // Consulta a regra sem salvar (a tela usa para avisar antes de o usuário confirmar)
  app.post('/api/pedidos/conferir-mix', rota((req, res) => {
    const { frete, itens } = req.body || {};
    if (!Array.isArray(itens)) return res.status(400).json({ erro: 'Itens inválidos.' });
    res.json(conferirMixCif(frete, itens));
  }));

  // Libera um pedido que ficou bloqueado pela regra de mix
  app.post('/api/pedidos/:nr/aprovar', rota((req, res) => {
    const nr = req.params.nr;
    { const t = _travaCreditoAprovacao(String(req.params.nr||'').trim(), req); if (t) return res.status(t.status).json(t.body); }   // v.399
    const linhas = queryAll('SELECT id, bloqueio FROM pedidos WHERE pedido_venda=?', [nr]);
    if (!linhas.length) return res.status(404).json({ erro: 'Pedido não encontrado.' });
    if (!linhas.some(l => l.bloqueio))
      return res.status(400).json({ erro: 'Este pedido não está bloqueado.' });
    const quem = req.usuario?.nome || 'sistema';
    // Libera qualquer tipo de bloqueio (mix CIF, preço mínimo, condição de pagamento).
    // À vista → confirmação de pagamento; a prazo → direto para a rota.
    const _lib = queryOne('SELECT condicao_pagamento, forma_pagamento, spg, nota_mae FROM pedidos WHERE pedido_venda=? LIMIT 1', [nr]) || {};
    const _destinoLib = ehAVista(_lib.condicao_pagamento || '', _lib.forma_pagamento || '') ? 'AGUARDANDO PAGAMENTO' : situacaoLogistica(_lib.spg, _lib.nota_mae);
    // v.271: grava a DATA da aprovação — é o dia em que esta venda entra no faturamento
    const _aprovEm = _isoHoje();
    db.run("UPDATE pedidos SET bloqueio='', bloqueio_motivo='', situacao=?, aprovado_por=?, aprovado_em=? WHERE pedido_venda=?",
      [_destinoLib, quem, _aprovEm, nr]);
    registrarLog('APROVAÇÃO DE PEDIDO BLOQUEADO', `${nr} — liberado por ${quem} em ${_aprovEm.split('-').reverse().join('/')}`,
      req.body?.observacao || '', '', quem);
    try { recalcularSituacaoPedido(nr); } catch(e) {}
    salvarArquivo();
    res.json({ ok: true, aprovado_por: quem });
  }));



  app.post('/api/pedidos/criar-manual', rota((req, res) => {
    const b = req.body || {};
    /* v.375: controle de crédito — bloqueia, reduz o prazo ou só avisa, conforme o atraso do cliente */
    let _avisoCredito = '';
    try {
      const _cr = _aplicarCreditoNoPedido(b.razao_social, b.condicao_pagamento || '', b.forma_pagamento || '', req.usuario, !!b.liberar_credito);
      if (_cr.erro) return res.status(400).json({ erro: _cr.erro, credito_bloqueado: 1, credito: _cr.credito });
      if (_cr.condicao) b.condicao_pagamento = _cr.condicao;
      if (_cr.obs) b.obs = (String(b.obs || '').trim() ? String(b.obs).trim() + ' | ' : '') + _cr.obs;
      _avisoCredito = _cr.aviso || '';
    } catch(e) { console.warn('crédito (manual):', e && e.message); }
    const { pedido_venda, data, razao_social, nome_fantasia, cidade, regiao, representante, frete, obs, itens, spg, condicao_pagamento, forma_pagamento, unidade } = b;
    const notaMae = b.nota_mae ? 1 : 0;   // pedido mãe de venda futura (CFOP 5922)
    if (!pedido_venda || !String(pedido_venda).trim()) return res.status(400).json({ erro: 'Informe o número do pedido.' });
    if (!razao_social || !razao_social.trim()) return res.status(400).json({ erro: 'Informe o cliente (razão social).' });
    if (!Array.isArray(itens) || !itens.length) return res.status(400).json({ erro: 'Adicione ao menos um produto.' });

    const nr = String(pedido_venda).trim();
    const jaExiste = queryOne('SELECT id FROM pedidos WHERE pedido_venda=?', [nr]);
    if (jaExiste) return res.status(400).json({ erro: `Já existe um pedido com o número ${nr}.` });
    { const _eN = _confereNumeroDaUnidade(nr, _unidadeDeQuemLanca(req)); if (_eN) return res.status(400).json({ erro: _eN, numero_fora_da_faixa: 1, proximo: proximoNumeroPedidoLivre(_unidadeDeQuemLanca(req)).nr }); }   // v.340

    /* v.299: o CNPJ da ficha que a tela escolheu. Se a tela não mandou (versão antiga,
       ou pedido lançado por integração), procura no cadastro — e só aceita quando não há
       dúvida, isto é, quando existe UMA ficha com aquela razão social naquela cidade. */
    let _docCliente = String(b.cpf_cnpj || '').replace(/\D/g, '');
    if (!_docCliente) {
      try {
        const _achado = clienteFiscalPref(razao_social.trim(), cidade || '');
        const _mesmoNome = queryAll('SELECT cpf_cnpj FROM clientes_fiscais WHERE razao_social=? COLLATE NOCASE', [razao_social.trim()]) || [];
        if (_achado && _mesmoNome.length === 1) _docCliente = String(_achado.cpf_cnpj || '').replace(/\D/g, '');
      } catch(e) {}
    }

    // Quantidade tem que ser inteira (produtos são vendidos em sacos/unidades)
    for (const it of itens) {
      const q = +it.quantidade || 0;
      if (!Number.isInteger(q) || q <= 0)
        return res.status(400).json({ erro: `Quantidade inválida em "${it.produto}": use números inteiros (sem casas decimais).` });
    }

    // Regra de mix em venda CIF: NÃO impede o lançamento, mas o pedido nasce BLOQUEADO
    // aguardando liberação do gestor.
    const mix = conferirMixCif(frete, itens);
    const _regM = regrasAprovacaoPedido(itens, condicao_pagamento || '');
    const _motM = [];
    if (mix.bloqueia) _motM.push(`Venda CIF com ${mix.percentual}% em AC1/massa PVA/tinta econômica (limite ${mix.limite}%)`);
    _regM.motivos.forEach(m=>_motM.push(m));
    const bloqueio = (mix.bloqueia || _regM.bloqueia) ? (mix.bloqueia ? 'mix_cif' : 'aprovacao') : '';
    const bloqueioMotivo = _motM.join(' | ');
    const _avistaM = ehAVista(condicao_pagamento || '', forma_pagamento || '');
    // REGRA: pedido de REPRESENTANTE/VENDEDOR entra "sem análise" (aba do gestor) — MAS só
    // quando é A PRAZO. Venda À VISTA (PIX/Transferência/Dinheiro) não precisa de análise
    // cadastral e vai direto para AGUARDANDO PAGAMENTO.
    /* v.366: quem precisa de análise é configurável por usuário (Usuários → "Pedidos passam pela
       análise do gestor"). Sem configuração, vale a função: representante/vendedor passa; escritório não. */
    const _ehRepVend = _precisaAnalise(req.usuario);
    const _semAnalise = (_ehRepVend && !_avistaM) ? 1 : 0;
    const _situacaoM = _semAnalise ? 'AGUARDANDO ANÁLISE'
                       : (bloqueio ? 'BLOQUEADO - AGUARDANDO APROVAÇÃO' : (_avistaM ? 'AGUARDANDO PAGAMENTO' : situacaoLogistica(spg, notaMae)));

    /* v.301: venda sem dono não gera comissão para ninguém. Se a tela não informou o
       representante, ele vem da ficha do cliente. */
    const _repGravar = String(representante || '').trim() || _repDoCliente(razao_social, _docCliente, cidade);
    if (!String(representante||'').trim() && _repGravar)
      console.log(`📄 Pedido ${nr}: representante "${_repGravar}" veio do cadastro do cliente.`);

    let totalPedido = 0;
    itens.forEach(it => {
      const qtd = Math.round(+it.quantidade || 0);
      const vun = +it.vlr_unit || 0;
      const vtot = +(qtd * vun).toFixed(2);
      totalPedido += vtot;
      // Cada item vira uma linha na tabela pedidos (mesmo formato dos importados)
      db.run(`INSERT INTO pedidos (pedido_venda, data, razao_social, nome_fantasia, cidade, regiao,
                produto, quantidade, vlr_unit, valor_total, situacao, frete, obs, representante, spg,
                condicao_pagamento, forma_pagamento, unidade, bloqueio, bloqueio_motivo, nota_mae, sem_analise,
                empresa_id, cpf_cnpj)
              VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
        [nr, data || new Date().toLocaleDateString('pt-BR'), razao_social.trim(), nome_fantasia || '',
         cidade || '', regiao || '', it.produto, qtd, vun, vtot,
         _situacaoM,
         frete || 'CIF', obs || '', _repGravar, spg ? 1 : 0,
         condicao_pagamento || '', forma_pagamento || '', unidade || '', bloqueio, bloqueioMotivo, notaMae, _semAnalise,
         _unidadeDoPedidoNovo(req, cidade, _repGravar)   /* v.363 / v.381: cidade → representante → quem lança */,
         _docCliente]);                    // v.299: e com o CNPJ da ficha escolhida
      // Também guarda em pedido_itens (fonte estruturada do pedido manual)
      db.run('INSERT INTO pedido_itens (pedido_venda, produto, quantidade, vlr_unit, valor_total) VALUES (?,?,?,?,?)',
        [nr, it.produto, qtd, vun, vtot]);
    });
    registrarLog('CADASTRO MANUAL DE PEDIDO', `${nr} — ${razao_social} — ${itens.length} item(ns)`, '', '', req.usuario?.nome || 'sistema');
    try { recalcularSituacaoPedido(nr); } catch(e) {}
    salvarArquivo();
    res.json({ ok: true, pedido_venda: nr, aviso_credito: _avisoCredito, itens: itens.length, total: totalPedido, mix, bloqueado: !!bloqueio, aguardando_pagamento: _situacaoM==='AGUARDANDO PAGAMENTO', nota_mae: notaMae, sem_analise: _semAnalise });
  }));

  // ===== Pedidos à vista: AGUARDANDO PAGAMENTO (somente Priscila / dono confirmam) =====
  /* v.351: quem confirma pagamento à vista — Priscila (matriz), Luana (Petrolina) e o dono.
     Luana pediu porque os pedidos à vista de Petrolina ficavam presos esperando a Priscila. */
  const USUARIOS_PAGAMENTO = ['priscila', 'luana'];
  function _ehUsuarioPagamento(u){
    const login = String(u?.usuario||'').toLowerCase();
    return USUARIOS_PAGAMENTO.includes(login) || ehDono(u);
  }
  // Lista os pedidos à vista que estão aguardando confirmação de pagamento
  app.get('/api/pedidos/aguardando-pagamento', rota((req, res) => {
    const linhas = queryAll(`SELECT pedido_venda, data, razao_social, nome_fantasia, cidade, regiao,
              produto, quantidade, vlr_unit, valor_total, situacao, frete, representante,
              condicao_pagamento, forma_pagamento, unidade, spg, obs
            FROM pedidos WHERE situacao='AGUARDANDO PAGAMENTO'${_filtroUnidade(req).sql}
            ORDER BY data, pedido_venda`, _filtroUnidade(req).params);   // v.292
    const porPedido = new Map();
    linhas.forEach(l => {
      const k = String(l.pedido_venda);
      if (!porPedido.has(k)) porPedido.set(k, {
        pedido_venda: k, data: l.data||'', razao_social: l.razao_social||'', nome_fantasia: l.nome_fantasia||'',
        cidade: l.cidade||'', regiao: l.regiao||'', representante: l.representante||'',
        condicao_pagamento: l.condicao_pagamento||'', forma_pagamento: l.forma_pagamento||'',
        unidade: l.unidade||'', spg: l.spg?1:0, obs: l.obs||'', total: 0, itens: [] });
      const p = porPedido.get(k);
      p.total += (+l.valor_total||0);
      p.itens.push({ produto: l.produto, quantidade: l.quantidade, vlr_unit: l.vlr_unit, valor_total: l.valor_total });
    });
    res.json({ ok: true, pedidos: Array.from(porPedido.values()) });
  }));
  // Priscila (ou dono) confirma o pagamento → pedido vai para AGUARDANDO ROTA (tela do Laercio)
  app.post('/api/pedidos/:nr/confirmar-pagamento', rota((req, res) => {
    if (!_ehUsuarioPagamento(req.usuario)) return res.status(403).json({ erro: 'Somente Priscila, Luana ou o administrador podem confirmar o pagamento.' });
    const nr = String(req.params.nr||'').trim();
    const linhas = queryAll("SELECT id FROM pedidos WHERE pedido_venda=? AND situacao='AGUARDANDO PAGAMENTO'", [nr]);
    if (!linhas.length) return res.status(404).json({ erro: 'Pedido não encontrado ou não está aguardando pagamento.' });
    // Pago: se for NF (SPG=Não) ainda espera a emissão da nota (AGUARDANDO NF); SPG vai direto p/ rota.
    const _pg = queryOne("SELECT spg, nota_mae, situacao_antes_pgto FROM pedidos WHERE pedido_venda=? LIMIT 1", [nr]) || {};
    // v.231: se o pagamento tinha sido DESFEITO num pedido já entregue/em rota,
    // ele volta para a mesma situação de antes — a entrega não se perde.
    const _volta = String(_pg.situacao_antes_pgto || '').trim();
    const _destPg = _volta || situacaoLogistica(_pg.spg, _pg.nota_mae);
    db.run("UPDATE pedidos SET situacao=?, situacao_antes_pgto='' WHERE pedido_venda=? AND situacao='AGUARDANDO PAGAMENTO'", [_destPg, nr]);
    if (!_volta) { try { recalcularSituacaoPedido(nr); } catch(e) {} }   // pedido entregue não recalcula
    salvarArquivo();
    registrarLog('CONFIRMAÇÃO DE PAGAMENTO (à vista)', nr, '', '', req.usuario?.nome || 'sistema');
    res.json({ ok: true, pedido_venda: nr, situacao: _destPg });
  }));

  // v.229: DESFAZER de pedido À VISTA. Um botão só, decidindo pelo estado:
  //   • pagamento já confirmado   → volta para AGUARDANDO PAGAMENTO (caiu por engano,
  //     o PIX não entrou, o cliente desistiu…)
  //   • ainda AGUARDANDO PAGAMENTO → libera do à vista e devolve ao fluxo normal,
  //     para poder mudar a forma (ex.: virar boleto) e seguir para a logística.
  app.post('/api/pedidos/:nr/desfazer-avista', rota((req, res) => {
    if (!_ehUsuarioPagamento(req.usuario))
      return res.status(403).json({ erro: 'Somente Priscila, Luana ou o administrador podem desfazer o pagamento à vista.' });
    const nr = String(req.params.nr || '').trim();
    const motivo = String(req.body?.motivo || '').trim();
    const linhas = queryAll('SELECT id, situacao, spg, nota_mae, cancelado FROM pedidos WHERE pedido_venda=?', [nr]);
    if (!linhas.length) return res.status(404).json({ erro: 'Pedido não encontrado.' });
    if (linhas.every(l => l.cancelado)) return res.status(400).json({ erro: 'Este pedido está cancelado.' });
    const _sit = String(linhas[0].situacao || '').toUpperCase();
    // v.231: pedido já carregando/em rota/entregue TAMBÉM pode ter o pagamento
    // desfeito — é onde mais se descobre que o PIX não caiu. A entrega em si não
    // é apagada: o sistema guarda a situação e devolve ao confirmar o pagamento.
    const _jaSaiu = ['CARREGANDO','EM ROTA','ENTREGUE'].some(x => _sit.includes(x));
    if (queryOne("SELECT id FROM boletos_gerados WHERE pedido_venda=? LIMIT 1", [nr]))
      return res.status(400).json({ erro: 'Este pedido tem boleto registrado no banco — use o Desfazer do boleto (baixa CNAB).' });

    const quem = req.usuario?.nome || 'sistema';
    if (_sit === 'AGUARDANDO PAGAMENTO') {
      // libera do à vista: volta ao fluxo normal (aguardando NF ou rota, conforme SPG)
      const _dest = situacaoLogistica(linhas[0].spg, linhas[0].nota_mae);
      db.run("UPDATE pedidos SET situacao=? WHERE pedido_venda=? AND situacao='AGUARDANDO PAGAMENTO'", [_dest, nr]);
      try { recalcularSituacaoPedido(nr); } catch(e) {}
      registrarLog('À VISTA LIBERADO', `${nr} — saiu de AGUARDANDO PAGAMENTO para ${_dest}`, motivo, '', quem);
      salvarArquivo();
      const _sitFim = (queryOne('SELECT situacao FROM pedidos WHERE pedido_venda=? LIMIT 1', [nr]) || {}).situacao || _dest;
      return res.json({ ok: true, acao: 'liberado', pedido_venda: nr, situacao: _sitFim,
        mensagem: `Pedido liberado do à vista — agora está em "${_sitFim}". Use 💳 Pagamento se quiser mudar a forma (ex.: boleto).` });
    }
    // pagamento já confirmado → volta para AGUARDANDO PAGAMENTO
    const _antes = linhas[0].situacao || '';
    db.run("UPDATE pedidos SET situacao='AGUARDANDO PAGAMENTO', situacao_antes_pgto=? WHERE pedido_venda=?",
      [_jaSaiu ? _antes : '', nr]);
    registrarLog('PAGAMENTO À VISTA DESFEITO', `${nr} — voltou para AGUARDANDO PAGAMENTO (estava em ${_antes || '?'})`, motivo, '', quem);
    salvarArquivo();
    res.json({ ok: true, acao: 'desconfirmado', pedido_venda: nr, situacao: 'AGUARDANDO PAGAMENTO',
      volta_para: _jaSaiu ? _antes : '',
      mensagem: 'Pagamento desfeito — o pedido voltou para AGUARDANDO PAGAMENTO.' +
        (_jaSaiu ? ` A entrega não foi apagada: ao confirmar o pagamento, ele volta para "${_antes}".` : '') });
  }));

  // ===== PEDIDOS SEM ANÁLISE (lançados por representante/vendedor) =====
  app.get('/api/pedidos/sem-analise', rota((req, res) => {
    const linhas = queryAll(`SELECT pedido_venda, data, razao_social, nome_fantasia, cidade, regiao,
              produto, quantidade, vlr_unit, valor_total, situacao, frete, representante,
              condicao_pagamento, forma_pagamento, unidade, spg, obs
            FROM pedidos WHERE sem_analise=1 AND (cancelado IS NULL OR cancelado=0)${_filtroUnidade(req).sql}
            ORDER BY data, pedido_venda`, _filtroUnidade(req).params);   // v.292
    const porPedido = new Map();
    linhas.forEach(l => {
      const k = String(l.pedido_venda);
      if (!porPedido.has(k)) porPedido.set(k, {
        pedido_venda: k, data: l.data||'', razao_social: l.razao_social||'', nome_fantasia: l.nome_fantasia||'',
        cidade: l.cidade||'', regiao: l.regiao||'', representante: l.representante||'',
        condicao_pagamento: l.condicao_pagamento||'', forma_pagamento: l.forma_pagamento||'',
        unidade: l.unidade||'', spg: l.spg?1:0, obs: l.obs||'', total: 0, itens: [] });
      const p = porPedido.get(k);
      p.total += (+l.valor_total||0);
      p.itens.push({ produto: l.produto, quantidade: l.quantidade, vlr_unit: l.vlr_unit, valor_total: l.valor_total });
    });
    res.json({ ok: true, pedidos: Array.from(porPedido.values()) });
  }));

  // Gestor aprova a análise → pedido entra no fluxo normal (à vista / bloqueio / aguardando rota)
  /* v.399: pedido de cliente com boleto VENCIDO em aberto (crédito bloqueado) não pode ser
     aprovado — nem na análise, nem na liberação de bloqueio. Devolve 409 credito_bloqueado com o
     detalhe; o administrador libera o crédito do cliente (por prazo) e aí aprova. */
  function _travaCreditoAprovacao(nr, req) {
    try {
      const l = queryOne("SELECT razao_social FROM pedidos WHERE pedido_venda=? LIMIT 1", [nr]); if (!l) return null;
      const c = _creditoDoCliente(l.razao_social);
      if (c.nivel !== 'bloqueado') return null;
      const R = v => 'R$ ' + (+v || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 });
      registrarLog('APROVAÇÃO RECUSADA — CRÉDITO BLOQUEADO', `${nr} — ${l.razao_social}: ${c.qtd} boleto(s) vencido(s), ${R(c.valor)}, maior atraso ${c.dias} dia(s)`, '', '', req.usuario?.nome || 'sistema');
      return { status: 409, body: { erro: `⛔ ${l.razao_social} tem ${c.qtd} boleto(s) VENCIDO(S) em aberto no banco (${R(c.valor)}, o mais antigo há ${c.dias} dia(s)). O pedido ${nr} não pode ser aprovado até o cliente regularizar — ou o administrador liberar o crédito.`, credito_bloqueado: 1, cliente: l.razao_social, credito: { nivel: c.nivel, qtd: c.qtd, valor: c.valor, dias: c.dias, cartorio: c.cartorio || 0 }, pode_liberar: ehDono(req.usuario) ? 1 : 0 } };
    } catch(e) { return null; }
  }
  app.post('/api/pedidos/:nr/aprovar-analise', rota((req, res) => {
    if (!ehDono(req.usuario) && String(req.usuario?.perfil||'').toLowerCase()!=='admin')
      return res.status(403).json({ erro: 'Apenas gestor/administrador pode aprovar a análise.' });
    const nr = String(req.params.nr||'').trim();
    const linhas = queryAll("SELECT * FROM pedidos WHERE pedido_venda=? AND sem_analise=1", [nr]);
    if (!linhas.length) return res.status(404).json({ erro: 'Pedido não encontrado ou já analisado.' });
    { const t = _travaCreditoAprovacao(nr, req); if (t) return res.status(t.status).json(t.body); }   // v.399
    const l0 = linhas[0];
    // Recalcula a situação pelo fluxo normal (mantém eventual bloqueio já marcado)
    const avista = ehAVista(l0.condicao_pagamento || '', l0.forma_pagamento || '');
    const temBloqueio = linhas.some(l => l.bloqueio);
    const nova = temBloqueio ? 'BLOQUEADO - AGUARDANDO APROVAÇÃO' : (avista ? 'AGUARDANDO PAGAMENTO' : situacaoLogistica(l0.spg, l0.nota_mae));
    db.run("UPDATE pedidos SET sem_analise=0, situacao=? WHERE pedido_venda=? AND sem_analise=1", [nova, nr]);
    registrarLog('APROVAÇÃO DE ANÁLISE DE PEDIDO', `${nr} — liberado por ${req.usuario?.nome||'sistema'} → ${nova}`, '', '', req.usuario?.nome || 'sistema');
    try { recalcularSituacaoPedido(nr); } catch(e) {}
    salvarArquivo();
    res.json({ ok: true, pedido_venda: nr, situacao: nova });
  }));

  // Libera para a logística um pedido preso em análise. Usado ao (RE)IMPORTAR o PDF:
  // pedido que vem da importação de PDF já está liberado para carregamento (regra do cliente).
  app.post('/api/pedidos/:nr/liberar-analise', rota((req, res) => {
    const _cargo = String(req.usuario?.cargo || '').toLowerCase();
    if (/representante|vendedor|representa/.test(_cargo) && !ehDono(req.usuario))
      return res.status(403).json({ erro: 'Sem permissão para liberar pedidos.' });
    const nr = String(req.params.nr || '').trim();
    // Pedido vindo de PDF já está LIBERADO para a logística. Se estiver escondido por qualquer
    // motivo (análise, bloqueio, à vista/aguardando pagamento ou cancelado), força para
    // AGUARDANDO ROTA. NÃO mexe em quem já está em rota/carregamento/entregue.
    const linhas = queryAll(`SELECT id FROM pedidos WHERE pedido_venda=? AND (
        sem_analise=1 OR cancelado=1
        OR (bloqueio IS NOT NULL AND TRIM(bloqueio)<>'')
        OR UPPER(situacao) LIKE '%ANÁLISE%' OR UPPER(situacao) LIKE '%ANALISE%'
        OR UPPER(situacao) LIKE '%BLOQUEAD%' OR UPPER(situacao)='AGUARDANDO PAGAMENTO'
      )`, [nr]);
    if (!linhas.length) return res.json({ ok: true, liberado: false });
    db.run(`UPDATE pedidos SET sem_analise=0, bloqueio='', bloqueio_motivo='', cancelado=0,
            situacao='AGUARDANDO ROTA' WHERE pedido_venda=?`, [nr]);
    registrarLog('LIBERAÇÃO DE PEDIDO (importação PDF)', `${nr} — forçado para logística`, '', '', req.usuario?.nome || 'sistema');
    salvarArquivo();
    res.json({ ok: true, liberado: true });
  }));

  // Gestor recusa a análise → cancela o pedido com motivo
  app.post('/api/pedidos/:nr/recusar-analise', rota((req, res) => {
    if (!ehDono(req.usuario) && String(req.usuario?.perfil||'').toLowerCase()!=='admin')
      return res.status(403).json({ erro: 'Apenas gestor/administrador pode recusar a análise.' });
    const nr = String(req.params.nr||'').trim();
    const motivo = String(req.body?.motivo||'').trim() || 'Recusado na análise';
    const linhas = queryAll("SELECT id FROM pedidos WHERE pedido_venda=? AND sem_analise=1", [nr]);
    if (!linhas.length) return res.status(404).json({ erro: 'Pedido não encontrado ou já analisado.' });
    db.run("UPDATE pedidos SET sem_analise=0, cancelado=1, situacao='CANCELADO', cancelamento_motivo=? WHERE pedido_venda=? AND sem_analise=1", [motivo, nr]);
    registrarLog('RECUSA DE ANÁLISE DE PEDIDO', `${nr} — recusado por ${req.usuario?.nome||'sistema'}`, motivo, '', req.usuario?.nome || 'sistema');
    salvarArquivo();
    res.json({ ok: true, pedido_venda: nr, cancelado: true });
  }));

  // Dados completos de um pedido para impressão (layout parecido com o da nota)
  // Diz se um pedido já tem NF-e autorizada. Compara também sem os zeros à esquerda,
  // porque o número do pedido pode estar gravado de formas diferentes nas tabelas.
  function temNotaAutorizada(pedidoNr) {
    const nr = String(pedidoNr || '').trim();
    if (!nr) return null;
    // conta como "com nota" o que já está autorizado ou ainda processando na SEFAZ
    const direto = queryOne(`SELECT status FROM nfe_emitidas
      WHERE pedido_venda=? AND status IN ('autorizado','processando') AND COALESCE(ambiente,'producao')='producao' LIMIT 1`, [nr]);
    if (direto) return direto.status;
    const semZeros = nr.replace(/^0+/, '');
    if (semZeros && semZeros !== nr) {
      const alt = queryOne(`SELECT status FROM nfe_emitidas
        WHERE status IN ('autorizado','processando') AND COALESCE(ambiente,'producao')='producao' AND ltrim(pedido_venda,'0')=? LIMIT 1`, [semZeros]);
      if (alt) return alt.status;
    }
    return null;
  }

  // ─── Apoio à impressão de orçamento e pedido ─────────────────────────────────
  // Condição e forma de pagamento de um PEDIDO. Elas variam a cada venda, por isso
  // ficam no pedido. Pedidos antigos (importados antes dessa mudança) não têm o dado,
  // então caímos no cadastro do cliente como reserva.
  function pagamentoDoPedido(pedidoNr, clienteNome) {
    const linha = pedidoNr
      ? queryOne(`SELECT condicao_pagamento, forma_pagamento, razao_social FROM pedidos
                  WHERE pedido_venda=? AND (condicao_pagamento!='' OR forma_pagamento!='') LIMIT 1`, [pedidoNr])
      : null;
    let condicao = linha?.condicao_pagamento || '';
    let forma    = linha?.forma_pagamento || '';
    if (!condicao || !forma) {
      const nome = clienteNome || linha?.razao_social ||
        queryOne('SELECT razao_social FROM pedidos WHERE pedido_venda=? LIMIT 1', [pedidoNr])?.razao_social;
      if (nome) {
        const cli = queryOne('SELECT condicao_pagamento, forma_pagamento FROM clientes_fiscais WHERE razao_social=? COLLATE NOCASE', [nome]);
        if (!condicao) condicao = cli?.condicao_pagamento || '';
        if (!forma)    forma    = cli?.forma_pagamento || '';
      }
    }
    return { condicao, forma };
  }

  // Classifica o produto num grupo, no estilo do sistema antigo
  function grupoImpressao(desc) {
    const t = (desc||'').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
    if (/REJUNTE/.test(t))               return /RESINAD/.test(t) ? 'REJUNTE RESINADO' : 'REJUNTE BASICO';
    if (/\bAC\s*-?\s*1\b|\bACI\b/.test(t))            return 'ARGAMASSA BASICA';
    if (/\bAC\s*-?\s*[23]\b|PISO\s*S(OBRE)?\s*PISO|\bPSP\b/.test(t)) return 'ARGAMASSA ESPECIAL';
    if (/ARGAMASSA/.test(t))             return 'ARGAMASSA';
    if (/SELADOR/.test(t))               return 'SELADOR';
    if (/TINTA/.test(t))                 return 'TINTA';
    if (/MASSA\s*(PVA|ACRILICA)/.test(t))return 'MASSA';
    if (/GESSO/.test(t))                 return 'GESSO';
    return 'DIVERSOS';
  }

  // Enriquece os itens com código, unidade, grupo e ICMS-ST (mesma regra da NF-e).
  // semST=true (nota mãe / CFOP 5922): não calcula nem mostra ST — o ST vai na remessa (5116).
  function enriquecerItensImpressao(itens, cli, semST, ufEmitente) {
    const clienteSemST = semST || ['2','9'].includes(String(cli?.indicador_ie ?? ''));
    let totalProdutos = 0, totalST = 0;
    const out = itens.map(it => {
      const prod = queryOne('SELECT * FROM produtos_fiscais WHERE descricao=? COLLATE NOCASE', [it.produto]);
      const qtd = +it.quantidade || 0;
      const vun = +it.vlr_unit || 0;
      const merc = +(qtd * vun).toFixed(2);
      let st = 0;
      if (prod && !clienteSemST) {
        const cst = prod.cst_icms || '00';
        if (['10','30','70','90'].includes(cst)) {
          const icmsProprio = +(merc * (prod.aliq_icms || 0) / 100).toFixed(2);
          const baseSt = +(merc * (1 + _mvaDoProduto(prod, ufEmitente)/100) * (1 - (prod.icms_red_bc_st || 0)/100)).toFixed(2);   // v.371
          st = +Math.max(0, (baseSt * (prod.icms_aliq_st || 0)/100) - icmsProprio).toFixed(2);
        }
      }
      totalProdutos += merc;
      totalST += st;
      return {
        codigo: prod?.codigo || '',
        produto: it.produto,
        unidade: prod?.unidade || 'UN',
        grupo: grupoImpressao(it.produto),
        quantidade: qtd,
        vlr_unit: vun,
        vlr_merc: merc,
        vlr_st: st,
        valor_total: merc
      };
    });
    return { itens: out, totalProdutos: +totalProdutos.toFixed(2), totalST: +totalST.toFixed(2),
             totalGeral: +(totalProdutos + totalST).toFixed(2) };
  }

  // Parcelas a partir da condição de pagamento, no formato do sistema antigo
  // (numeração = número do documento + 001, 002...)
  /* v.414: o ICMS-ST vai INTEIRO na 1ª parcela (igual às duplicatas da NF-e e aos boletos);
     só o valor dos produtos é dividido entre as parcelas. O espelho do pedido dividia tudo. */
  function parcelasImpressao(numeroDoc, total, condicaoDesc, st) {
    st = Math.max(0, +st || 0); if (st > total) st = 0;
    const produtos = +(total - st).toFixed(2);
    let dias = [];
    if (condicaoDesc) {
      const cond = queryOne('SELECT prazos FROM condicoes_pagamento WHERE descricao=? COLLATE NOCASE', [condicaoDesc]);
      dias = (cond?.prazos || '').split('/').map(s => parseInt(s.trim(),10)).filter(n => !isNaN(n));
    }
    if (!dias.length) return [];
    dias = ajustarParcelasMinBoleto(dias, total, 'BOLETO');   // valor mínimo por boleto
    const base = new Date();
    const out = []; let acc = 0;
    dias.forEach((d, i) => {
      const fracao = (i < dias.length-1) ? +(produtos/dias.length).toFixed(2) : +(produtos - acc).toFixed(2);
      acc = +(acc + fracao).toFixed(2);
      const valor = i === 0 ? +(fracao + st).toFixed(2) : fracao;   // v.414: ST na primeira
      const v = new Date(base); v.setDate(v.getDate() + d);
      out.push({
        numero: `${String(numeroDoc).replace(/\D/g,'')}${String(i+1).padStart(3,'0')}`,
        vencimento: v.toLocaleDateString('pt-BR'),
        valor, produtos: fracao, st: i === 0 ? st : 0
      });
    });
    return out;
  }

  // Texto da condição no estilo "028/042/056 - BOLETO BANCÁRIO"
  function condicaoTexto(condicaoDesc, formaPagamento) {
    let prazos = '';
    if (condicaoDesc) {
      const cond = queryOne('SELECT prazos FROM condicoes_pagamento WHERE descricao=? COLLATE NOCASE', [condicaoDesc]);
      const dias = (cond?.prazos || '').split('/').map(s => s.trim()).filter(Boolean);
      prazos = dias.map(d => String(d).padStart(3,'0')).join('/');
    }
    const forma = (formaPagamento || '').toUpperCase();
    const formaTxt = ehFormaBoleto(forma) ? 'BOLETO BANCÁRIO' : (forma || '');
    if (prazos && formaTxt) return `${prazos} - ${formaTxt}`;
    if (prazos) return prazos;
    return formaTxt || (condicaoDesc || '');
  }

  app.get('/api/pedidos/:nr/impressao', rota((req, res) => {
    const nr = req.params.nr;
    const linhas = queryAll('SELECT * FROM pedidos WHERE pedido_venda=? ORDER BY id', [nr]);
    if (!linhas.length) return res.status(404).json({ erro: 'Pedido não encontrado.' });
    /* v.310: o PEDIDO pode ser impresso a qualquer hora (a trava da v.306 saiu daqui).
       O que não se imprime antes de aprovar/liberar é o BOLETO — e a resposta diz à tela
       se o pedido está liberado, para ela nem oferecer o boleto quando não está. */
    const _libImp = _pedidoLiberado(nr);
    const cab = linhas[0];
    const cli = clienteFiscalPref(cab.razao_social, cab.cidade) || {};
    const emit = _emitentePadrao(cab.empresa_id);      // v.294: a empresa da unidade do pedido
    const itens = linhas
      .filter(l => l.produto && l.produto !== '-' && !/Nenhum produto/i.test(l.produto))
      .map(l => ({
        produto: l.produto,
        quantidade: l.quantidade || 0,
        vlr_unit: l.vlr_unit || 0
      }));
    const ehNotaMae = linhas.some(l => l.nota_mae);   // nota mãe (5922): espelho sem ST, cobra só produtos
    const ehSpg = linhas.some(l => l.spg);            // SPG: não gera nota → não destaca ICMS ST no espelho
    const en = enriquecerItensImpressao(itens, cli, ehNotaMae || ehSpg, emit.uf_emitente);   // v.371
    const pgtoPed = pagamentoDoPedido(nr, cab.razao_social);
    const parcelas = parcelasImpressao(nr, en.totalGeral, pgtoPed.condicao, en.totalST);   // v.414: ST só na 1ª parcela
    const rep = queryOne('SELECT * FROM representantes WHERE nome=? COLLATE NOCASE', [cab.representante]) || {};
    res.json({
      pedido: nr, data: cab.data, situacao: cab.situacao, frete: cab.frete,
      liberado: _libImp.ok ? 1 : 0, nao_liberado_motivo: _libImp.ok ? '' : _libImp.motivo,   // v.310
      spg: cab.spg ? 1 : 0, unidade: cab.unidade || '',
      obs: cab.obs,
      representante: cab.representante,
      representante_codigo: rep.codigo || '',
      cliente: {
        razao_social: cab.razao_social, nome_fantasia: cab.nome_fantasia || cli.nome_fantasia || '',
        cpf_cnpj: cli.cpf_cnpj || '', ie: cli.ie || '',
        logradouro: cli.logradouro || '', numero: cli.numero || '', bairro: cli.bairro || '',
        municipio: cli.municipio || cab.cidade || '', uf: cli.uf || '', cep: cli.cep || '',
        telefone: cli.telefone || '', email: cli.email || '',
        condicao_pagamento: pgtoPed.condicao || '', forma_pagamento: pgtoPed.forma || '',
        cond_texto: condicaoTexto(pgtoPed.condicao, pgtoPed.forma)
      },
      emitente: {
        nome: emit.nome_emitente || 'USINA MASSA TOP ARGAMASSAS E REVESTIMENT',
        cnpj: emit.cnpj_emitente || '21820732000106', ie: emit.ie_emitente || '122492398',
        logradouro: emit.logradouro_emitente || 'V URBANA', numero: emit.numero_emitente || '2479',
        bairro: emit.bairro_emitente || 'CIA SUL', municipio: emit.municipio_emitente || 'SIMOES FILHO',
        uf: emit.uf_emitente || 'BA', cep: emit.cep_emitente || '43700000',
        email: 'atendimento@massatop.com.br', fone: '(71) 9 9999-6180'
      },
      itens: en.itens,
      total_produtos: en.totalProdutos, total_st: en.totalST, total: en.totalGeral,
      parcelas, banco: ehFormaBoleto(pgtoPed.forma) ? 'ITAU' : ''
    });
  }));

  // Busca de pedidos por período e/ou cliente (para a tela Pedidos)
  // ─── RELATÓRIOS GERENCIAIS ───────────────────────────────────────────────────
  // Converte a data dd/mm/aaaa gravada nos pedidos para Date
  function dataPedido(br) {
    const m = String(br || '').match(/(\d{2})\/(\d{2})\/(\d{4})/);
    return m ? new Date(+m[3], +m[2]-1, +m[1]) : null;
  }

  /* v.331: UMA regra só para "em que dia esta venda entrou". Antes, o Faturamento andava
     pela data de EMISSÃO da nota (v.322) e os relatórios gerenciais (Vendas por Produto,
     Período, Cliente, Comissão) pela data do PEDIDO — e ainda contavam pedido NF que nem
     tinha nota. Resultado: Vendas por Produto R$ 1.500.340 e Faturamento R$ 1.576.023 no
     mesmo mês. Agora todos passam por aqui. */
  function _regraDataFaturamento() {
    const isoToDate = v => { const m = String(v||'').match(/(\d{4})-(\d{2})-(\d{2})/); return m ? new Date(+m[1], +m[2]-1, +m[3]) : null; };
    const brToDate  = v => { const m = String(v||'').match(/(\d{2})\/(\d{2})\/(\d{4})/); return m ? new Date(+m[3], +m[2]-1, +m[1]) : null; };
    const emissao = {};
    queryAll(`SELECT pedido_venda, data_emissao, criado_em FROM nfe_emitidas
               WHERE status='autorizado' AND COALESCE(ambiente,'producao')='producao' AND (ef_modo IS NULL OR ef_modo NOT IN ('devolucao')) ORDER BY id`).forEach(n => {
      const dia = /^\d{4}-\d{2}-\d{2}/.test(String(n.data_emissao||'')) ? String(n.data_emissao).slice(0,10) : String(n.criado_em||'').slice(0,10);
      if (/^\d{4}-\d{2}-\d{2}$/.test(dia)) { const k = String(n.pedido_venda||'').trim(); emissao[k] = dia; emissao[k.replace(/^0+/,'')] = dia; }
    });
    const diaEmissao = pd => { const k = String(pd.pedido_venda||'').trim(); return emissao[k] || emissao[k.replace(/^0+/,'')] || ''; };
    const dataFat = pd => {
      const em = diaEmissao(pd);
      if (em) return isoToDate(em);
      return (/^\d{4}-\d{2}-\d{2}$/.test(String(pd.aprovado_em || '')) ? isoToDate(pd.aprovado_em) : brToDate(pd.data));
    };
    return { diaEmissao, dataFat, esperaNota: _mapaEsperandoNota(), isoToDate, brToDate };
  }

  // Linhas de pedido dentro do período (uma linha por produto)
  // v.292: `req` chega para que os quatro relatórios gerenciais (período, cliente,
  // comissão e produto) saiam da unidade escolhida no topo — todos passam por aqui.
  /* v.406: opts.notaMaeMesSeguinte — para a COMISSÃO, a venda de NOTA MÃE (entrega futura,
     5922) conta no mês SEGUINTE ao do faturamento. O faturamento continua no mês da emissão. */
  function linhasNoPeriodo(de, ate, req, opts) {
    opts = opts || {};
    const _mesSeguinte = d => { if (!d) return d; const y = d.getFullYear(), m = d.getMonth() + 1, ult = new Date(y, m + 1, 0).getDate(); return new Date(y, m, Math.min(d.getDate(), ult)); };
    const dDe  = de  ? new Date(de  + 'T00:00:00') : null;
    const dAte = ate ? new Date(ate + 'T23:59:59') : null;
    const _fu = req ? _filtroUnidade(req) : { sql: '', params: [] };
    const _rf = _regraDataFaturamento();   // v.331: mesma data e mesma regra do Faturamento
    /* v.343: os AJUSTES DE FATURAMENTO (fora do sistema) entram aqui como linha marcada
       (ajuste=1), para o Vendas por Produto/Cliente/Período fecharem com o Faturamento.
       Comissão e "pedidos sem representante" pulam essas linhas. */
    const _ajLinhas = _ajustesFaturamento(_fu.unidade || '', String(de || '').slice(0,10), String(ate || '').slice(0,10)).map(a => ({
      pedido_venda: 'AJUSTE-' + a.id, data: String(a.data).split('-').reverse().join('/'), razao_social: a.descricao || 'Ajuste de faturamento',
      cidade: '', produto: 'AJUSTE DE FATURAMENTO (fora do sistema)', quantidade: 0, vlr_unit: 0, valor_total: +(+a.valor).toFixed(2),
      representante: '', situacao: 'AJUSTE', ef_remessa: 0, ajuste: 1 }));
    const _cf = _sqlClientesFora('razao_social');   // v.416
    return _ajLinhas.concat(queryAll(`SELECT pedido_venda, data, razao_social, cidade, produto, quantidade,
                            vlr_unit, valor_total, representante, situacao, ef_remessa, aprovado_em, nota_mae, forma_pagamento
                     FROM pedidos WHERE pedido_venda IS NOT NULL AND pedido_venda!=''
                       AND (cancelado IS NULL OR cancelado=0)
                       AND (sem_analise IS NULL OR sem_analise=0)
                       -- Pedido BLOQUEADO ainda depende de aprovação: não é venda confirmada
                       AND (bloqueio IS NULL OR TRIM(bloqueio)='')${_fu.sql}${_cf.sql}`, [..._fu.params, ..._cf.params])
      .map(l => {
        // Garante a mesma regra usada na tela: total do item = quantidade × valor unitário.
        const q = +l.quantidade || 0, vu = +l.vlr_unit || 0;
        if (q > 0 && vu > 0) l.valor_total = +(q * vu).toFixed(2);
        return l;
      })
      .filter(l => {
        if (l.ajuste) return true;   // v.343: ajuste já veio filtrado por data/unidade
        if (_clienteFora(l.razao_social)) return false;   // v.416 (com acento também — o SQL pega só sem acento)
        if (!l.produto || l.produto === '-' || /Nenhum produto/i.test(l.produto)) return false;
        // Remessa de entrega futura (5116): produtos já contados na nota mãe → nunca conta como venda.
        // Usa a marca fixa ef_remessa (não a situação, que muda para AGUARDANDO ROTA após emitir).
        if (l.ef_remessa || String(l.situacao||'').toUpperCase() === 'REMESSA') return false;
        // v.331: pedido que gera NF-e só vira venda quando a nota sai (igual ao Faturamento)
        if (_rf.esperaNota.has(String(l.pedido_venda||'').trim())) return false;
        let d = _rf.dataFat(l);   // v.331: dia da emissão da nota → aprovação → pedido
        if (opts.notaMaeMesSeguinte && l.nota_mae) { d = _mesSeguinte(d); l.comissao_mes_seguinte = 1; }   // v.406
        if (dDe  && (!d || d < dDe))  return false;
        if (dAte && (!d || d > dAte)) return false;
        return true;
      }));
  }

  /* v.403: o MODELO DE CUSTO (argamassa e tinta) virou função — o relatório de Vendas
     por Produto e a Previsão de vendas pela matéria-prima usam a mesma conta. */
  function _modeloCustos() {
    // ─── CUSTO POR PRODUTO ────────────────────────────────────────────────────
    // Vem do próprio módulo de Produção:
    //  • Argamassas (AC1/AC2/AC3/PSP) → custo por saco da tela "Custo Argamassa"
    //  • Tintas e massas               → custo por unidade da tela "Custo Tinta"
    //  • Rejunte / gesso / cimentinho  → 40% do preço de venda
    //  • Se houver custo cadastrado em 💰 Preços para o produto, ele tem prioridade.
    const A = k => { const r = queryOne('SELECT valor FROM custos_argamassa WHERE chave=?', [k]); return r ? (+r.valor || 0) : 0; };
    const T = k => { const r = queryOne('SELECT valor FROM custos_tinta WHERE chave=?', [k]); return r ? (+r.valor || 0) : 0; };
    const _semAcento = s => String(s || '').toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
    // Mesma classificação usada nas telas de custo
    function _classificarProduto(desc) {
      const t = _semAcento(desc);
      if (/REJUNTE|GESSO|CIMENTINHO/.test(t)) return { tipo: 'percentual' };
      if (/\bPSP\b|PISO\s*S(OBRE)?\s*PISO|PISO\s*S\/\s*PISO/.test(t)) return { tipo: 'argamassa', codigo: 'PSP' };
      if (/\bAC\s*-?\s*3\b|\bACIII\b|FLEXIVEL/.test(t) && !/SEMI/.test(t)) return { tipo: 'argamassa', codigo: 'AC3' };
      if (/\bAC\s*-?\s*2\b|\bACII\b|SEMI\s*-?\s*FLEXIVEL/.test(t)) return { tipo: 'argamassa', codigo: 'AC2' };
      if (/\bAC\s*-?\s*1\b|\bACI\b/.test(t)) return { tipo: 'argamassa', codigo: 'AC1' };
      if (/SELADOR/.test(t)) return { tipo: 'tinta', codigo: 'SELADOR' };
      if (/MASSA\s*ACRILICA/.test(t)) return { tipo: 'tinta', codigo: 'MASSA_ACRILICA' };
      if (/MASSA\s*(PVA|CORRIDA)/.test(t)) return { tipo: 'tinta', codigo: 'MASSA_PVA' };
      if (/ECONOMICA/.test(t)) return { tipo: 'tinta', codigo: 'TINTA_ECONOMICA' };
      if (/ACRILICA/.test(t)) return { tipo: 'tinta', codigo: 'TINTA_ACRILICA' };
      return { tipo: 'indefinido' };
    }
    // Custo por saco de cada argamassa — mesma conta da tela Custo Argamassa
    const _custoArgCache = new Map();
    function custoArgamassa(codigo) {
      if (_custoArgCache.has(codigo)) return _custoArgCache.get(codigo);
      const sacos = A('PRODUCAO_MENSAL_' + codigo);
      const sacosPorBatida = A('SACOS_POR_BATIDA') || 55;
      const batidas = sacos > 0 ? sacos / sacosPorBatida : 0;
      let custoPorSaco = 0;
      if (sacos > 0) {
        const custoCim = A('CIMENTO_' + codigo) * batidas * A('CUSTO_CIMENTO_KG');
        const custoAre = (A('AREIA_' + codigo) * batidas / 1000) * A('CUSTO_AREIA_TON');
        const custoAdi = A('ADITIVO_' + codigo) * batidas * A('CUSTO_ADITIVO_KG');
        const custoPo = (A('PO_PEDRA_' + codigo) * batidas / 1000) * A('CUSTO_PO_PEDRA_TON');
        const custoEmb = sacos * A('CUSTO_SACO');
        const custoPal = (sacos / (A('SACOS_POR_PALETE') || 100)) * A('CUSTO_PALETE');
        const custoFil = (sacos / (A('SACOS_POR_FILME') || 100)) * A('CUSTO_FILME');
        custoPorSaco = (custoCim + custoAre + custoAdi + custoPo + custoEmb + custoPal + custoFil) / sacos;
      }
      const v = +custoPorSaco.toFixed(2);
      _custoArgCache.set(codigo, v);
      return v;
    }
    // Custo por unidade de cada tinta/massa — mesma conta da tela Custo Tinta
    const _insumosTinta = ['RESINA', 'CALCITA', 'ESPESSANTE', 'BETONITA', 'EMBALAGEM', 'OUTROS'];
    const _custoTintaCache = new Map();
    function custoTinta(codigo) {
      if (_custoTintaCache.has(codigo)) return _custoTintaCache.get(codigo);
      // v.254: custo final informado manda. Quando existe, é ele que vale — a conta
      // por insumo fica como referência na tela de Custo Tinta.
      const informado = T(codigo + '_CUSTO_FINAL');
      if (informado > 0) { _custoTintaCache.set(codigo, informado); return informado; }
      const custoTotal = _insumosTinta.reduce((s, ins) => s + T(codigo + '_' + ins), 0);
      const qtd = T(codigo + '_QTD');
      const v = qtd > 0 ? +(custoTotal / qtd).toFixed(2) : 0;
      _custoTintaCache.set(codigo, v);
      return v;
    }
    return { A, T, _classificarProduto, custoArgamassa, custoTinta, _semAcento };
  }

  /* ═══════ v.403: PREVISÃO DE VENDAS PELA MATÉRIA-PRIMA ═══════
     Pergunta do dono: "com base na matéria-prima lançada para pagar no mês, quanto isso
     gera de vendas em cada empresa?" A base é AREIA, CIMENTO, ADITIVO (argamassa) e
     MP-TINTA (tintas/massas), pelo que está no Contas a Pagar com vencimento no mês.
       • Argamassa: R$ do insumo ÷ custo unitário (tela Custo Argamassa) = quantidade
         comprada; ÷ consumo por saco (kg por batida ÷ sacos por batida, ponderado pelo
         mix do que a unidade vendeu nos últimos 90 dias) = sacos que dá para produzir;
         × preço médio do saco (vendas reais dos 90 dias; sem venda, o preço da tela)
         = vendas. O insumo que rende MENOS sacos é o gargalo — é ele que manda.
       • Tinta: R$ de MP-TINTA ÷ (custo de matéria-prima por unidade ÷ preço médio),
         ponderado pelo mix de tintas/massas vendidas; sem custo cadastrado, usa a
         proporção histórica (vendas de tinta ÷ MP-TINTA lançada nos 90 dias). */
  function _previsaoVendasPorMP(mes) {
    const { A, T, _classificarProduto, custoTinta, _semAcento } = _modeloCustos();
    const tipoCat = nome => {
      const t = _semAcento(nome);
      if (/MP[-\s_]?TINTA|MAT(ERIA)?\.?\s*PRIMA.*TINTA|INSUMO.*TINTA/.test(t)) return 'tinta';
      if (/AREIA|AREAL/.test(t)) return 'areia';
      if (/CIMENTO/.test(t)) return 'cimento';
      if (/ADITIVO/.test(t)) return 'aditivo';
      return '';
    };
    const codigos = ['AC1', 'AC2', 'AC3', 'PSP'];
    const spb = A('SACOS_POR_BATIDA') || 55;
    const custoUnit = { cimento: A('CUSTO_CIMENTO_KG'), areia: A('CUSTO_AREIA_TON'), aditivo: A('CUSTO_ADITIVO_KG') };
    const hoje = agoraBR().slice(0, 10);
    const d90 = new Date(hoje + 'T12:00:00'); d90.setDate(d90.getDate() - 90);
    const de90 = d90.toISOString().slice(0, 10);
    const empresas = queryAll('SELECT id, nome, sigla FROM cp_empresas ORDER BY id');
    const contasMes = queryAll("SELECT empresa_id, categoria, fornecedor, descricao, valor, status, vencimento FROM cp_contas WHERE substr(vencimento,1,7)=? AND LOWER(status)!='aguardando'", [mes]);
    const contas90 = queryAll("SELECT empresa_id, categoria, valor FROM cp_contas WHERE vencimento>=? AND vencimento<=? AND LOWER(status)!='aguardando'", [de90, hoje]);
    const mpTintaUnit = cod => {
      const ins = ['RESINA', 'CALCITA', 'ESPESSANTE', 'BETONITA'].reduce((t, i) => t + T(cod + '_' + i), 0);
      const qtd = T(cod + '_QTD');
      if (ins > 0 && qtd > 0) return +(ins / qtd).toFixed(2);
      return custoTinta(cod);   // sem detalhe por insumo: custo cheio da tela
    };
    const r2 = v => +(+v || 0).toFixed(2);
    const lista = empresas.map(e => {
      const fake = { query: { unidade: e.id }, headers: {} };
      // 1) insumos lançados no mês
      const ins = { areia: { valor: 0, contas: 0 }, cimento: { valor: 0, contas: 0 }, aditivo: { valor: 0, contas: 0 }, tinta: { valor: 0, contas: 0 } };
      const lancamentos = [];
      contasMes.filter(c => (c.empresa_id || 'emp1') === e.id).forEach(c => {
        const t = tipoCat(c.categoria) || tipoCat(c.descricao);
        if (!t) return;
        ins[t].valor += (+c.valor || 0); ins[t].contas++;
        lancamentos.push({ tipo: t, fornecedor: c.fornecedor, descricao: c.descricao, valor: r2(c.valor), vencimento: c.vencimento, status: c.status, categoria: c.categoria });
      });
      // 2) mix dos últimos 90 dias (sacos vendidos por tipo e preço médio)
      const mixArg = {}, mixTinta = {};
      let vendasTinta90 = 0;
      linhasNoPeriodo(de90, hoje, fake).filter(l => !l.ajuste).forEach(l => {
        const cl = _classificarProduto(l.produto);
        const q = +l.quantidade || 0, v = +l.valor_total || 0;
        if (cl.tipo === 'argamassa') { const m = mixArg[cl.codigo] || (mixArg[cl.codigo] = { qtd: 0, valor: 0 }); m.qtd += q; m.valor += v; }
        else if (cl.tipo === 'tinta') { const m = mixTinta[cl.codigo] || (mixTinta[cl.codigo] = { qtd: 0, valor: 0 }); m.qtd += q; m.valor += v; vendasTinta90 += v; }
      });
      let totalArg = codigos.reduce((t, c) => t + ((mixArg[c] || {}).qtd || 0), 0);
      let baseMix = 'vendas_90_dias';
      if (totalArg <= 0) {   // unidade sem venda de argamassa nos 90 dias: mix da produção esperada
        baseMix = 'producao_esperada';
        codigos.forEach(c => { mixArg[c] = { qtd: A('PRODUCAO_MENSAL_' + c), valor: 0 }; });
        totalArg = codigos.reduce((t, c) => t + mixArg[c].qtd, 0);
      }
      const mix = {};
      let kgPorSaco = { cimento: 0, areia: 0, aditivo: 0 }, precoSaco = 0;
      codigos.forEach(c => {
        const m = mixArg[c] || { qtd: 0, valor: 0 };
        const sh = totalArg > 0 ? m.qtd / totalArg : 0;
        const preco = m.qtd > 0 && m.valor > 0 ? m.valor / m.qtd : A('VENDA_' + c);
        mix[c] = { share: +(sh * 100).toFixed(1), qtd: Math.round(m.qtd), preco: r2(preco) };
        kgPorSaco.cimento += sh * A('CIMENTO_' + c) / spb;
        kgPorSaco.areia   += sh * A('AREIA_' + c) / spb;
        kgPorSaco.aditivo += sh * A('ADITIVO_' + c) / spb;
        precoSaco += sh * preco;
      });
      // 3) quantos sacos cada insumo rende, e quanto isso vende
      const insumos = {};
      [['cimento', 'kg', 1], ['areia', 't', 1000], ['aditivo', 'kg', 1]].forEach(([k, unid, fator]) => {
        const valor = r2(ins[k].valor);
        const custo = custoUnit[k];
        const qtd = custo > 0 ? valor / custo : 0;          // kg (cimento/aditivo) ou toneladas (areia)
        const kg = qtd * fator;
        const sacos = kgPorSaco[k] > 0 ? kg / kgPorSaco[k] : 0;
        insumos[k] = { valor, contas: ins[k].contas, custo_unit: custo, unidade: unid, quantidade: +qtd.toFixed(2),
                       kg_por_saco: +kgPorSaco[k].toFixed(3), sacos: Math.round(sacos), vendas: r2(sacos * precoSaco) };
      });
      const comValor = Object.keys(insumos).filter(k => insumos[k].valor > 0 && insumos[k].sacos > 0);
      let gargalo = '', sacosArg = 0;
      if (comValor.length) { gargalo = comValor.sort((a, b) => insumos[a].sacos - insumos[b].sacos)[0]; sacosArg = insumos[gargalo].sacos; }
      const vendasArg = r2(sacosArg * precoSaco);
      // 4) tinta
      const mpTinta = r2(ins.tinta.valor);
      let somaCusto = 0, somaVenda = 0;
      const mixT = {};
      Object.keys(mixTinta).forEach(c => {
        const m = mixTinta[c]; if (m.qtd <= 0) return;
        const cu = mpTintaUnit(c);
        mixT[c] = { qtd: Math.round(m.qtd), preco: r2(m.valor / m.qtd), custo_mp: cu };
        if (cu > 0) { somaCusto += cu * m.qtd; somaVenda += m.valor; }
      });
      let pctTinta = somaVenda > 0 ? somaCusto / somaVenda : 0, baseTinta = 'modelo_custo';
      if (!(pctTinta > 0)) {
        const mp90 = contas90.filter(c => (c.empresa_id || 'emp1') === e.id && tipoCat(c.categoria) === 'tinta').reduce((t, c) => t + (+c.valor || 0), 0);
        if (mp90 > 0 && vendasTinta90 > 0) { pctTinta = mp90 / vendasTinta90; baseTinta = 'historico_90_dias'; }
        else baseTinta = '';
      }
      const vendasTinta = pctTinta > 0 ? r2(mpTinta / pctTinta) : 0;
      // 5) realizado no mês (para comparar)
      const dMes = _cpAutoDatas(mes);
      const realizado = dMes ? r2(linhasNoPeriodo(dMes.de, dMes.ate, fake).filter(l => !l.ajuste).reduce((t, l) => t + (+l.valor_total || 0), 0)) : 0;
      return {
        empresa_id: e.id, empresa: e.nome, sigla: e.sigla || '',
        insumos, gargalo, sacos_por_batida: spb, base_mix: baseMix, mix, preco_medio_saco: r2(precoSaco),
        argamassa: { sacos: sacosArg, vendas: vendasArg },
        tinta: { valor: mpTinta, contas: ins.tinta.contas, pct_custo: +(pctTinta * 100).toFixed(1), base: baseTinta, vendas: vendasTinta, mix: mixT },
        total_mp: r2(ins.areia.valor + ins.cimento.valor + ins.aditivo.valor + ins.tinta.valor),
        vendas_previstas: r2(vendasArg + vendasTinta),
        realizado_mes: realizado,
        lancamentos: lancamentos.sort((a, b) => b.valor - a.valor)
      };
    });
    return {
      mes, de_mix: de90, ate_mix: hoje, lista,
      total_mp: r2(lista.reduce((t, x) => t + x.total_mp, 0)),
      total_vendas: r2(lista.reduce((t, x) => t + x.vendas_previstas, 0)),
      total_realizado: r2(lista.reduce((t, x) => t + x.realizado_mes, 0)),
      parametros: { sacos_por_batida: spb, custo_cimento_kg: custoUnit.cimento, custo_areia_ton: custoUnit.areia, custo_aditivo_kg: custoUnit.aditivo }
    };
  }
  app.get('/api/previsao-mp', rota((req, res) => {
    if (!ehDono(req.usuario)) return res.status(403).json({ erro: 'Só o administrador vê a previsão de vendas pela matéria-prima.' });
    const mes = /^\d{4}-\d{2}$/.test(String(req.query.mes || '')) ? String(req.query.mes) : agoraBR().slice(0, 7);
    try { res.json({ ok: true, ..._previsaoVendasPorMP(mes) }); }
    catch(e) { res.status(500).json({ erro: e.message }); }
  }));

  /* v.401: IMPOSTO (ICMS-ST) do período, por unidade — a conta é a mesma do relatório de
     Vendas por Produto (v.208) e do Faturamento; agora em função porque o lançamento
     automático no Contas a Pagar (dia 09) usa o mesmo número. */
  function _impostoSTPeriodo(de, ate, req) {
    let notas = 0, remessas = 0;
    const _de = /^\d{4}-\d{2}-\d{2}$/.test(String(de||'')) ? String(de) : '';
    const _ate = /^\d{4}-\d{2}-\d{2}$/.test(String(ate||'')) ? String(ate) : '';
    const _fuST = req ? _filtroUnidadeNfe(req) : { sql: '', params: [] };   // v.331 / v.378: só a unidade escolhida (com a filial dela)
    const _anulST = _refsNotasDevolvidas();       // v.331: nota devolvida não tem mais imposto
    const _cfST = _sqlClientesFora('cliente_nome');   // v.416
    queryAll(`SELECT ref, valor_total, criado_em, ef_modo, requisicao_json, cliente_nome FROM nfe_emitidas WHERE status='autorizado' AND COALESCE(ambiente,'producao')='producao'${_fuST.sql}${_cfST.sql}`, [..._fuST.params, ..._cfST.params]).forEach(n => {
      if (_clienteFora(n.cliente_nome)) return;   // v.416
      const dISO = String(n.criado_em||'').slice(0,10);
      if (_de && dISO < _de) return;
      if (_ate && dISO > _ate) return;
      const modo = String(n.ef_modo||'');
      if (modo === 'devolucao') return;
      if (modo === '5116') { remessas += (+n.valor_total||0); return; }
      if (_anulST.has(String(n.ref))) return;
      try {
        const rj = JSON.parse(n.requisicao_json||'{}');
        notas += (rj.items||[]).reduce((s2,i)=>s2+(+i.icms_valor_st||0),0);
      } catch(e) {}
    });
    return { notas: +notas.toFixed(2), remessas: +remessas.toFixed(2), total: +(notas + remessas).toFixed(2) };
  }

  // 1) Vendas por período (agrupado por dia e por mês)
  app.get('/api/relatorios/vendas-periodo', rota((req, res) => {
    const linhas = linhasNoPeriodo(req.query.de, req.query.ate, req);   // v.292
    // v.343: os ajustes de faturamento já vêm de linhasNoPeriodo (linha marcada ajuste=1)
    const porDia = new Map(), porMes = new Map();
    const pedidos = new Set();
    let total = 0, qtdTotal = 0;
    linhas.forEach(l => {
      const v = +l.valor_total || 0, q = +l.quantidade || 0;
      total += v; qtdTotal += q;
      pedidos.add(l.pedido_venda);
      const dia = l.data || 's/ data';
      if (!porDia.has(dia)) porDia.set(dia, { data: dia, pedidos: new Set(), quantidade: 0, valor: 0 });
      const D = porDia.get(dia); D.pedidos.add(l.pedido_venda); D.quantidade += q; D.valor += v;
      const d = dataPedido(l.data);
      const mes = d ? `${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()}` : 's/ data';
      if (!porMes.has(mes)) porMes.set(mes, { mes, pedidos: new Set(), quantidade: 0, valor: 0 });
      const M = porMes.get(mes); M.pedidos.add(l.pedido_venda); M.quantidade += q; M.valor += v;
    });
    const fmt = arr => arr.map(x => ({ ...x, pedidos: x.pedidos.size, valor: +x.valor.toFixed(2) }));
    const dias = fmt([...porDia.values()]).sort((a,b) => {
      const da = dataPedido(a.data), db_ = dataPedido(b.data);
      return (da && db_) ? db_ - da : 0;
    });
    const meses = fmt([...porMes.values()]).sort((a,b) => b.mes.localeCompare(a.mes));
    res.json({ total: +total.toFixed(2), quantidade: qtdTotal, pedidos: pedidos.size, dias, meses });
  }));

  // 2) Vendas por cliente
  app.get('/api/relatorios/vendas-clientes', rota((req, res) => {
    const linhas = linhasNoPeriodo(req.query.de, req.query.ate, req);   // v.292
    const porCliente = new Map();
    let total = 0;
    linhas.forEach(l => {
      const nome = l.razao_social || '(sem cliente)';
      const v = +l.valor_total || 0;
      total += v;
      if (!porCliente.has(nome)) porCliente.set(nome, {
        cliente: nome, cidade: l.cidade || '', representante: l.representante || '',
        pedidos: new Set(), quantidade: 0, valor: 0
      });
      const C = porCliente.get(nome);
      C.pedidos.add(l.pedido_venda);
      C.quantidade += (+l.quantidade || 0);
      C.valor += v;
      if (!C.representante && l.representante) C.representante = l.representante;
    });
    const lista = [...porCliente.values()]
      .map(c => ({ ...c, pedidos: c.pedidos.size, valor: +c.valor.toFixed(2),
                   ticket: c.pedidos.size ? +(c.valor / c.pedidos.size).toFixed(2) : 0 }))
      .sort((a,b) => b.valor - a.valor);
    res.json({ total: +total.toFixed(2), clientes: lista.length, lista });
  }));

  // Pedidos faturados como BONIFICAÇÃO / doação / brinde (CFOP 5910 ou 6910 interestadual)
  // NÃO geram comissão de vendas — é uma remessa gratuita, não uma venda.
  function _pedidosSemComissaoPorCfop(){
    const set = new Set();
    queryAll("SELECT pedido_venda, requisicao_json FROM nfe_emitidas WHERE status IN ('autorizado','processando') AND COALESCE(ambiente,'producao')='producao' AND requisicao_json LIKE '%910%'").forEach(n => {
      if (!n.pedido_venda) return;
      try {
        const rj = JSON.parse(n.requisicao_json || '{}');
        const items = rj.items || [];
        if (items.some(it => ['5910','6910'].includes(String(it.cfop||'').replace(/\D/g,'')))) set.add(String(n.pedido_venda));
      } catch(e) {}
    });
    return set;
  }

  /* v.301: PEDIDOS ÓRFÃOS — quem seria o representante de cada um.
     Só LISTA; não muda nada. A confirmação é uma chamada separada, porque acertar o
     representante de venda já faturada mexe em comissão a pagar. */
  function _pedidosSemRepresentante(de, ate, req){
    const linhas = linhasNoPeriodo(de, ate, req).filter(l => !l.ajuste);   // v.343
    const porPedido = new Map();
    linhas.forEach(l => {
      if (String(l.representante || '').trim()) return;
      const nr = String(l.pedido_venda || '');
      if (!nr) return;
      if (!porPedido.has(nr)) porPedido.set(nr, { pedido_venda: nr, data: l.data || '',
        cliente: l.razao_social || '', cidade: l.cidade || '', cpf_cnpj: l.cpf_cnpj || '', valor: 0 });
      porPedido.get(nr).valor += (+l.valor_total || 0);
    });
    const saida = [];
    porPedido.forEach(p => {
      p.valor = +p.valor.toFixed(2);
      p.representante_sugerido = _repDoCliente(p.cliente, p.cpf_cnpj, p.cidade);
      saida.push(p);
    });
    return saida.sort((a,b) => b.valor - a.valor);
  }

  app.get('/api/relatorios/pedidos-sem-representante', rota((req, res) => {
    const lista = _pedidosSemRepresentante(req.query.de, req.query.ate, req);
    const comDono = lista.filter(p => p.representante_sugerido);
    const semDono = lista.filter(p => !p.representante_sugerido);
    /* quanto de comissão cada acerto geraria, pela tabela do representante */
    const tabela = new Map();
    queryAll('SELECT id, nome FROM representantes').forEach(r => {
      const m = {};
      queryAll('SELECT grupo, percentual FROM representante_comissoes WHERE representante_id=?', [r.id])
        .forEach(c => { m[c.grupo] = +c.percentual || 0; });
      tabela.set(String(r.nome || '').toUpperCase(), m);
    });
    const linhas = linhasNoPeriodo(req.query.de, req.query.ate, req);
    const _porNr = new Map(comDono.map(p => [p.pedido_venda, p]));
    comDono.forEach(p => { p.comissao_estimada = 0; });
    linhas.forEach(l => {
      const p = _porNr.get(String(l.pedido_venda || ''));
      if (!p) return;
      const pct = tabela.get(String(p.representante_sugerido).toUpperCase())?.[grupoDoProduto(l.produto)] || 0;
      p.comissao_estimada = +(p.comissao_estimada + (+l.valor_total || 0) * pct / 100).toFixed(2);
    });
    res.json({
      com_sugestao: comDono, sem_sugestao: semDono,
      resumo: {
        pedidos: lista.length,
        valor: +lista.reduce((t,p)=>t+p.valor,0).toFixed(2),
        acertaveis: comDono.length,
        valor_acertavel: +comDono.reduce((t,p)=>t+p.valor,0).toFixed(2),
        comissao_estimada: +comDono.reduce((t,p)=>t+(p.comissao_estimada||0),0).toFixed(2)
      }
    });
  }));

  app.post('/api/relatorios/pedidos-sem-representante/aplicar', rota((req, res) => {
    const pedidos = Array.isArray(req.body && req.body.pedidos) ? req.body.pedidos.map(String) : null;
    const lista = _pedidosSemRepresentante(req.body && req.body.de, req.body && req.body.ate, req)
      .filter(p => p.representante_sugerido)
      .filter(p => !pedidos || pedidos.includes(p.pedido_venda));
    if (!lista.length) return res.json({ ok:true, alterados:0, detalhe:[] });
    const detalhe = [];
    lista.forEach(p => {
      /* só grava onde ainda está vazio — se alguém preencheu no meio do caminho, respeita */
      db.run("UPDATE pedidos SET representante=? WHERE pedido_venda=? AND COALESCE(TRIM(representante),'')=''",
        [p.representante_sugerido, p.pedido_venda]);
      detalhe.push({ pedido_venda: p.pedido_venda, cliente: p.cliente,
                     representante: p.representante_sugerido, valor: p.valor });
    });
    registrarLog('REPRESENTANTE PREENCHIDO EM PEDIDOS',
      detalhe.length + ' pedido(s): ' + detalhe.slice(0,12).map(d => d.pedido_venda + '→' + d.representante).join(' · ')
        + (detalhe.length > 12 ? ' …' : ''),
      'Vieram sem representante; preenchido pelo cadastro do cliente', '', req.usuario?.nome || 'sistema');
    salvarArquivo();
    res.json({ ok:true, alterados: detalhe.length, detalhe });
  }));

  // 3) Comissão por representante (usa a comissão por grupo de produto)
  /* v.401: a conta da comissão virou função — a tela de relatório e o lançamento
     automático no Contas a Pagar (dia 25) usam EXATAMENTE a mesma regra. */
  function _comissaoRepresentantes(de, ate, req, q) {
    q = q || {};
    const linhas = linhasNoPeriodo(de, ate, req, { notaMaeMesSeguinte: true }).filter(l => !l.ajuste);   // v.292 / v.343: ajuste não gera comissão · v.406: nota mãe no mês seguinte
    const semComissao = _pedidosSemComissaoPorCfop();   // bonificação (CFOP 5910/6910)
    // Pedidos marcados como "não gera comissão" (ex.: re-entrega de material que faltou)
    queryAll("SELECT DISTINCT pedido_venda FROM pedidos WHERE sem_comissao=1").forEach(r => semComissao.add(String(r.pedido_venda)));
    // comissões cadastradas: representante → { grupo: percentual }
    const tabela = new Map();
    queryAll('SELECT id, nome FROM representantes').forEach(r => {
      const m = {};
      queryAll('SELECT grupo, percentual FROM representante_comissoes WHERE representante_id=?', [r.id])
        .forEach(c => { m[c.grupo] = +c.percentual || 0; });
      tabela.set((r.nome || '').toUpperCase(), m);
    });

    const porRep = new Map();
    let totalVendas = 0, totalComissao = 0;
    // v.242: detalhamento por CLIENTE (vendedor → cliente → produtos), no formato
    // do relatório que o escritório já usa. Só é montado quando a tela pede.
    const _detCliente = ['1','true','sim'].includes(String(q.detalhar_cliente || '').toLowerCase());
    // v.243: filtro por representante — aceita a grafia curta ou a oficial (nomeBateRep)
    const _repFiltro = String(q.representante || '').trim();
    let vendasPermuta = 0;
    linhas.forEach(l => {
      if (semComissao.has(String(l.pedido_venda))) return;   // bonificação CFOP 5910/6910: não gera comissão
      if (/PERMUTA/i.test(String(l.forma_pagamento || ''))) { vendasPermuta += (+l.valor_total || 0); return; }   // v.417: permuta não gera comissão
      const rep = l.representante || '(sem representante)';
      if (_repFiltro && !(rep === _repFiltro || nomeBateRep(rep, _repFiltro))) return;   // v.243
      const v = +l.valor_total || 0;
      const grupo = grupoDoProduto(l.produto);
      const pct = tabela.get(rep.toUpperCase())?.[grupo] || 0;
      const com = +(v * pct / 100).toFixed(2);
      totalVendas += v; totalComissao += com;
      if (!porRep.has(rep)) porRep.set(rep, { representante: rep, vendas: 0, comissao: 0, vendas_nota_mae: 0, grupos: new Map(), clientes: new Map() });
      const R = porRep.get(rep);
      R.vendas += v; R.comissao += com;
      if (l.comissao_mes_seguinte) R.vendas_nota_mae += v;   // v.406: venda de nota mãe do mês anterior
      if (!R.grupos.has(grupo)) R.grupos.set(grupo, { grupo, percentual: pct, vendas: 0, comissao: 0 });
      const G = R.grupos.get(grupo);
      G.vendas += v; G.comissao += com; G.percentual = pct;
      if (_detCliente) {
        const cli = l.razao_social || '(sem cliente)';
        if (!R.clientes.has(cli)) R.clientes.set(cli, { cliente: cli, vendas: 0, comissao: 0, quantidade: 0, produtos: new Map(), pedidos: new Set() });
        const C = R.clientes.get(cli);
        const q = +l.quantidade || 0;
        C.vendas += v; C.comissao += com; C.quantidade += q; C.pedidos.add(String(l.pedido_venda));
        const kp = String(l.produto || '(sem produto)');
        if (!C.produtos.has(kp)) C.produtos.set(kp, { produto: kp, quantidade: 0, vendas: 0, comissao: 0, percentual: pct });
        const P = C.produtos.get(kp);
        P.quantidade += q; P.vendas += v; P.comissao += com; P.percentual = pct;
      }
    });

    const lista = [...porRep.values()].map(r => ({
      representante: r.representante,
      vendas: +r.vendas.toFixed(2),
      comissao: +r.comissao.toFixed(2),
      vendas_nota_mae: +r.vendas_nota_mae.toFixed(2),   // v.406
      grupos: [...r.grupos.values()]
        .map(g => ({ ...g, vendas: +g.vendas.toFixed(2), comissao: +g.comissao.toFixed(2) }))
        .sort((a,b) => b.vendas - a.vendas),
      // v.242: quebra por cliente, com os produtos de cada um
      clientes: _detCliente ? [...r.clientes.values()].map(c => ({
        cliente: c.cliente,
        pedidos: c.pedidos.size,
        quantidade: +c.quantidade.toFixed(3),
        vendas: +c.vendas.toFixed(2),
        comissao: +c.comissao.toFixed(2),
        produtos: [...c.produtos.values()].map(p => ({
          produto: p.produto,
          quantidade: +p.quantidade.toFixed(3),
          vendas: +p.vendas.toFixed(2),
          preco_medio: p.quantidade > 0 ? +(p.vendas / p.quantidade).toFixed(2) : 0,
          percentual: p.percentual,
          comissao: +p.comissao.toFixed(2)
        })).sort((a,b) => b.vendas - a.vendas)
      })).sort((a,b) => b.vendas - a.vendas) : undefined
    })).sort((a,b) => b.comissao - a.comissao);
    return { total_vendas: +totalVendas.toFixed(2), total_comissao: +totalComissao.toFixed(2),
             vendas_nota_mae: +lista.reduce((t, r) => t + (r.vendas_nota_mae || 0), 0).toFixed(2),   // v.406
             regra_nota_mae: 'venda de nota mãe (entrega futura) entra na comissão no mês seguinte ao faturamento',
             vendas_permuta: +vendasPermuta.toFixed(2),   // v.417: vendas em permuta (fora da comissão)
             detalhado_por_cliente: _detCliente ? 1 : 0, representante: _repFiltro || '', lista };
  }
  app.get('/api/relatorios/comissao-representante', rota((req, res) => {
    res.json(_comissaoRepresentantes(req.query.de, req.query.ate, req,
      { detalhar_cliente: req.query.detalhar_cliente, representante: req.query.representante }));
  }));

  // 4) Vendas por produto, agrupadas por categoria
  // Vendas por produto POR DIA, agrupado por grupo de produto (Argamassas, Tintas e Massas,
  // Rejuntes, Outros): para cada dia de venda, o somatório do que foi vendido de cada produto.
  app.get('/api/relatorios/vendas-produtos', rota((req, res) => {
    // TODO o período somado por produto (sem quebrar por dia), agrupado por categoria.
    const linhas = linhasNoPeriodo(req.query.de, req.query.ate, req);   // v.292
    const { A, T, _classificarProduto, custoArgamassa, custoTinta } = _modeloCustos();   // v.403
    // Custo informado manualmente em 💰 Preços (tem prioridade quando existir)
    const _tabCustos = queryAll('SELECT produto, custo FROM precos_produtos WHERE custo>0');
    const _normP = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().replace(/\s+/g, ' ').trim();
    function custoCadastrado(nome) {
      const chave = _normP(nome);
      const palavras = new Set(chave.split(/\s+/).filter(Boolean));
      let melhor = 0, maior = 0;
      _tabCustos.forEach(p => {
        const pNorm = _normP(p.produto);
        if (pNorm === chave) { if (pNorm.length + 100 > maior) { melhor = +p.custo || 0; maior = pNorm.length + 100; } }
        else {
          const pw = pNorm.split(/\s+/).filter(Boolean);
          if (!pw.length) return;
          if (pw.every(w => palavras.has(w)) && pNorm.length > maior) { melhor = +p.custo || 0; maior = pNorm.length; }
        }
      });
      return melhor;
    }
    const PCT_CUSTO_REJUNTE = 0.40;   // rejunte, gesso e cimentinho: custo = 40% da venda
    const _cacheCusto = new Map();
    // precoMedio é usado só no caso percentual (40% do valor de venda)
    function custoDoProduto(nome, precoMedio) {
      const chave = _normP(nome) + '|' + (precoMedio || 0);
      if (_cacheCusto.has(chave)) return _cacheCusto.get(chave);
      let custo = custoCadastrado(nome), origem = custo > 0 ? 'cadastro' : '';
      if (!custo) {
        const cl = _classificarProduto(nome);
        if (cl.tipo === 'argamassa') { custo = custoArgamassa(cl.codigo); origem = 'argamassa'; }
        else if (cl.tipo === 'tinta') { custo = custoTinta(cl.codigo); origem = 'tinta'; }
        else if (cl.tipo === 'percentual') { custo = +((+precoMedio || 0) * PCT_CUSTO_REJUNTE).toFixed(2); origem = '40%'; }
      }
      const r = { custo: +custo || 0, origem };
      _cacheCusto.set(chave, r);
      return r;
    }
    const categorias = new Map();
    const diasComVenda = new Set();
    let total = 0, qtdTotal = 0;
    linhas.forEach(l => {
      const v = +l.valor_total || 0, q = +l.quantidade || 0;
      total += v; qtdTotal += q;
      const dataBR = String(l.data || '').trim();
      if (dataBR) diasComVenda.add(dataBR);
      const cat = l.ajuste ? 'AJUSTES (FORA DO SISTEMA)' : categoriaProduto(l.produto);   // v.343
      if (!categorias.has(cat)) categorias.set(cat, { categoria: cat, quantidade: 0, valor: 0, produtos: new Map() });
      const C = categorias.get(cat);
      C.quantidade += q; C.valor += v;
      const nome = (l.produto || '').trim();
      if (!C.produtos.has(nome)) C.produtos.set(nome, { produto: nome, quantidade: 0, valor: 0 });
      const P = C.produtos.get(nome);
      P.quantidade += q; P.valor += v;
    });
    const ordemCat = { 'ARGAMASSAS': 1, 'TINTAS E MASSAS': 2, 'REJUNTES': 3, 'OUTROS': 4, 'AJUSTES (FORA DO SISTEMA)': 5 };
    // Preço médio praticado = valor vendido ÷ quantidade vendida
    const _medio = (valor, qtd) => (+qtd > 0 ? +((+valor) / (+qtd)).toFixed(2) : 0);
    const cats = [...categorias.values()]
      .map(c => {
        const produtos = [...c.produtos.values()]
          .map(p => {
            const medio = _medio(p.valor, p.quantidade);
            const { custo, origem } = custoDoProduto(p.produto, medio);
            const dif = custo > 0 ? +(medio - custo).toFixed(2) : 0;
            const qtd = +p.quantidade || 0;
            return {
              ...p, valor: +p.valor.toFixed(2), preco_medio: medio,
              custo, custo_origem: origem, diferenca: dif,
              // margem sobre o preço de venda (quanto do preço médio sobra acima do custo)
              diferenca_pct: (custo > 0 && medio > 0) ? +((dif / medio) * 100).toFixed(1) : null,
              // gasto com matéria-prima deste produto no período e o que sobrou
              custo_total: custo > 0 ? +(custo * qtd).toFixed(2) : 0,
              ganho_total: custo > 0 ? +(dif * qtd).toFixed(2) : 0
            };
          })
          .sort((a, b) => b.quantidade - a.quantidade || b.valor - a.valor);
        // Gasto com insumos do segmento e o que sobra depois de pagar a matéria-prima
        const custoSeg = +produtos.reduce((s, p) => s + (+p.custo_total || 0), 0).toFixed(2);
        const valorSeg = +c.valor.toFixed(2);
        const _ehAjuste = c.categoria === 'AJUSTES (FORA DO SISTEMA)';   // v.343: ajuste não tem custo nem entra no aviso
        const semCusto = _ehAjuste ? 0 : +produtos.filter(p => !(p.custo > 0)).reduce((s, p) => s + (+p.valor || 0), 0).toFixed(2);
        return {
          categoria: c.categoria, quantidade: c.quantidade, valor: valorSeg,
          preco_medio: _medio(c.valor, c.quantidade),
          custo_total: custoSeg,
          lucro_bruto: +(valorSeg - custoSeg).toFixed(2),
          margem_pct: valorSeg > 0 ? +(((valorSeg - custoSeg) / valorSeg) * 100).toFixed(1) : null,
          valor_sem_custo: semCusto,
          produtos
        };
      })
      .sort((a, b) => (ordemCat[a.categoria] || 9) - (ordemCat[b.categoria] || 9));
    // Consolidado do período
    const custoGeral = +cats.reduce((s, c) => s + (+c.custo_total || 0), 0).toFixed(2);
    const semCustoGeral = +cats.reduce((s, c) => s + (+c.valor_sem_custo || 0), 0).toFixed(2);
    const lucroGeral = +(total - custoGeral).toFixed(2);
    // v.208: IMPOSTO (ICMS-ST) do período — mesma conta do relatório de Faturamento.
    // Nota normal: o ST vem dos itens da requisição; remessa 5116: o valor da nota JÁ É só ST.
    const { notas: _stNotas, remessas: _stRem, total: _stTotal } = _impostoSTPeriodo(req.query.de, req.query.ate, req);   // v.401: mesma conta, em função
    res.json({ total: +total.toFixed(2), quantidade: qtdTotal, preco_medio: _medio(total, qtdTotal),
               dias_com_venda: diasComVenda.size,
               custo_total: custoGeral,
               lucro_bruto: lucroGeral,
               margem_pct: total > 0 ? +((lucroGeral / total) * 100).toFixed(1) : null,
               valor_sem_custo: semCustoGeral,
               // v.208: imposto do período e faturamento com ele somado
               imposto_st: _stTotal, imposto_st_notas: +_stNotas.toFixed(2), imposto_st_remessas: +_stRem.toFixed(2),
               total_com_imposto: +(total + _stTotal).toFixed(2),
               categorias: cats });
  }));

  // ─── CANCELAMENTO DE PEDIDO ──────────────────────────────────────────────────
  // Cancelar preserva o histórico (quem, quando e por quê), diferente de excluir.
  /* v.325: mover um pedido para outra unidade (quando nasceu na errada) */
  app.post('/api/pedidos/:nr/unidade', rota((req, res) => {
    const nr = String(req.params.nr || '').trim();
    const emp = String(req.body?.empresa_id || '').trim();
    if (!nr || !emp) return res.status(400).json({ erro: 'Informe o pedido e a unidade.' });
    const e = queryOne('SELECT id, nome FROM cp_empresas WHERE id=?', [emp]);
    if (!e) return res.status(400).json({ erro: 'Unidade não encontrada: ' + emp });
    const antes = queryOne("SELECT COALESCE(empresa_id,'emp1') AS e, razao_social FROM pedidos WHERE pedido_venda=? LIMIT 1", [nr]);
    if (!antes) return res.status(404).json({ erro: 'Pedido não encontrado.' });
    if (queryOne(`SELECT id FROM nfe_emitidas WHERE pedido_venda=? AND status='autorizado' AND COALESCE(ambiente,'producao')='producao' AND COALESCE(empresa_id,'')<>? LIMIT 1`, [nr, emp]))
      return res.status(400).json({ erro: `O pedido ${nr} já tem NF-e autorizada por outro CNPJ — a nota manda: não dá para mover a unidade do pedido.` });
    db.run('UPDATE pedidos SET empresa_id=?, unidade_fixa=1 WHERE pedido_venda=?', [emp, nr]);   // v.407: escolha manual fica
    registrarLog('PEDIDO MOVIDO DE UNIDADE', `${nr} — ${antes.razao_social || ''}: ${antes.e} → ${emp} (${e.nome})`, String(req.body?.motivo || ''), '', req.usuario?.nome || 'sistema');
    salvarArquivo();
    res.json({ ok: true, pedido_venda: nr, empresa_id: emp, nome: e.nome });
  }));
  app.post('/api/pedidos/mover-unidade', rota((req, res) => {
    const emp = String(req.body?.empresa_id || '').trim();
    const lista = [...new Set((req.body?.pedidos || []).map(String).filter(Boolean))];
    const e = queryOne('SELECT id, nome FROM cp_empresas WHERE id=?', [emp]);
    if (!e || !lista.length) return res.status(400).json({ erro: 'Informe os pedidos e a unidade.' });
    const movidos = [], recusados = [];
    lista.forEach(nr => {
      if (queryOne(`SELECT id FROM nfe_emitidas WHERE pedido_venda=? AND status='autorizado' AND COALESCE(ambiente,'producao')='producao' AND COALESCE(empresa_id,'')<>? LIMIT 1`, [nr, emp])) { recusados.push(nr); return; }
      db.run('UPDATE pedidos SET empresa_id=?, unidade_fixa=1 WHERE pedido_venda=?', [emp, nr]); movidos.push(nr);   // v.407
    });
    if (movidos.length) registrarLog('PEDIDOS MOVIDOS DE UNIDADE', `${movidos.length} pedido(s) → ${e.nome}: ${movidos.join(', ')}`, '', '', req.usuario?.nome || 'sistema');
    salvarArquivo();
    res.json({ ok: true, movidos, recusados, nome: e.nome });
  }));

  app.post('/api/pedidos/:nr/cancelar', rota((req, res) => {
    const nr = String(req.params.nr);
    const motivo = String(req.body?.motivo || '').trim();
    const linhas = queryAll('SELECT id, razao_social, cancelado, valor_total FROM pedidos WHERE pedido_venda=?', [nr]);
    if (!linhas.length) return res.status(404).json({ erro: 'Pedido não encontrado.' });
    if (linhas.every(l => l.cancelado)) return res.status(400).json({ erro: 'Este pedido já está cancelado.' });
    if (motivo.length < 5) return res.status(400).json({ erro: 'Descreva o motivo do cancelamento (mínimo 5 caracteres).' });

    // Trava: pedido com NF-e de produção autorizada precisa da nota cancelada antes
    const nfe = queryOne(`SELECT numero FROM nfe_emitidas
                          WHERE pedido_venda=? AND status='autorizado' AND ambiente='producao' LIMIT 1`, [nr]);
    if (nfe) return res.status(400).json({ ok: false,
      erro: `O pedido ${nr} tem NF-e autorizada${nfe.numero ? ' (nº ' + nfe.numero + ')' : ''}. Cancele a nota na SEFAZ antes de cancelar o pedido.` });

    const quem = req.usuario?.nome || 'sistema';
    const agora = new Date().toLocaleString('pt-BR');
    const total = linhas.reduce((s, l) => s + (+l.valor_total || 0), 0);
    let _devolvidaC = null; try { _devolvidaC = _devolverCargaAoPedido(nr, quem, 'cancelada'); } catch(e) { console.warn('devolver carga:', e && e.message); }   // v.411
    db.run(`UPDATE pedidos SET cancelado=1, situacao='CANCELADO', cancelamento_motivo=?,
              cancelado_por=?, cancelado_em=? WHERE pedido_venda=?`, [motivo, quem, agora, nr]);
    // tira das pendências de boleto (não faz sentido cobrar pedido cancelado)
    db.run('DELETE FROM boletos_fila WHERE pedido_venda=?', [nr]);
    registrarLog('CANCELAMENTO DE PEDIDO',
      `${nr} — ${linhas[0].razao_social || '?'}`, motivo,
      `Valor: R$ ${total.toFixed(2)}`, quem);
    salvarArquivo();
    res.json({ ok: true, pedido: nr, cancelado_por: quem, cancelado_em: agora, carga_devolvida: _devolvidaC || null });
  }));

  // Reativa um pedido cancelado (se foi engano)
  app.post('/api/pedidos/:nr/reativar', rota((req, res) => {
    const nr = String(req.params.nr);
    const linhas = queryAll('SELECT id, cancelado FROM pedidos WHERE pedido_venda=?', [nr]);
    if (!linhas.length) return res.status(404).json({ erro: 'Pedido não encontrado.' });
    if (!linhas.some(l => l.cancelado)) return res.status(400).json({ erro: 'Este pedido não está cancelado.' });
    const quem = req.usuario?.nome || 'sistema';
    /* v.412: carga separada que foi cancelada devolveu os volumes ao pedido de origem; ao
       reativar, eles saem de lá de novo. Se o pedido de origem não tem mais a quantidade
       (já separou outra carga), a reativação é recusada — senão a venda dobraria. */
    const _cargaR = queryAll('SELECT produto, quantidade, pedido_origem FROM pedidos WHERE pedido_venda=?', [nr]);
    const _origR = String((_cargaR[0] || {}).pedido_origem || '').trim();
    if (_origR) {
      const _np = x => String(x || '').trim().toUpperCase();
      const lo = queryAll('SELECT id, produto, quantidade, vlr_unit FROM pedidos WHERE pedido_venda=? AND COALESCE(cancelado,0)=0 ORDER BY id', [_origR]);
      if (lo.length && !queryOne(`SELECT id FROM nfe_emitidas WHERE pedido_venda=? AND status IN ('autorizado','processando') AND COALESCE(ambiente,'producao')='producao' LIMIT 1`, [_origR])) {
        for (const c of _cargaR) {
          const o = lo.find(x => _np(x.produto) === _np(c.produto));
          if (!o || (+o.quantidade || 0) < (+c.quantidade || 0)) return res.status(400).json({ erro: `Não dá para reativar: o pedido de origem ${_origR} não tem mais ${c.quantidade} de "${c.produto}" para devolver a esta carga (já foi separado em outra carga). Separe uma carga nova a partir do ${_origR}.` });
        }
        _cargaR.forEach(c => { const o = lo.find(x => _np(x.produto) === _np(c.produto)); const nq = (+o.quantidade || 0) - (+c.quantidade || 0);
          if (nq > 0) { db.run('UPDATE pedidos SET quantidade=?, valor_total=? WHERE id=?', [nq, +(nq * (+o.vlr_unit || 0)).toFixed(2), o.id]); db.run('UPDATE pedido_itens SET quantidade=?, valor_total=? WHERE pedido_venda=? AND produto=? COLLATE NOCASE', [nq, +(nq * (+o.vlr_unit || 0)).toFixed(2), _origR, o.produto]); }
          else { db.run('DELETE FROM pedidos WHERE id=?', [o.id]); db.run('DELETE FROM pedido_itens WHERE pedido_venda=? AND produto=? COLLATE NOCASE', [_origR, o.produto]); }
          o.quantidade = nq; });
        db.run('UPDATE pedidos SET cancelado=0 WHERE pedido_venda=?', [nr]);   // já conta como viva no resumo
        try { _atualizarResumoCargas(_origR); } catch(e) {}   // v.413
        registrarLog('CARGA REATIVADA — VOLUMES SAÍRAM DO PEDIDO DE ORIGEM', `${nr} ← ${_origR}: ` + _cargaR.map(c => `${c.produto} ${c.quantidade}`).join(' · '), '', '', quem);
      }
    }
    db.run(`UPDATE pedidos SET cancelado=0, situacao='AGUARDANDO ROTA', cancelamento_motivo='',
              cancelado_por='', cancelado_em='' WHERE pedido_venda=?`, [nr]);
    registrarLog('REATIVAÇÃO DE PEDIDO', nr, req.body?.motivo || '', '', quem);
    salvarArquivo();
    res.json({ ok: true });
  }));

  // Dados de pagamento atuais do pedido (para preencher o modal de alteração)
  app.get('/api/pedidos/:nr/pagamento', rota((req, res) => {
    const nr = String(req.params.nr||'').trim();
    const linhas = queryAll('SELECT spg, condicao_pagamento, cond_pagto, forma_pagamento, sem_comissao FROM pedidos WHERE pedido_venda=?', [nr]);
    if (!linhas.length) return res.status(404).json({ erro: 'Pedido não encontrado.' });
    const primeiroNaoVazio = campo => { for (const l of linhas) { const v=String(l[campo]||'').trim(); if(v) return v; } return ''; };
    const cond = primeiroNaoVazio('condicao_pagamento') || primeiroNaoVazio('cond_pagto');
    res.json({
      ok: true, pedido_venda: nr,
      spg: linhas.some(l => l.spg) ? 1 : 0,
      condicao_pagamento: cond,
      forma_pagamento: primeiroNaoVazio('forma_pagamento'),
      sem_comissao: linhas.some(l => l.sem_comissao) ? 1 : 0
    });
  }));

  // Altera SPG, condição e forma de pagamento de um pedido (todas as linhas)
  app.post('/api/pedidos/:nr/pagamento', rota((req, res) => {
    const nr = String(req.params.nr||'').trim();
    const b = req.body || {};
    const linhas = queryAll('SELECT id, cancelado, spg FROM pedidos WHERE pedido_venda=?', [nr]);
    if (!linhas.length) return res.status(404).json({ erro: 'Pedido não encontrado.' });
    // v.222: com NF-e autorizada, a FORMA e a condição AINDA podem mudar — a forma
    // de cobrança não faz parte do XML da nota (caso Baratão: a venda virou
    // factoring depois da emissão). O que continua travado com nota é mudar o SPG,
    // porque esse altera o fluxo fiscal (SPG não gera nota).
    const nfe = queryOne(`SELECT numero FROM nfe_emitidas WHERE pedido_venda=? AND status='autorizado' AND ambiente='producao' LIMIT 1`, [nr]);
    const _spgAtual = linhas.some(l => l.spg) ? 1 : 0;
    if (nfe && (b.spg ? 1 : 0) !== _spgAtual)
      return res.status(400).json({ erro: `O pedido ${nr} já tem NF-e autorizada${nfe.numero?' (nº '+nfe.numero+')':''} — dá para mudar a forma/condição de pagamento, mas não o SPG.` });
    const spg = b.spg ? 1 : 0;
    const cond = String(b.condicao_pagamento||'').trim();
    const forma = String(b.forma_pagamento||'').trim();
    const semComissao = b.sem_comissao ? 1 : 0;
    const _condAntes = String(linhas[0]?.condicao_pagamento || linhas[0]?.cond_pagto || '').trim();
    db.run('UPDATE pedidos SET spg=?, condicao_pagamento=?, cond_pagto=?, forma_pagamento=?, sem_comissao=? WHERE pedido_venda=?',
      [spg, cond, cond, forma, semComissao, nr]);
    /* v.311: mudou a condição → os números reservados na impressão antiga não servem mais
       (o papel velho tem outro valor/outra quantidade de parcelas). Se nada foi ao banco,
       apaga as reservas; o boleto sai de novo, do zero. */
    let _resDesc = 0;
    if (cond.toUpperCase() !== _condAntes.toUpperCase()) {
      const _noBanco = queryOne('SELECT id FROM boletos_gerados WHERE pedido_venda=? LIMIT 1', [nr]);
      if (!_noBanco) {
        const _qtd = (queryAll('SELECT rowid FROM boletos_reservados WHERE chave=? OR pedido_venda=?', [nr, nr]) || []).length;
        if (_qtd) {
          _resDesc = _qtd;
          db.run('DELETE FROM boletos_reservados WHERE chave=? OR pedido_venda=?', [nr, nr]);
          registrarLog('RESERVA DE NOSSO NÚMERO DESCARTADA (condição mudou)',
            `${nr}: ${_condAntes || '-'} → ${cond || '-'} · ${_qtd} reserva(s) apagadas`,
            'Os boletos impressos antes NÃO valem — imprima de novo', '', req.usuario?.nome || 'sistema');
        }
      }
    }
    // Ajusta a situação conforme o novo SPG (só no início do fluxo, sem mexer em rota/entrega):
    //  • virou SPG (não gera nota) e estava AGUARDANDO NF → entra na logística (AGUARDANDO ROTA)
    //  • virou NF (gera nota) e estava AGUARDANDO ROTA sem nota autorizada → volta para AGUARDANDO NF
    try {
      const sitAtual = (queryOne('SELECT situacao FROM pedidos WHERE pedido_venda=? LIMIT 1', [nr]) || {}).situacao || '';
      if (spg && sitAtual === 'AGUARDANDO NF') {
        db.run("UPDATE pedidos SET situacao='AGUARDANDO ROTA' WHERE pedido_venda=? AND situacao='AGUARDANDO NF'", [nr]);
      } else if (!spg && sitAtual === 'AGUARDANDO ROTA' && !temNotaAutorizada(nr)) {
        db.run("UPDATE pedidos SET situacao='AGUARDANDO NF' WHERE pedido_venda=? AND situacao='AGUARDANDO ROTA' AND (ef_remessa IS NULL OR ef_remessa=0) AND (nota_mae IS NULL OR nota_mae=0)", [nr]);
      }
      // Virou À VISTA (PIX/dinheiro/transferência) e ainda está no início do fluxo →
      // passa a aguardar a confirmação do pagamento.
      if (ehAVista(cond, forma) &&
          ['AGUARDANDO ROTA','AGUARDANDO NF','AGUARDANDO BOLETO'].includes(sitAtual)) {
        db.run(`UPDATE pedidos SET situacao='AGUARDANDO PAGAMENTO' WHERE pedido_venda=?
                  AND UPPER(TRIM(situacao)) IN ('AGUARDANDO ROTA','AGUARDANDO NF','AGUARDANDO BOLETO')
                  AND (ef_remessa IS NULL OR ef_remessa=0) AND (nota_mae IS NULL OR nota_mae=0)`, [nr]);
      }
    } catch(e) {}
    // Mudou SPG/forma → reavalia a regra do boleto (nota+boleto ou pedido impresso+boleto)
    try { recalcularSituacaoPedido(nr); } catch(e) {}
    // Reflete nas cobranças (títulos em aberto) e nas filas de boleto
    try { sincronizarTitulos(); } catch(e) {}
    registrarLog('ALTERAÇÃO DE PAGAMENTO DO PEDIDO',
      `${nr} — SPG: ${spg?'sim':'não'} · Condição: ${cond||'-'} · Forma: ${forma||'-'} · Comissão: ${semComissao?'NÃO gera':'gera'}`, '', '', req.usuario?.nome || 'sistema');
    salvarArquivo();
    const _sitFinal = (queryOne('SELECT situacao FROM pedidos WHERE pedido_venda=? LIMIT 1', [nr]) || {}).situacao || '';
    res.json({ ok: true, pedido_venda: nr, spg, condicao_pagamento: cond, forma_pagamento: forma, sem_comissao: semComissao, situacao: _sitFinal, reservas_descartadas: _resDesc });
  }));

  app.get('/api/pedidos/buscar', rota((req, res) => {
    let { de, ate, cliente } = req.query || {};
    /* v.313: NÚMERO DE PEDIDO ACHA O PEDIDO, PONTO. Quem digita o número quer aquele
       pedido — não importa a unidade em que foi lançado nem a data. O 095143896 estava
       "aguardando análise" e a tela dizia "nenhum pedido encontrado" porque o filtro de
       unidade/data escondia. O mesmo vale para o filtro "Aguardando análise": mostra
       todos os que estão em análise, de qualquer unidade. */
    const _soNumero = /^\s*\d{5,}\s*$/.test(String(cliente || ''));
    const _todosAnalise = String(req.query.sem_analise || '') === '1';
    const _semFiltroUnidade = _soNumero || _todosAnalise;
    if (_semFiltroUnidade) { de = ''; ate = ''; }
    const _fuB = _semFiltroUnidade ? { sql: '', params: [] } : _filtroUnidade(req);
    const linhas = queryAll(`SELECT pedido_venda, data, razao_social, nome_fantasia, cidade,
                                    situacao, representante, quantidade, valor_total, spg,
                                    unidade, empresa_id, bloqueio, bloqueio_motivo, sem_analise, forma_pagamento, frete,
                                    cancelado, cancelamento_motivo, cancelado_por, cancelado_em, criado_em,
                                    pedido_origem, carga_num, carga_qtd
                             FROM pedidos WHERE pedido_venda IS NOT NULL AND pedido_venda!=''${_fuB.sql}
                             ${_todosAnalise ? ' AND COALESCE(sem_analise,0)=1 AND COALESCE(cancelado,0)=0' : ''}`,
                             _fuB.params);   // v.290 / v.313
    // cache da forma de pagamento cadastrada no cliente (fallback quando o pedido não tem)
    const _formaCliCache = new Map();
    const _formaDoCliente = (nome) => {
      const k = (nome||'').toUpperCase().trim();
      if (!_formaCliCache.has(k)) {
        const c = queryOne('SELECT forma_pagamento FROM clientes_fiscais WHERE razao_social=? COLLATE NOCASE', [nome]);
        _formaCliCache.set(k, (c?.forma_pagamento || '').trim());
      }
      return _formaCliCache.get(k);
    };
    // data no banco é dd/mm/aaaa → converte para comparar
    const paraData = br => {
      if (!br) return null;
      const m = String(br).match(/(\d{2})\/(\d{2})\/(\d{4})/);
      if (!m) return null;
      return new Date(+m[3], +m[2]-1, +m[1]);
    };
    const dDe  = de  ? new Date(de + 'T00:00:00')  : null;
    const dAte = ate ? new Date(ate + 'T23:59:59') : null;
    const alvo = (cliente || '').trim().toUpperCase();
    // Se o usuário digitou números, também casa pelo NÚMERO do pedido (tolerante a zeros à esquerda)
    const alvoNum = alvo.replace(/\D/g,'').replace(/^0+/,'');

    const porPedido = new Map();
    linhas.forEach(l => {
      if (alvo) {
        const nomeMatch = ((l.razao_social||'') + ' ' + (l.nome_fantasia||'')).toUpperCase().includes(alvo);
        const pedDigits = String(l.pedido_venda||'').replace(/\D/g,'').replace(/^0+/,'');
        const numMatch = alvoNum && pedDigits.includes(alvoNum);
        if (!nomeMatch && !numMatch) return;
      }
      /* v.373: pedido AGUARDANDO ANÁLISE ou AGUARDANDO PAGAMENTO é pendência do gestor —
         aparece SEMPRE, em qualquer período escolhido (não cancelado). O resto segue a data. */
      const _pendente = !l.cancelado && (l.sem_analise || /AGUARDANDO (AN[AÁ]LISE|PAGAMENTO)/i.test(String(l.situacao || '')));
      const d = paraData(l.data);
      if (!_pendente) {
        if (dDe  && (!d || d < dDe))  return;
        if (dAte && (!d || d > dAte)) return;
      }
      const k = String(l.pedido_venda);
      if (!porPedido.has(k)) porPedido.set(k, {
        pedido_venda: k, data: l.data || '', razao_social: l.razao_social || '',
        cidade: l.cidade || '', situacao: l.situacao || '', representante: l.representante || '',
        spg: l.spg ? 1 : 0, unidade: l.unidade || '', bloqueio: l.bloqueio || '',
        empresa_id: l.empresa_id || 'emp1',   // v.365: unidade (empresa) do pedido, para filtro e cor na tela
        sempre_visivel: _pendente ? 1 : 0,     // v.373: fora do período, mas é pendência
        bloqueio_motivo: l.bloqueio_motivo || '', sem_analise: l.sem_analise ? 1 : 0,
        forma_pagamento: (l.forma_pagamento || '').trim() || _formaDoCliente(l.razao_social),
        frete: (l.frete || '').trim().toUpperCase() || 'CIF',
        cancelado: l.cancelado ? 1 : 0, cancelamento_motivo: l.cancelamento_motivo || '',
        cancelado_por: l.cancelado_por || '', cancelado_em: l.cancelado_em || '',
        // hora em que o pedido foi lançado (primeira linha gravada)
        criado_em: l.criado_em || '', hora: String(l.criado_em || '').slice(11, 16),
        pedido_origem: l.pedido_origem || '', carga_num: +l.carga_num || 0, carga_qtd: +l.carga_qtd || 0,   // v.408
        itens: 0, valor_total: 0
      });
      const p = porPedido.get(k);
      p.itens++;
      p.valor_total += (+l.valor_total || 0);
      if (l.criado_em && (!p.criado_em || String(l.criado_em) < String(p.criado_em))) {
        p.criado_em = l.criado_em; p.hora = String(l.criado_em).slice(11, 16);
      }
    });
    const out = [...porPedido.values()].map(p => ({ ...p, valor_total: +p.valor_total.toFixed(2) }));
    // mais recentes primeiro (pela data; se não tiver, pelo número)
    out.sort((a,b) => {
      const da = paraData(a.data), db_ = paraData(b.data);
      if (da && db_ && da.getTime() !== db_.getTime()) return db_ - da;
      if (a.criado_em && b.criado_em && a.criado_em !== b.criado_em) return String(b.criado_em).localeCompare(String(a.criado_em));
      return String(b.pedido_venda).localeCompare(String(a.pedido_venda));
    });
    /* v.392: o corte dos 500 mais recentes NUNCA esconde pendência (aguardando análise /
       pagamento). O pedido 300000006 da OESTE (R$ 92 mil, em análise desde 29/09) sumia
       da busca "Tudo" porque, com todas as unidades, havia mais de 500 pedidos mais novos. */
    const lista = out.slice(0, 500);
    out.slice(500).filter(p => p.sempre_visivel).forEach(p => lista.push(p));
    /* v.398: situação de crédito do cliente em cada pedido (boleto vencido em aberto / mau pagador),
       para quem consulta e para quem aprova ver antes de liberar. Uma leitura do banco para todos. */
    try {
      const av = _creditoAvaliador(); const memo = new Map();
      lista.forEach(p => {
        const k = String(p.razao_social || '').trim().toUpperCase(); if (!k) return;
        if (!memo.has(k)) { const c = av.avaliar(p.razao_social); memo.set(k, c.qtd ? { nivel: c.nivel, nivel_faixa: c.nivel_faixa || c.nivel, qtd: c.qtd, valor: c.valor, dias: c.dias, cartorio: c.cartorio || 0 } : null); }
        const c = memo.get(k); if (c) p.credito = c;
      });
    } catch(e) {}
    res.json({ total: out.length, pedidos: lista, limite: 500 });
  }));

  // ─── LIMPEZA DE PEDIDOS DUPLICADOS (reimportados) ───────────────────────────
  // Ao trocar a extração do PDF do "CONTROLE Nº" (00714xx) para o "Nº do Pedido de
  // Venda" (069xxx), reimportar o mesmo PDF gerou uma 2ª cópia com o número novo.
  // Aqui removemos a cópia NOVA (069xxx) quando existe uma cópia ANTIGA (00714xx)
  // com o MESMO conteúdo (cliente + valor total + qtd de itens). ?dry=1 só simula.
  app.post('/api/pedidos/dedup-reimportados', rota((req, res) => {
    const dry = req.query.dry === '1' || req.body?.dry === true || req.body?.dry === 1;
    const linhas = queryAll("SELECT pedido_venda, razao_social, valor_total, situacao, data FROM pedidos WHERE pedido_venda IS NOT NULL AND pedido_venda!=''");
    const porPed = new Map();
    linhas.forEach(l => {
      const k = String(l.pedido_venda);
      if (!porPed.has(k)) porPed.set(k, { nr: k, razao: l.razao_social || '', total: 0, itens: 0, situacao: l.situacao || '', data: l.data || '' });
      const p = porPed.get(k);
      p.total += (+l.valor_total || 0);
      p.itens++;
      if (!p.razao && l.razao_social) p.razao = l.razao_social;
    });
    const peds = [...porPed.values()].map(p => ({ ...p, total: +p.total.toFixed(2) }));
    const norm = s => String(s || '').toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/\s+/g, ' ').trim();
    const chave = p => norm(p.razao) + '|' + p.total.toFixed(2) + '|' + p.itens;
    const ehControle = nr => /^0071\d{3}$/.test(nr); // número ANTIGO (controle)
    const ehPedVenda = nr => /^069\d{3}$/.test(nr);  // número NOVO (pedido de venda)
    // indexa as cópias antigas (controle) por conteúdo
    const antigosPorChave = new Map();
    peds.forEach(p => { if (ehControle(p.nr)) { const k = chave(p); if (!antigosPorChave.has(k)) antigosPorChave.set(k, []); antigosPorChave.get(k).push(p); } });
    const pares = [];
    peds.forEach(p => {
      if (ehPedVenda(p.nr)) {
        const twins = antigosPorChave.get(chave(p)) || [];
        if (twins.length) pares.push({ novo: p, antigo: twins[0] });
      }
    });
    if (!dry) {
      pares.forEach(d => {
        db.run('DELETE FROM pedido_itens WHERE pedido_venda=?', [d.novo.nr]);
        db.run('DELETE FROM pedidos WHERE pedido_venda=?', [d.novo.nr]);
        registrarLog('DEDUP REIMPORTADO', `${d.novo.nr} removido (duplicata de ${d.antigo.nr})`, '', '', req.usuario?.nome || 'sistema');
      });
      if (pares.length) salvarArquivo();
    }
    res.json({ ok: true, dry: !!dry, total: pares.length, pares });
  }));

  app.get('/api/pedidos', rota((req, res) => {
    const f = _filtroUnidade(req);                       // v.290
    let lista = queryAll(`SELECT * FROM pedidos WHERE 1=1${f.sql} ORDER BY id DESC`, f.params);
    try { lista = lista.filter(p => !_clienteFora(p.razao_social)); } catch(e) {}   // v.416: clientes fora da logística
    /* v.338: REPRESENTANTE SÓ RECEBE OS PEDIDOS DELE — filtrado AQUI, no servidor, com a
       mesma regra da carteira (nomeBateRep: primeiro nome igual E todos os nomes do menor
       dentro do maior). A tela filtrava sozinha, pelo PRIMEIRO NOME: a Janaina Duarte
       (Petrolina) enxergava os pedidos da Janaina Carla da Silva (Simões Filho). */
    try {
      if (ehRepresentante(req.usuario) && !ehDono(req.usuario)) {
        const nomes = repsDoUsuario(req.usuario).nomes || [];
        lista = lista.filter(p => nomes.some(n => nomeBateRep(p.representante, n)));
      }
    } catch(e) { console.warn('v.338 filtro do representante:', e && e.message); }
    res.json(lista);
  }));

  app.get('/api/pedidos/existe/:nr', rota((req, res) => {
    const row = queryOne('SELECT razao_social, situacao, sem_analise, cancelado FROM pedidos WHERE pedido_venda=? LIMIT 1', [req.params.nr]);
    if (!row) return res.json({ existe: false });
    let situacao = String(row.situacao || 'AGUARDANDO ROTA');
    if (row.cancelado) situacao = 'CANCELADO';
    else if (row.sem_analise) situacao = 'AGUARDANDO ANÁLISE';
    res.json({ existe: true, razao_social: row.razao_social || '', situacao, sem_analise: row.sem_analise ? 1 : 0, cancelado: row.cancelado ? 1 : 0 });
  }));

  // ─── Representante vindo do PDF importado ────────────────────────────────────
  // Limpa o nome ("076-0 DANIEL ALBURQUERQUE" → "DANIEL ALBURQUERQUE", "012-4 SM - JANAINA" → "JANAINA")
  function _limparNomeRep(bruto){
    let s = String(bruto||'').trim();
    if (!s || s === '-') return '';
    s = s.replace(/^repres\.?:?\s*/i,'');           // rótulo, se veio junto
    s = s.replace(/^\s*\d{2,5}\s*-\s*\d\b\s*/,'');   // código "076-0 "
    s = s.replace(/^\s*[A-Za-z]{1,4}\s*-\s*/,'');    // sigla "SM - "
    s = s.replace(/\s{2,}/g,' ').trim();
    return s;
  }
  const _normRep = s => String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toUpperCase().replace(/[^A-Z0-9]+/g,' ').trim();
  // Garante o representante na tabela (sem duplicar por acento/caixa/espaço) e devolve o NOME canônico
  // Resolve o representante do PDF para um que JÁ EXISTE no cadastro (por código ou nome).
  // NÃO cria mais representante automaticamente (evita duplicados por grafias diferentes nos PDFs).
  // Retorna o nome canônico do cadastro, ou '' se não houver correspondência.
  // v.211: devolve a grafia OFICIAL do cadastro para um nome abreviado.
  // "JANAINA CARLA" → "JANAINA CARLA DA SILVA" (todos os tokens do nome estão no oficial).
  // "TIAGO PRAZERES - ELADIO" NÃO vira "TIAGO PRAZERES": tem tokens a mais (é uma dupla),
  // então fica como veio — a regra só encurta a distância quando o nome é uma ABREVIAÇÃO.
  function _grafiaOficialRep(nome){
    const n = String(nome||'').trim();
    if (!n) return n;
    let lista = [];
    try { lista = queryAll("SELECT nome FROM representantes WHERE ativo=1 AND TRIM(nome)<>''"); } catch(e) { return n; }
    const normN = _repNorm(n);
    // bate exato com uma linha do cadastro → usa a grafia de lá
    for (const r of lista) if (_repNorm(r.nome) === normN) return r.nome;
    // é abreviação de exatamente UM oficial → usa o oficial
    const toks = _repTok(n);
    if (!toks.length) return n;
    const candidatos = lista.filter(r => {
      const t2 = _repTok(r.nome);
      return toks[0] === t2[0] && toks.every(t => t2.includes(t)) && t2.length > toks.length;
    });
    return candidatos.length === 1 ? candidatos[0].nome : n;
  }

  function garantirRepresentante(bruto, stats){
    const nome = _limparNomeRep(bruto);
    if (!nome || nome.length < 2) return '';
    const alvo = _normRep(nome);
    if (!alvo) return '';
    const codigo = (String(bruto||'').match(/\b(\d{2,5}-\d)\b/) || [])[1] || '';
    const existentes = queryAll('SELECT nome, codigo FROM representantes');
    // 1) mesmo CÓDIGO já cadastrado (ex.: "076-0") → é o mesmo rep, mesmo que a grafia varie
    if (codigo) { for (const r of existentes) { if (String(r.codigo||'').trim() === codigo) return r.nome; } }
    // 2) mesmo NOME normalizado (acento/caixa/espaço)
    for (const r of existentes) { if (_normRep(r.nome) === alvo) return r.nome; }
    // 2.5 (v.211): o nome do PDF é uma ABREVIAÇÃO de um único representante do
    // cadastro (ex.: "JANAINA CARLA" ⊂ "JANAINA CARLA DA SILVA") → usa o oficial.
    const _oficial = _grafiaOficialRep(nome);
    if (_oficial && _normRep(_oficial) !== alvo) return _oficial;
    // Sem correspondência: NÃO cria. Apenas deixa o nome que veio no pedido.
    return '';
  }
  // Coloca o representante no cadastro fiscal do cliente (preenche se vazio ou corrige a grafia do mesmo rep)
  function vincularRepAoCliente(razao, repNome, stats){
    const rs = String(razao||'').trim();
    if (!rs || !repNome) return;
    const cli = queryOne('SELECT id, representante FROM clientes_fiscais WHERE razao_social=? COLLATE NOCASE', [rs]);
    if (!cli) return;                                     // cliente ainda não está no cadastro fiscal
    const atual = String(cli.representante||'').trim();
    if (atual && _normRep(atual) !== _normRep(repNome)) return;  // já tem OUTRO representante — não sobrescreve
    if (atual === repNome) return;                        // já está correto
    db.run("UPDATE clientes_fiscais SET representante=?, atualizado_em=datetime('now','localtime') WHERE id=?", [repNome, cli.id]);
    if (stats) stats.clientes_vinculados++;
  }

  app.post('/api/pedidos/bulk', rota((req, res) => {
    const pedidos = req.body;
    if (!Array.isArray(pedidos) || !pedidos.length) return res.json({ inseridos: 0 });
    const _uImport = _unidadeDeQuemLanca(req)   /* v.325 */;   // v.290: unidade de quem está importando
    let inseridos = 0, condicao_atualizada = 0;
    const stats = { reps_criados: 0, clientes_vinculados: 0 };
    // O total do item é SEMPRE quantidade × valor unitário. O leitor de PDF às vezes
    // captura outra coluna como "valor total" e isso inflava os relatórios.
    pedidos.forEach(p => {
      const q = +p["Quantidade"] || 0, vu = +p["Vlr. Unit."] || 0;
      if (q > 0 && vu > 0) p["Valor Total"] = +(q * vu).toFixed(2);
    });
    const _repCache = new Map();  // brutoRepresentante → nome canônico (evita reprocessar por linha)
    for (const p of pedidos) {
      try {
        db.run(
          `INSERT OR IGNORE INTO pedidos
            (pedido_venda,data,razao_social,nome_fantasia,cidade,regiao,produto,
             quantidade,vlr_unit,valor_total,previsao,situacao,
             data_entrega,motorista,caminhao,obs,representante,arquivo,cond_pagto,empresa_id)
           VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
          [p["Pedido de Venda"]||'-', p["Data"]||null, p["Razão Social"]||null,
           p["Nome Fantasia"]||null, p["Cidade"]||null, p["Região"]||null,
           p["Descrição do Produto"]||null, p["Quantidade"]||0, p["Vlr. Unit."]||0,
           p["Valor Total"]||0, p["Previsão"]||null, p["Situação"]||'AGUARDANDO ROTA',
           p["Data da Entrega"]||null, p["Motorista"]||null, p["Caminhão"]||null,
           p["Obs"]||null, p["Representante"]||null, p["Arquivo"]||null, p["Cond. Pagto"]||null,
           _unidadePelaCidade(p["Cidade"]) || _unidadePeloRep(p["Representante"]) || _uImport]      // v.363 / v.381 / v.290
        );
        if (db.getRowsModified() > 0) inseridos++;
        else {
          // Pedido já existe: preenche a CONDIÇÃO DE PAGAMENTO se estiver vazia e o PDF trouxe uma
          const cp = p["Cond. Pagto"]; const nr = p["Pedido de Venda"];
          if (cp && String(cp).trim() && String(cp).trim() !== '(não informado)' && nr && nr !== '-') {
            db.run("UPDATE pedidos SET cond_pagto=? WHERE pedido_venda=? AND (cond_pagto IS NULL OR TRIM(cond_pagto)='' OR cond_pagto='(não informado)')", [cp, nr]);
            if (db.getRowsModified() > 0) condicao_atualizada++;
          }
        }

        // ─── Representante do PDF: cadastra o rep (se novo) e vincula ao cliente ───
        const repBruto = p["Representante"];
        if (repBruto && String(repBruto).trim() && String(repBruto).trim() !== '-') {
          let repNome = _repCache.get(repBruto);
          if (repNome === undefined) { repNome = garantirRepresentante(repBruto, stats); _repCache.set(repBruto, repNome); }
          if (repNome) {
            const nr = p["Pedido de Venda"];
            // padroniza a grafia do representante no próprio pedido
            if (nr && nr !== '-') db.run('UPDATE pedidos SET representante=? WHERE pedido_venda=? AND representante<>?', [repNome, nr, repNome]);
            vincularRepAoCliente(p["Razão Social"], repNome, stats);
          }
        }
      } catch(e) { /* ignorar duplicatas */ }
    }
    salvarArquivo();
    res.json({ inseridos, condicao_atualizada, reps_criados: stats.reps_criados, clientes_vinculados: stats.clientes_vinculados });
  }));

  // Confirmar entrega de TODOS os pedidos de uma rota
  app.post('/api/pedidos/confirmar-rota', rota((req, res) => {
    const { motorista, caminhao, data_prevista, data_entrega } = req.body;
    if (!motorista || !data_entrega) return res.status(400).json({ erro: 'Campos obrigatórios.' });
    db.run(
      "UPDATE pedidos SET situacao='PEDIDO ENTREGUE',data_entrega=? WHERE situacao='CARREGANDO' AND motorista=? AND caminhao=? AND data_prevista=?",
      [data_entrega, motorista, caminhao||null, data_prevista||null]
    );
    const atualizados=db.getRowsModified();
    salvarArquivo();
    res.json({ ok:true, atualizados });
  }));

  // Atualizar data de entrega de pedido já entregue
  app.post('/api/pedidos/atualizar-data', rota((req, res) => {
    const { pedido_venda, data_entrega, motorista, caminhao } = req.body;
    if (!pedido_venda || !data_entrega) return res.status(400).json({ erro: 'Campos obrigatórios.' });
    const campos = ['data_entrega=?'];
    const params = [data_entrega];
    if (motorista !== undefined && motorista !== null) {
      campos.push('motorista=?');
      params.push(motorista);
    }
    if (caminhao !== undefined && caminhao !== null) {
      campos.push('caminhao=?');
      params.push(caminhao);
    }
    params.push(pedido_venda);
    db.run(`UPDATE pedidos SET ${campos.join(',')} WHERE pedido_venda=?`, params);
    // Registrar log da alteração
    const detalhes = [];
    detalhes.push(`Data: ${data_entrega}`);
    if (motorista !== undefined && motorista !== null) detalhes.push(`Motorista: ${motorista}`);
    if (caminhao !== undefined && caminhao !== null) detalhes.push(`Caminhão: ${caminhao}`);
    registrarLog('ALTERAÇÃO DE ENTREGA',
      `Pedido ${pedido_venda}`,
      '',
      detalhes.join(' · '),
      req.usuario?.nome||'sistema');
    salvarArquivo();
    res.json({ ok: true });
  }));

  // Desfazer divisão — junta itens de um pedido dividido (XXX-P1) de volta ao original (XXX)
  app.post('/api/pedidos/desfazer-divisao', rota((req, res) => {
    const { pedido_venda } = req.body;
    if (!pedido_venda) return res.status(400).json({ erro: 'pedido_venda obrigatório' });

    // Verificar se o pedido tem padrão de divisão: termina com -P seguido de número
    const match = pedido_venda.match(/^(.+)-P(\d+)$/);
    if (!match) return res.status(400).json({ erro: 'Este pedido não foi gerado por divisão (esperado padrão "XXX-P1").' });

    const pedidoOriginal = match[1];

    // Verificar se o pedido original ainda existe
    const originalExiste = queryOne('SELECT id FROM pedidos WHERE pedido_venda=? LIMIT 1', [pedidoOriginal]);
    if (!originalExiste) {
      return res.status(404).json({ erro: `Pedido original ${pedidoOriginal} não existe mais. Não é possível reverter.` });
    }

    // Buscar itens do pedido dividido
    const itens = queryAll('SELECT id, obs FROM pedidos WHERE pedido_venda=?', [pedido_venda]);
    if (!itens.length) return res.status(404).json({ erro: 'Nenhum item encontrado para reverter.' });

    // Reverter cada item para o pedido original, removendo a marcação de divisão da obs
    itens.forEach(item => {
      let novaObs = item.obs || '';
      // Remover a marcação [Dividido de XXX em DD/MM/YYYY - falta estoque]
      novaObs = novaObs.replace(/\[Dividido de [^\]]+\]/g, '').trim();
      if (!novaObs) novaObs = null;
      db.run('UPDATE pedidos SET pedido_venda=?, obs=? WHERE id=?', [pedidoOriginal, novaObs, item.id]);
    });

    registrarLog('REVERSÃO DE DIVISÃO',
      `${pedido_venda} → ${pedidoOriginal}`,
      'Desfazer divisão',
      `${itens.length} item(ns) restaurados ao pedido original`,
      req.usuario?.nome || 'sistema');

    salvarArquivo();
    res.json({ ok: true, pedido_original: pedidoOriginal, itens_revertidos: itens.length });
  }));

  // Dividir pedido — move alguns itens (totais ou parciais) para um novo pedido pendente
  // Útil quando faltam alguns produtos em estoque: o pedido original entrega o que tem,
  // e os itens em falta (totais OU parciais) viram um novo pedido pendente (AGUARDANDO ROTA)
  // Body: { pedido_venda, splits: [{ item_id, qtd_pendente }] }
  app.post('/api/pedidos/dividir', rota((req, res) => {
    const { pedido_venda, splits, item_ids } = req.body;

    if (!pedido_venda) return res.status(400).json({ erro: 'pedido_venda é obrigatório.' });

    // Compatibilidade: aceitar splits (novo) OU item_ids (formato antigo = move tudo)
    let splitsArr = [];
    if (Array.isArray(splits) && splits.length) {
      splitsArr = splits.filter(s => s.item_id && (s.qtd_pendente || 0) > 0);
    } else if (Array.isArray(item_ids) && item_ids.length) {
      // Formato antigo — move quantidade total de cada item
      splitsArr = item_ids.map(id => ({ item_id: id, qtd_pendente: null }));
    }
    if (!splitsArr.length) return res.status(400).json({ erro: 'Nenhum item válido para mover.' });

    // Buscar todos os itens envolvidos
    const itemIds = splitsArr.map(s => s.item_id);
    const placeholders = itemIds.map(() => '?').join(',');
    const itens = queryAll(
      `SELECT * FROM pedidos WHERE id IN (${placeholders}) AND pedido_venda=?`,
      [...itemIds, pedido_venda]
    );
    if (!itens.length) return res.status(404).json({ erro: 'Itens não encontrados no pedido informado.' });

    // Separar: full move (qtd_pendente >= qtd) vs partial split (0 < qtd_pendente < qtd)
    const itemsFullMove = [];
    const itemsPartial = [];
    splitsArr.forEach(s => {
      const item = itens.find(i => i.id === s.item_id);
      if (!item) return;
      const qtdOrig = item.quantidade || 0;
      const qtdPend = s.qtd_pendente === null ? qtdOrig : Math.min(s.qtd_pendente, qtdOrig);
      if (qtdPend <= 0) return;
      if (qtdPend >= qtdOrig) {
        itemsFullMove.push(item);
      } else {
        itemsPartial.push({ item, qtd_pendente: qtdPend });
      }
    });

    if (!itemsFullMove.length && !itemsPartial.length) {
      return res.status(400).json({ erro: 'Nenhum item tem quantidade pendente válida.' });
    }

    // Validar: precisa sobrar pelo menos 1 item (ou parte de item) no pedido original
    const totalItensPedido = queryOne('SELECT COUNT(*) as n FROM pedidos WHERE pedido_venda=?', [pedido_venda]).n;
    const totalMovendoCompleto = itemsFullMove.length;
    if (totalMovendoCompleto === totalItensPedido && itemsPartial.length === 0) {
      return res.status(400).json({ erro: 'Não é possível mover TODOS os itens completamente. Mantenha pelo menos 1 item (ou parcela) no original.' });
    }

    // Gerar número novo do pedido
    let suffix = 1;
    let novoNumero = `${pedido_venda}-P${suffix}`;
    while (true) {
      const existe = queryOne('SELECT id FROM pedidos WHERE pedido_venda=? LIMIT 1', [novoNumero]);
      if (!existe) break;
      suffix++;
      novoNumero = `${pedido_venda}-P${suffix}`;
      if (suffix > 99) return res.status(500).json({ erro: 'Limite de divisões excedido.' });
    }

    const dataHoje = new Date().toLocaleDateString('pt-BR');
    const obsExtra = `[Dividido de ${pedido_venda} em ${dataHoje} - falta estoque]`;

    // 1) Itens movidos por inteiro: troca pedido_venda
    itemsFullMove.forEach(item => {
      const novaObs = item.obs && item.obs !== '-' && item.obs !== '' ? `${item.obs} ${obsExtra}` : obsExtra;
      db.run(
        `UPDATE pedidos SET pedido_venda=?, situacao='AGUARDANDO ROTA', motorista=NULL, caminhao=NULL, data_prevista=NULL, data_entrega=NULL, obs=? WHERE id=?`,
        [novoNumero, novaObs, item.id]
      );
    });

    // 2) Splits parciais: reduz qtd do original e cria nova linha no novo pedido
    itemsPartial.forEach(({ item, qtd_pendente }) => {
      const qtdRestante = (item.quantidade || 0) - qtd_pendente;
      const vu = item.vlr_unit || 0;
      const valorRestante = qtdRestante * vu;
      const valorPendente = qtd_pendente * vu;
      const novaObs = item.obs && item.obs !== '-' && item.obs !== '' ? `${item.obs} ${obsExtra}` : obsExtra;

      // Atualiza original com qtd reduzida
      db.run(`UPDATE pedidos SET quantidade=?, valor_total=? WHERE id=?`,
        [qtdRestante, valorRestante, item.id]);

      // Cria nova linha no novo pedido com a qtd pendente
      db.run(`INSERT INTO pedidos
        (pedido_venda, data, razao_social, nome_fantasia, cidade, regiao, produto, quantidade, vlr_unit, valor_total, previsao, situacao, data_entrega, motorista, caminhao, data_prevista, obs, representante, arquivo, empresa_id)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
        [novoNumero, item.data || null, item.razao_social || null, item.nome_fantasia || null,
         item.cidade || null, item.regiao || null, item.produto || null, qtd_pendente, vu, valorPendente,
         item.previsao || null, 'AGUARDANDO ROTA', null, null, null, null, novaObs, item.representante || null, item.arquivo || null,
         item.empresa_id || 'emp1']);   // v.290: o pedido-filho fica na unidade do pai
    });

    registrarLog('DIVISÃO DE PEDIDO',
      `${pedido_venda} → ${novoNumero}`,
      'Falta de estoque',
      `${itemsFullMove.length} item(ns) total + ${itemsPartial.length} parcial`,
      req.usuario?.nome || 'sistema');

    salvarArquivo();
    res.json({
      ok: true,
      novo_pedido: novoNumero,
      itens_total: itemsFullMove.length,
      itens_parcial: itemsPartial.length,
      itens_movidos: itemsFullMove.length + itemsPartial.length
    });
  }));

  /* ═══════ v.408: DESMEMBRAR UM PEDIDO EM CARGAS ═══════
     Pedido grande (ex.: 12.255 volumes da COROA) não cabe numa carreta. O gestor diz quantas
     cargas são e quanto de cada produto vai em cada uma. A carga 1 fica no número original;
     as outras viram pedidos NOVOS, com número da faixa da unidade, copiando o cabeçalho
     inteiro (cliente, cidade, representante, condição e forma de pagamento, frete, unidade,
     análise/bloqueio). Cada carga segue o fluxo normal — NF-e própria, boletos próprios pela
     mesma condição, logística própria — "faturado do mesmo jeito". Só antes da nota. */
  app.post('/api/pedidos/:nr/desmembrar', rota((req, res) => {
    const nr = String(req.params.nr || '').trim();
    if (ehRepresentante(req.usuario) && !ehDono(req.usuario)) return res.status(403).json({ erro: 'Representante não desmembra pedido — peça ao escritório.' });
    const cargas = Array.isArray(req.body?.cargas) ? req.body.cargas : [];
    if (cargas.length < 2) return res.status(400).json({ erro: 'Informe pelo menos 2 cargas.' });
    if (cargas.length > 12) return res.status(400).json({ erro: 'No máximo 12 cargas por pedido.' });
    const linhas = queryAll('SELECT * FROM pedidos WHERE pedido_venda=? ORDER BY id', [nr]);
    if (!linhas.length) return res.status(404).json({ erro: 'Pedido não encontrado.' });
    const tpl = { ...linhas[0] };
    const sitU = String(tpl.situacao || '').toUpperCase();
    if (linhas.some(l => l.cancelado)) return res.status(400).json({ erro: 'Pedido cancelado não pode ser desmembrado.' });
    if (/ENTREGUE|CARREGANDO|REMESSA/.test(sitU)) return res.status(400).json({ erro: `Pedido ${nr} está "${tpl.situacao}" — desmembre antes de montar a rota.` });
    if (tpl.nota_mae) return res.status(400).json({ erro: 'Nota mãe (entrega futura) não se desmembra — as remessas já fazem esse papel.' });
    if (tpl.ef_remessa) return res.status(400).json({ erro: 'Remessa de entrega futura não se desmembra.' });
    if (queryOne(`SELECT id FROM nfe_emitidas WHERE pedido_venda=? AND status IN ('autorizado','processando') AND COALESCE(ambiente,'producao')='producao' LIMIT 1`, [nr]))
      return res.status(400).json({ erro: `O pedido ${nr} já tem NF-e emitida — não dá mais para desmembrar. Cancele/devolva a nota primeiro.` });
    // quantidades do pedido por produto (soma das linhas iguais)
    const _np = x => String(x || '').trim().toUpperCase();
    const orig = new Map();
    linhas.forEach(l => { const k = _np(l.produto); if (!orig.has(k)) orig.set(k, { produto: l.produto, quantidade: 0, vlr_unit: +l.vlr_unit || 0, linha: l }); orig.get(k).quantidade += (+l.quantidade || 0); });
    // valida a divisão: inteiros ≥ 0, e a soma de cada produto = quantidade do pedido
    let plano;
    try {
      plano = cargas.map((c, i) => {
        const itens = Array.isArray(c?.itens) ? c.itens : [];
        const m = new Map();
        itens.forEach(it => { const k = _np(it.produto); const q = Math.round(+it.quantidade || 0); if (!orig.has(k)) throw new Error(`Produto "${it.produto}" não está no pedido.`); if (q < 0) throw new Error('Quantidade negativa.'); m.set(k, (m.get(k) || 0) + q); });
        return { num: i + 1, nome: String(c?.nome || `Carga ${i + 1}`).trim(), itens: m };
      });
    } catch(e) { return res.status(400).json({ erro: e.message }); }
    for (const [k, o] of orig) {
      const soma = plano.reduce((t, c) => t + (c.itens.get(k) || 0), 0);
      if (soma !== o.quantidade) return res.status(400).json({ erro: `${o.produto}: as cargas somam ${soma} e o pedido tem ${o.quantidade}. Distribua tudo (a diferença fica em alguma carga).` });
    }
    const vazias = plano.filter(c => [...c.itens.values()].every(q => q <= 0));
    if (vazias.length) return res.status(400).json({ erro: `${vazias.map(c => c.nome).join(', ')} está sem nenhum produto.` });
    const unidade = tpl.empresa_id || 'emp1';
    const excluir = new Set(['id', 'criado_em', 'produto', 'quantidade', 'vlr_unit', 'valor_total']);
    const cols = Object.keys(tpl).filter(k => !excluir.has(k));
    const todasCols = [...cols, 'produto', 'quantidade', 'vlr_unit', 'valor_total'];
    const ph = todasCols.map(() => '?').join(',');
    const hoje = new Date().toLocaleDateString('pt-BR');
    const total = plano.length;
    const numeros = [nr];
    // números novos para as cargas 2..N (faixa da unidade)
    for (let i = 1; i < total; i++) {
      let { nr: novo } = proximoNumeroPedidoLivre(unidade);
      while (numeros.includes(novo) || queryOne('SELECT id FROM pedidos WHERE pedido_venda=? LIMIT 1', [novo])) {
        const n = String(parseInt(novo, 10) + 1).padStart(String(novo).length, '0'); novo = n;
      }
      numeros.push(novo);
    }
    const tagObs = (i) => `[CARGA ${i + 1}/${total} do pedido ${nr} — desmembrado em ${hoje}: ${numeros.map((n, j) => `carga ${j + 1} = ${n}`).join(', ')}]`;
    const obsBase = String(tpl.obs || '').replace(/\s*\[CARGA [^\]]*\]/g, '').trim();
    // regrava: carga 1 no número original, as demais nos números novos
    db.run('DELETE FROM pedidos WHERE pedido_venda=?', [nr]);
    db.run('DELETE FROM pedido_itens WHERE pedido_venda=?', [nr]);
    const resumo = [];
    plano.forEach((c, i) => {
      const numero = numeros[i];
      const cab = { ...tpl, pedido_venda: numero, obs: (obsBase && obsBase !== '-' ? obsBase + ' ' : '') + tagObs(i),
                    motorista: null, caminhao: null, data_prevista: null, data_entrega: null, ordem_rota: null,
                    pedido_origem: nr, carga_num: i + 1, carga_qtd: total };
      let tot = 0, vols = 0;
      for (const [k, q] of c.itens) {
        if (q <= 0) continue;
        const o = orig.get(k); const vt = +(q * o.vlr_unit).toFixed(2); tot += vt; vols += q;
        db.run(`INSERT INTO pedidos (${todasCols.join(',')}) VALUES (${ph})`, [...cols.map(col => cab[col]), o.produto, q, o.vlr_unit, vt]);
        db.run('INSERT INTO pedido_itens (pedido_venda, produto, quantidade, vlr_unit, valor_total) VALUES (?,?,?,?,?)', [numero, o.produto, q, o.vlr_unit, vt]);
      }
      resumo.push({ carga: i + 1, nome: c.nome, pedido_venda: numero, volumes: vols, valor: +tot.toFixed(2) });
    });
    try { recalcularSituacaoPedidos(numeros); } catch(e) {}
    registrarLog('PEDIDO DESMEMBRADO EM CARGAS', `${nr} (${tpl.razao_social || ''}) → ${resumo.map(r => `carga ${r.carga}: ${r.pedido_venda} (${r.volumes} vol · R$ ${r.valor.toFixed(2)})`).join(' · ')}`, '', '', req.usuario?.nome || 'sistema');
    salvarArquivo();
    res.json({ ok: true, origem: nr, cargas: resumo });
  }));

  /* ═══════ v.409: SEPARAR UMA CARGA DE CADA VEZ ═══════
     O gestor não sabe de antemão quantas carretas vão sair nem o peso de cada uma. Então a
     separação é por caminhão: escolhe o caminhão (ou digita a capacidade em kg), o sistema
     sugere quanto cabe pelo peso de cada produto, ele ajusta e confirma. Essa carga vira um
     pedido NOVO (número da unidade, mesmo cabeçalho) e o pedido original fica com o restante,
     pronto para a próxima carreta. A última carga é o próprio pedido original. */
  function _pesoPorProduto() {
    const _normProd = x => String(x || '').toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Z0-9]+/g, ' ').trim();
    const mapa = new Map();
    try { queryAll('SELECT descricao, peso_kg FROM produtos_fiscais').forEach(pr => { const n = _normProd(pr.descricao); if (n) mapa.set(n, +pr.peso_kg > 0 ? +pr.peso_kg : 20); }); } catch(e) {}
    return nome => {
      const n = _normProd(nome); if (!n) return 20;
      if (mapa.has(n)) return mapa.get(n);
      for (const [k, v] of mapa) { if (k.length >= 4 && (k.startsWith(n) || n.startsWith(k))) return v; }
      return 20;
    };
  }
  app.get('/api/pedidos/:nr/carga-info', rota((req, res) => {
    const nr = String(req.params.nr || '').trim();
    const linhas = queryAll('SELECT * FROM pedidos WHERE pedido_venda=? ORDER BY id', [nr]);
    if (!linhas.length) return res.status(404).json({ erro: 'Pedido não encontrado.' });
    const peso = _pesoPorProduto();
    const _np = x => String(x || '').trim().toUpperCase();
    const itens = new Map();
    linhas.forEach(l => { const k = _np(l.produto); if (!itens.has(k)) itens.set(k, { produto: l.produto, quantidade: 0, vlr_unit: +l.vlr_unit || 0, peso_kg: peso(l.produto) }); itens.get(k).quantidade += (+l.quantidade || 0); });
    // estoque de produto acabado (Produção: produzido − entregue; disponível = menos o que já está em rota)
    const _normE = x => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/\s+/g, ' ').trim();
    const estoque = new Map();
    try { _estoqueProdutosAcabados().forEach(e => estoque.set(_normE(e.produto), e)); } catch(e) {}
    const _achaEst = nome => { const n = _normE(nome); if (estoque.has(n)) return estoque.get(n); for (const [k, v] of estoque) { if (k.length >= 6 && (k.startsWith(n) || n.startsWith(k))) return v; } return null; };
    const lista = [...itens.values()].map(i => { const e = _achaEst(i.produto); return { ...i, peso_total: +(i.quantidade * i.peso_kg).toFixed(1), valor_total: +(i.quantidade * i.vlr_unit).toFixed(2),
      estoque_saldo: e ? Math.round(e.saldo_estoque) : null, estoque_disponivel: e ? Math.round(e.disponivel_apos_rota) : null, estoque_em_rota: e ? Math.round(e.em_rota) : 0, estoque_pendente: e ? Math.round(e.pendente) : 0 }; });
    const cargas = queryAll("SELECT pedido_venda, carga_num, SUM(quantidade) AS volumes, SUM(valor_total) AS valor, MAX(situacao) AS situacao FROM pedidos WHERE pedido_origem=? AND COALESCE(cancelado,0)=0 GROUP BY pedido_venda ORDER BY carga_num", [nr]);
    const caminhoes = queryAll('SELECT placa, modelo, capacidade_kg FROM caminhoes ORDER BY placa');
    const t = linhas[0];
    res.json({ ok: true, pedido: nr, cliente: t.razao_social || '', situacao: t.situacao || '', itens: lista,
      peso_total: +lista.reduce((a, i) => a + i.peso_total, 0).toFixed(1), valor_total: +lista.reduce((a, i) => a + i.valor_total, 0).toFixed(2),
      cargas_separadas: cargas.map(c => ({ pedido_venda: c.pedido_venda, carga: c.carga_num, volumes: +c.volumes || 0, valor: +(+c.valor || 0).toFixed(2), situacao: c.situacao || '' })),
      caminhoes, pedido_origem: t.pedido_origem || '', carga_num: +t.carga_num || 0 });
  }));
  app.post('/api/pedidos/:nr/separar-carga', rota((req, res) => {
    const nr = String(req.params.nr || '').trim();
    if (ehRepresentante(req.usuario) && !ehDono(req.usuario)) return res.status(403).json({ erro: 'Representante não separa carga — peça ao escritório.' });
    const b = req.body || {};
    const pedidos_itens = Array.isArray(b.itens) ? b.itens : [];
    const linhas = queryAll('SELECT * FROM pedidos WHERE pedido_venda=? ORDER BY id', [nr]);
    if (!linhas.length) return res.status(404).json({ erro: 'Pedido não encontrado.' });
    const tpl = { ...linhas[0] };
    const sitU = String(tpl.situacao || '').toUpperCase();
    if (linhas.some(l => l.cancelado)) return res.status(400).json({ erro: 'Pedido cancelado não pode ser separado.' });
    if (/ENTREGUE|CARREGANDO|REMESSA/.test(sitU)) return res.status(400).json({ erro: `Pedido ${nr} está "${tpl.situacao}" — separe a carga antes de montar a rota.` });
    if (tpl.nota_mae) return res.status(400).json({ erro: 'Nota mãe (entrega futura) não se separa em cargas — as remessas já fazem esse papel.' });
    if (tpl.ef_remessa) return res.status(400).json({ erro: 'Remessa de entrega futura não se separa.' });
    if (queryOne(`SELECT id FROM nfe_emitidas WHERE pedido_venda=? AND status IN ('autorizado','processando') AND COALESCE(ambiente,'producao')='producao' LIMIT 1`, [nr]))
      return res.status(400).json({ erro: `O pedido ${nr} já tem NF-e emitida — não dá mais para separar carga dele. Cancele/devolva a nota primeiro.` });
    const _np = x => String(x || '').trim().toUpperCase();
    const orig = new Map();
    linhas.forEach(l => { const k = _np(l.produto); if (!orig.has(k)) orig.set(k, { produto: l.produto, quantidade: 0, vlr_unit: +l.vlr_unit || 0 }); orig.get(k).quantidade += (+l.quantidade || 0); });
    const carga = new Map();
    for (const it of pedidos_itens) {
      const k = _np(it.produto); const q = Math.round(+it.quantidade || 0);
      if (!orig.has(k)) return res.status(400).json({ erro: `Produto "${it.produto}" não está no pedido.` });
      if (q < 0) return res.status(400).json({ erro: 'Quantidade negativa.' });
      if (q > orig.get(k).quantidade) return res.status(400).json({ erro: `${orig.get(k).produto}: o pedido só tem ${orig.get(k).quantidade} e a carga pede ${q}.` });
      carga.set(k, (carga.get(k) || 0) + q);
    }
    const volCarga = [...carga.values()].reduce((t, q) => t + q, 0);
    if (volCarga <= 0) return res.status(400).json({ erro: 'A carga está vazia — informe quantos volumes de cada produto vão neste caminhão.' });
    const volTotal = [...orig.values()].reduce((t, o) => t + o.quantidade, 0);
    if (volCarga >= volTotal) return res.status(400).json({ erro: `Esta carga leva o pedido inteiro (${volTotal} volumes) — então ela é o próprio pedido ${nr}, não precisa separar. Separe só quando sobrar algo para outro caminhão.` });
    const unidade = tpl.empresa_id || 'emp1';
    let { nr: novo } = proximoNumeroPedidoLivre(unidade);
    while (queryOne('SELECT id FROM pedidos WHERE pedido_venda=? LIMIT 1', [novo])) novo = String(parseInt(novo, 10) + 1).padStart(String(novo).length, '0');
    const nCarga = ((queryOne('SELECT MAX(carga_num) AS m FROM pedidos WHERE pedido_origem=?', [nr]) || {}).m || 0) + 1;
    const hoje = new Date().toLocaleDateString('pt-BR');
    const caminhao = String(b.caminhao || '').trim();
    const excluir = new Set(['id', 'criado_em', 'produto', 'quantidade', 'vlr_unit', 'valor_total']);
    const cols = Object.keys(tpl).filter(k => !excluir.has(k));
    const todasCols = [...cols, 'produto', 'quantidade', 'vlr_unit', 'valor_total'];
    const ph = todasCols.map(() => '?').join(',');
    const obsBase = String(tpl.obs || '').replace(/\s*\[CARGA [^\]]*\]/g, '').trim();
    const obsLimpa = (obsBase && obsBase !== '-') ? obsBase + ' ' : '';
    // 1) o pedido novo com a carga
    const cab = { ...tpl, pedido_venda: novo, obs: obsLimpa + `[CARGA ${nCarga} do pedido ${nr} — separada em ${hoje}${caminhao ? ' · caminhão ' + caminhao : ''}]`,
                  motorista: null, caminhao: null, data_prevista: null, data_entrega: null, ordem_rota: null, pedido_origem: nr, carga_num: nCarga, carga_qtd: 0 };
    let totC = 0;
    for (const [k, q] of carga) { if (q <= 0) continue; const o = orig.get(k); const vt = +(q * o.vlr_unit).toFixed(2); totC += vt;
      db.run(`INSERT INTO pedidos (${todasCols.join(',')}) VALUES (${ph})`, [...cols.map(c => cab[c]), o.produto, q, o.vlr_unit, vt]);
      db.run('INSERT INTO pedido_itens (pedido_venda, produto, quantidade, vlr_unit, valor_total) VALUES (?,?,?,?,?)', [novo, o.produto, q, o.vlr_unit, vt]); }
    // 2) o original fica com o restante
    db.run('DELETE FROM pedidos WHERE pedido_venda=?', [nr]); db.run('DELETE FROM pedido_itens WHERE pedido_venda=?', [nr]);
    const cabO = { ...tpl, obs: obsLimpa + `[CARGAS separadas deste pedido: ${queryAll('SELECT DISTINCT pedido_venda FROM pedidos WHERE pedido_origem=? ORDER BY carga_num', [nr]).map(x => x.pedido_venda).join(', ')} — o restante fica aqui]`, carga_qtd: nCarga };
    let totO = 0, volO = 0;
    for (const [k, o] of orig) { const q = o.quantidade - (carga.get(k) || 0); if (q <= 0) continue; const vt = +(q * o.vlr_unit).toFixed(2); totO += vt; volO += q;
      db.run(`INSERT INTO pedidos (${todasCols.join(',')}) VALUES (${ph})`, [...cols.map(c => cabO[c]), o.produto, q, o.vlr_unit, vt]);
      db.run('INSERT INTO pedido_itens (pedido_venda, produto, quantidade, vlr_unit, valor_total) VALUES (?,?,?,?,?)', [nr, o.produto, q, o.vlr_unit, vt]); }
    try { recalcularSituacaoPedidos([nr, novo]); } catch(e) {}
    try { _atualizarResumoCargas(nr); } catch(e) {}   // v.413
    registrarLog('CARGA SEPARADA DO PEDIDO', `${nr} (${tpl.razao_social || ''}) → carga ${nCarga} = pedido ${novo}: ${volCarga} volume(s) · R$ ${totC.toFixed(2)}${caminhao ? ' · caminhão ' + caminhao : ''} · restam ${volO} volume(s) (R$ ${totO.toFixed(2)}) no ${nr}`, '', '', req.usuario?.nome || 'sistema');
    salvarArquivo();
    res.json({ ok: true, origem: nr, carga: nCarga, pedido_venda: novo, volumes: volCarga, valor: +totC.toFixed(2), restante: { volumes: volO, valor: +totO.toFixed(2) } });
  }));

  // Desfazer roteiro — reverte TODOS os pedidos da mesma rota para AGUARDANDO ROTA
  app.post('/api/pedidos/desfazer-rota', rota((req, res) => {
    const { pedido_venda } = req.body;
    if (!pedido_venda) return res.status(400).json({ erro: 'pedido_venda obrigatório' });
    // Buscar motorista e caminhão do pedido para identificar a rota completa
    const ref = queryOne(
      "SELECT motorista, caminhao, data_prevista FROM pedidos WHERE pedido_venda=? AND situacao='CARREGANDO'",
      [pedido_venda]
    );
    if (!ref) return res.json({ ok: true, atualizados: 0 });
    // Desfazer todos os pedidos da mesma rota (mesmo motorista + caminhão + data)
    db.run(
      "UPDATE pedidos SET situacao='AGUARDANDO ROTA', motorista='-', caminhao='-', data_prevista=NULL WHERE situacao='CARREGANDO' AND motorista=? AND caminhao=? AND data_prevista=?",
      [ref.motorista, ref.caminhao, ref.data_prevista]
    );
    const atualizados = db.getRowsModified();
    salvarArquivo();
    res.json({ ok: true, atualizados, motorista: ref.motorista, caminhao: ref.caminhao });
  }));

  // Gerar roteiro — define motorista, caminhão e data prevista em lote
  app.post('/api/pedidos/roteiro', rota((req, res) => {
    const { pedidos, motorista, caminhao, data_prevista } = req.body;
    if (!Array.isArray(pedidos) || !pedidos.length) return res.status(400).json({ erro: 'Lista de pedidos vazia.' });
    if (!motorista || !data_prevista) return res.status(400).json({ erro: 'Motorista e data obrigatórios.' });
    let atualizados = 0;
    // Data de início do carregamento (formato YYYY-MM-DD para comparações)
    const hoje = new Date();
    const dataInicio = hoje.getFullYear() + '-' +
      String(hoje.getMonth()+1).padStart(2,'0') + '-' +
      String(hoje.getDate()).padStart(2,'0');
    for (let i = 0; i < pedidos.length; i++) {
      const nr = pedidos[i];
      // v.161: ordem_rota guarda a sequencia planejada das paradas (1, 2, 3...)
      db.run(
        "UPDATE pedidos SET situacao='CARREGANDO',motorista=?,caminhao=?,data_prevista=?,data_inicio_carregamento=?,ordem_rota=? WHERE pedido_venda=? AND situacao!='PEDIDO ENTREGUE' AND (cancelado IS NULL OR cancelado=0) AND situacao<>'CANCELADO'",
        [motorista, caminhao||null, data_prevista, dataInicio, i + 1, nr]
      );
      if (db.getRowsModified() > 0) atualizados++;
    }
    salvarArquivo();
    res.json({ ok: true, atualizados });
  }));

  // Editar dados de pedido pendente (apenas cidade e observação — dados críticos preservados)
  app.put('/api/pedidos/editar-pendente/:pedido_venda', rota((req, res) => {
    const { cidade, obs } = req.body;
    const pedido = req.params.pedido_venda;
    const existe = queryOne('SELECT id,situacao,cidade,obs FROM pedidos WHERE pedido_venda=?', [pedido]);
    if (!existe) return res.status(404).json({ ok: false, erro: 'Pedido não encontrado.' });
    if (existe.situacao === 'PEDIDO ENTREGUE') {
      return res.status(400).json({ ok: false, erro: 'Pedidos entregues devem ser editados pela tela de Pedidos Entregues.' });
    }
    // Atualiza somente campos permitidos
    const campos = [];
    const params = [];
    if (cidade !== undefined) { campos.push('cidade=?'); params.push(cidade); }
    if (obs !== undefined) { campos.push('obs=?'); params.push(obs); }
    if (!campos.length) return res.status(400).json({ ok: false, erro: 'Nenhum campo para atualizar.' });
    params.push(pedido);
    db.run(`UPDATE pedidos SET ${campos.join(', ')} WHERE pedido_venda=?`, params);
    const atualizados = db.getRowsModified();
    registrarLog('EDIÇÃO DE PEDIDO PENDENTE',
      `Pedido ${pedido}`,
      'Edição de cidade/observação',
      JSON.stringify({antes:existe,depois:{cidade,obs}}),
      req.usuario?.nome||'sistema');
    salvarArquivo();
    res.json({ ok: true, atualizados });
  }));

  // Edita os ITENS de um pedido (produtos, quantidades e valores), preservando o cabeçalho.
  // Também aceita cidade/obs opcionais. Regrava as linhas do pedido a partir do 1º registro.
  app.put('/api/pedidos/:nr/itens', rota((req, res) => {
    const nr = String(req.params.nr || '').trim();
    const b = req.body || {};
    const itens = Array.isArray(b.itens) ? b.itens : [];
    if (!itens.length) return res.status(400).json({ erro: 'Informe ao menos um produto.' });
    const linhas = queryAll('SELECT * FROM pedidos WHERE pedido_venda=? ORDER BY id', [nr]);
    if (!linhas.length) return res.status(404).json({ erro: 'Pedido não encontrado.' });
    const tpl = { ...linhas[0] };
    if (String(tpl.situacao || '').toUpperCase().includes('ENTREGUE'))
      return res.status(400).json({ erro: 'Pedido já entregue não pode ter os itens editados.' });
    // valida os itens ANTES de apagar qualquer coisa
    for (const it of itens) {
      if (!it.produto || !String(it.produto).trim()) return res.status(400).json({ erro: 'Há um item sem produto.' });
      const q = Math.round(+it.quantidade || 0);
      if (!Number.isInteger(q) || q <= 0) return res.status(400).json({ erro: `Quantidade inválida em "${it.produto}": use inteiros.` });
      if ((+it.vlr_unit || 0) < 0) return res.status(400).json({ erro: `Valor inválido em "${it.produto}".` });
    }
    if (b.cidade !== undefined) tpl.cidade = b.cidade;
    if (b.obs !== undefined) tpl.obs = b.obs;
    // colunas de cabeçalho a preservar (exclui id/criado_em e os campos do próprio item)
    const excluir = new Set(['id', 'criado_em', 'produto', 'quantidade', 'vlr_unit', 'valor_total']);
    const cols = Object.keys(tpl).filter(k => !excluir.has(k));
    const todasCols = [...cols, 'produto', 'quantidade', 'vlr_unit', 'valor_total'];
    const ph = todasCols.map(() => '?').join(',');
    // apaga os itens atuais e regrava
    db.run('DELETE FROM pedidos WHERE pedido_venda=?', [nr]);
    db.run('DELETE FROM pedido_itens WHERE pedido_venda=?', [nr]);
    let total = 0;
    itens.forEach(it => {
      const q = Math.round(+it.quantidade || 0), v = +it.vlr_unit || 0, vt = +(q * v).toFixed(2);
      total += vt;
      db.run(`INSERT INTO pedidos (${todasCols.join(',')}) VALUES (${ph})`, [...cols.map(c => tpl[c]), String(it.produto).trim(), q, v, vt]);
      db.run('INSERT INTO pedido_itens (pedido_venda, produto, quantidade, vlr_unit, valor_total) VALUES (?,?,?,?,?)', [nr, String(it.produto).trim(), q, v, vt]);
    });
    registrarLog('EDIÇÃO DE ITENS DO PEDIDO', `${nr} — ${itens.length} item(ns) — total ${total.toFixed(2)}`, '', '', req.usuario?.nome || 'sistema');
    salvarArquivo();
    res.json({ ok: true, pedido_venda: nr, itens: itens.length, total: +total.toFixed(2) });
  }));

  app.put('/api/pedidos/entregar/:pedido_venda', rota((req, res) => {
    const { situacao, data_entrega, motorista, caminhao, frete, obs } = req.body;
    const pedido = req.params.pedido_venda;
    const existe = queryOne('SELECT id,situacao,motorista,caminhao,frete,obs FROM pedidos WHERE pedido_venda=?', [pedido]);
    if (!existe) return res.status(404).json({ ok: false, erro: 'Pedido não encontrado.' });
    // Se só veio data_entrega (edição de data pós-entrega), atualiza só a data
    if (data_entrega && !situacao) {
      db.run('UPDATE pedidos SET data_entrega=? WHERE pedido_venda=?', [data_entrega, pedido]);
      salvarArquivo();
      return res.json({ ok: true });
    }
    const freteValido = (frete === 'FOB') ? 'FOB' : 'CIF';
    db.run(
      'UPDATE pedidos SET situacao=?,data_entrega=?,motorista=?,caminhao=?,frete=?,obs=? WHERE pedido_venda=?',
      [situacao||existe.situacao, data_entrega, motorista||existe.motorista, caminhao||existe.caminhao, freteValido, obs||existe.obs||null, pedido]
    );
    salvarArquivo();
    res.json({ ok: true });
  }));

  // ─── EXCLUSÃO — rotas específicas ANTES da genérica /:pedido_venda ──────────
  app.delete('/api/pedidos/lote/entregues', rota((req, res) => {
    const qtd = queryAll("SELECT COUNT(*) as n FROM pedidos WHERE situacao='PEDIDO ENTREGUE'")[0]?.n||0;
    db.run("DELETE FROM pedidos WHERE situacao='PEDIDO ENTREGUE'");
    registrarLog('EXCLUSÃO EM LOTE','Pedidos entregues removidos',`${qtd} pedido(s) excluídos`,'','sistema');
    salvarArquivo(); res.json({ ok: true });
  }));

  app.delete('/api/pedidos/lote/periodo', rota((req, res) => {
    const { de, ate } = req.body;
    if (!de || !ate) return res.status(400).json({ erro: 'Informe datas.' });
    const qtd = queryAll('SELECT COUNT(*) as n FROM pedidos WHERE data >= ? AND data <= ?',[de,ate])[0]?.n||0;
    db.run('DELETE FROM pedidos WHERE data >= ? AND data <= ?', [de, ate]);
    registrarLog('EXCLUSÃO EM LOTE',`Pedidos período ${de} a ${ate}`,`${qtd} pedido(s) excluídos`,'','sistema');
    salvarArquivo(); res.json({ ok: true });
  }));

  app.delete('/api/pedidos/lote/todos', rota((req, res) => {
    const qtd = queryAll('SELECT COUNT(*) as n FROM pedidos')[0]?.n||0;
    registrarLog('EXCLUSÃO TOTAL','TODOS OS PEDIDOS REMOVIDOS',`${qtd} pedido(s)  excluídos`,'AÇÃO CRÍTICA','sistema');
    db.exec('DELETE FROM pedidos; DELETE FROM regioes;');
    salvarArquivo(); res.json({ ok: true });
  }));

  /* v.411: CARGA EXCLUÍDA/CANCELADA VOLTA PARA O PEDIDO DE ORIGEM. Separou uma carga e
     excluiu o pedido dela? Os volumes voltam para o pedido grande (somam na linha do mesmo
     produto; se a linha não existe mais, é recriada). Só não volta se o pedido de origem
     já tem NF-e emitida ou foi cancelado — aí fica registrado no Log para acerto à mão. */
  /* v.413: o pedido de origem mostra SÓ as cargas que existem. Contador (carga_qtd) e a
     marca na obs são refeitos a partir das cargas vivas — carga excluída/cancelada some
     do aviso "N carga(s) separada(s)". Roda ao separar, devolver, reativar e no boot. */
  function _atualizarResumoCargas(origem) {
    origem = String(origem || '').trim(); if (!origem) return 0;
    const vivas = queryAll("SELECT DISTINCT pedido_venda FROM pedidos WHERE pedido_origem=? AND COALESCE(cancelado,0)=0 ORDER BY carga_num, pedido_venda", [origem]).map(x => x.pedido_venda);
    const linhas = queryAll('SELECT id, obs FROM pedidos WHERE pedido_venda=?', [origem]);
    if (!linhas.length) return 0;
    linhas.forEach(l => {
      const base = String(l.obs || '').replace(/\s*\[CARGAS? [^\]]*\]/gi, '').trim();
      const obs = vivas.length ? ((base && base !== '-' ? base + ' ' : '') + `[CARGAS separadas deste pedido: ${vivas.join(', ')} — o restante fica aqui]`) : (base || '-');
      db.run('UPDATE pedidos SET carga_qtd=?, obs=? WHERE id=?', [vivas.length, obs, l.id]);
    });
    return vivas.length;
  }
  setTimeout(() => { try {
    const origens = queryAll("SELECT DISTINCT pedido_venda FROM pedidos WHERE COALESCE(carga_qtd,0)>0 OR obs LIKE '%[CARGAS%' OR pedido_venda IN (SELECT pedido_origem FROM pedidos WHERE COALESCE(pedido_origem,'')<>'')");
    let m = 0; origens.forEach(o => { const antes = (queryOne('SELECT carga_qtd FROM pedidos WHERE pedido_venda=? LIMIT 1', [o.pedido_venda]) || {}).carga_qtd || 0; const n = _atualizarResumoCargas(o.pedido_venda); if (n !== antes) m++; });
    if (m) { salvarArquivo(); console.log(`🚛 ${m} pedido(s) com o resumo de cargas corrigido`); }
  } catch(e) { console.warn('resumo de cargas:', e && e.message); } }, 38000);
  function _devolverCargaAoPedido(nrCarga, quem, motivoAcao) {
    const carga = queryAll('SELECT * FROM pedidos WHERE pedido_venda=? AND COALESCE(cancelado,0)=0 ORDER BY id', [nrCarga]);
    if (!carga.length) return null;
    const origem = String(carga[0].pedido_origem || '').trim();
    if (!origem) return null;
    const linhasO = queryAll('SELECT * FROM pedidos WHERE pedido_venda=? ORDER BY id', [origem]);
    const detalhe = carga.map(l => `${l.produto}: ${+l.quantidade || 0}`).join(' · ');
    if (!linhasO.length || linhasO.every(l => l.cancelado)) {
      registrarLog('CARGA NÃO DEVOLVIDA', `${nrCarga} (${motivoAcao}) era carga do pedido ${origem}, que ${linhasO.length ? 'está cancelado' : 'não existe mais'} — os volumes NÃO voltaram: ${detalhe}`, '', '', quem);
      return { ok: false, origem, motivo: 'origem_indisponivel' };
    }
    if (queryOne(`SELECT id FROM nfe_emitidas WHERE pedido_venda=? AND status IN ('autorizado','processando') AND COALESCE(ambiente,'producao')='producao' LIMIT 1`, [origem])) {
      registrarLog('CARGA NÃO DEVOLVIDA', `${nrCarga} (${motivoAcao}) era carga do pedido ${origem}, que já tem NF-e — os volumes NÃO voltaram (acerte à mão): ${detalhe}`, '', '', quem);
      return { ok: false, origem, motivo: 'origem_com_nota' };
    }
    const _np = x => String(x || '').trim().toUpperCase();
    const tpl = { ...linhasO.find(l => !l.cancelado) };
    const excluir = new Set(['id', 'criado_em', 'produto', 'quantidade', 'vlr_unit', 'valor_total']);
    const cols = Object.keys(tpl).filter(k => !excluir.has(k));
    const todasCols = [...cols, 'produto', 'quantidade', 'vlr_unit', 'valor_total'];
    const ph = todasCols.map(() => '?').join(',');
    let volumes = 0, valor = 0;
    carga.forEach(l => {
      const q = +l.quantidade || 0; if (q <= 0) return;
      const vu = +l.vlr_unit || 0;
      const alvo = linhasO.find(o => !o.cancelado && _np(o.produto) === _np(l.produto));
      if (alvo) {
        const nq = (+alvo.quantidade || 0) + q; const nvu = +alvo.vlr_unit || vu;
        db.run('UPDATE pedidos SET quantidade=?, valor_total=? WHERE id=?', [nq, +(nq * nvu).toFixed(2), alvo.id]); alvo.quantidade = nq;
        const pi = queryOne('SELECT id, quantidade FROM pedido_itens WHERE pedido_venda=? AND produto=? COLLATE NOCASE', [origem, l.produto]);
        if (pi) db.run('UPDATE pedido_itens SET quantidade=?, valor_total=? WHERE id=?', [(+pi.quantidade || 0) + q, +(((+pi.quantidade || 0) + q) * nvu).toFixed(2), pi.id]);
        else db.run('INSERT INTO pedido_itens (pedido_venda, produto, quantidade, vlr_unit, valor_total) VALUES (?,?,?,?,?)', [origem, l.produto, nq, nvu, +(nq * nvu).toFixed(2)]);
      } else {
        const vt = +(q * vu).toFixed(2);
        db.run(`INSERT INTO pedidos (${todasCols.join(',')}) VALUES (${ph})`, [...cols.map(c => tpl[c]), l.produto, q, vu, vt]);
        db.run('INSERT INTO pedido_itens (pedido_venda, produto, quantidade, vlr_unit, valor_total) VALUES (?,?,?,?,?)', [origem, l.produto, q, vu, vt]);
        linhasO.push({ produto: l.produto, quantidade: q, vlr_unit: vu, cancelado: 0, id: (queryOne('SELECT last_insert_rowid() AS id') || {}).id });
      }
      volumes += q; valor += q * vu;
    });
    // contador de cargas do pedido de origem (sem esta)
    // resumo do pedido de origem SEM esta carga (ela é apagada/cancelada pelo chamador logo em seguida)
    const _vivasDepois = queryAll("SELECT DISTINCT pedido_venda FROM pedidos WHERE pedido_origem=? AND pedido_venda<>? AND COALESCE(cancelado,0)=0 ORDER BY carga_num", [origem, nrCarga]).map(x => x.pedido_venda);
    queryAll('SELECT id, obs FROM pedidos WHERE pedido_venda=?', [origem]).forEach(l => {
      const base = String(l.obs || '').replace(/\s*\[CARGAS? [^\]]*\]/gi, '').trim();
      const obs = _vivasDepois.length ? ((base && base !== '-' ? base + ' ' : '') + `[CARGAS separadas deste pedido: ${_vivasDepois.join(', ')} — o restante fica aqui]`) : (base || '-');
      db.run('UPDATE pedidos SET carga_qtd=?, obs=? WHERE id=?', [_vivasDepois.length, obs, l.id]); });
    registrarLog('CARGA DEVOLVIDA AO PEDIDO', `${nrCarga} (${motivoAcao}) → ${volumes} volume(s) (R$ ${valor.toFixed(2)}) voltaram para o pedido ${origem}: ${detalhe}`, '', '', quem);
    return { ok: true, origem, volumes, valor: +valor.toFixed(2) };
  }
  app.delete('/api/pedidos/:pedido_venda', rota((req, res) => {
    const pedido = req.params.pedido_venda;
    const motivo = req.headers['x-motivo'] || req.query.motivo || '-';
    const info = queryOne('SELECT razao_social,cidade,valor_total,situacao FROM pedidos WHERE pedido_venda=?', [pedido]);
    if (!info) return res.status(404).json({ ok: false, erro: 'Pedido não encontrado.' });

    // Trava 1: pedido já faturado (nota de PRODUÇÃO) não pode ser excluído.
    // Notas de homologação são testes e não bloqueiam.
    // v.381: pode ser liberada com ?forcar_nota=1 — o pedido sai da logística e a nota
    // fica intacta em Notas Emitidas (faturamento, títulos e boletos continuam pela nota).
    const nfe = queryOne(`SELECT numero FROM nfe_emitidas
                          WHERE pedido_venda=? AND status='autorizado' AND ambiente='producao' LIMIT 1`, [pedido]);
    const forcarNota = req.query.forcar_nota === '1' || req.headers['x-forcar-nota'] === '1';
    if (nfe && !forcarNota) return res.status(409).json({ ok: false, motivo: 'nota', numero: nfe.numero || '',
      erro: `O pedido ${pedido} já tem NF-e autorizada${nfe.numero ? ' (nº ' + nfe.numero + ')' : ''}.` });

    // Trava 2: pedido com boleto já enviado ao banco.
    // Pode ser liberada com ?forcar_boleto=1 (o usuário confirma que o boleto foi
    // baixado/cancelado no banco). Nesse caso o registro do boleto também é apagado.
    // v.381: quando a nota fica, os boletos são da NOTA e ficam junto com ela.
    const boletos = nfe ? [] : queryAll('SELECT id, nosso_numero, valor FROM boletos_gerados WHERE pedido_venda=?', [pedido]);
    const forcarBoleto = req.query.forcar_boleto === '1' || req.headers['x-forcar-boleto'] === '1';
    if (boletos.length && !forcarBoleto) {
      return res.status(409).json({ ok: false, motivo: 'boleto', qtd: boletos.length,
        erro: `O pedido ${pedido} tem ${boletos.length} boleto(s) já gerado(s) e enviado(s) ao banco.` });
    }
    if (boletos.length && forcarBoleto) {
      db.run('DELETE FROM boletos_gerados WHERE pedido_venda=?', [pedido]);
      registrarLog('EXCLUSÃO DE BOLETOS DO PEDIDO', `${pedido} — ${boletos.length} boleto(s) removido(s) junto com o pedido`,
        motivo, '', req.usuario?.nome || 'sistema');
    }

    const qtdLinhas = queryAll('SELECT id FROM pedidos WHERE pedido_venda=?', [pedido]).length;
    // v.411: carga separada → os volumes voltam para o pedido de origem antes de apagar
    let _devolvida = null; try { _devolvida = _devolverCargaAoPedido(pedido, req.usuario?.nome || 'sistema', 'excluída'); } catch(e) { console.warn('devolver carga:', e && e.message); }
    // v.411: o Log guarda os itens — sem isso uma exclusão por engano não tem volta
    try { const _its = queryAll('SELECT produto, quantidade, vlr_unit FROM pedidos WHERE pedido_venda=?', [pedido]); registrarLog('ITENS DO PEDIDO EXCLUÍDO', `${pedido}: ` + _its.map(i => `${i.produto} ${+i.quantidade || 0} × ${(+i.vlr_unit || 0).toFixed(2)}`).join(' · '), motivo, '', req.usuario?.nome || 'sistema'); } catch(e) {}
    db.run('DELETE FROM pedidos WHERE pedido_venda=?', [pedido]);
    db.run('DELETE FROM pedido_itens WHERE pedido_venda=?', [pedido]);
    if (!nfe) {   // v.381: com a nota mantida, a cobrança (fila/dispensas) é da nota e fica
      db.run('DELETE FROM boletos_fila WHERE pedido_venda=?', [pedido]);
      db.run('DELETE FROM boletos_dispensados WHERE pedido_venda=?', [pedido]);
    }
    registrarLog(nfe ? 'EXCLUSÃO DE PEDIDO (nota mantida)' : 'EXCLUSÃO DE PEDIDO',
      `Pedido ${pedido} — ${info.razao_social||'?'} — ${info.cidade||'?'}${nfe ? ' — NF-e nº ' + (nfe.numero || '?') + ' mantida' : ''}`,
      motivo,
      `Situação: ${info.situacao} | Valor: R$ ${(info.valor_total||0).toFixed(2)}`,
      req.usuario?.nome||'sistema'
    );
    salvarArquivo();
    res.json({ ok: true, linhas: qtdLinhas, nota_mantida: nfe ? (nfe.numero || true) : null, carga_devolvida: _devolvida || null });
  }));

  // Exclusão PERMANENTE em lote de pedidos (tela Consultar Pedidos)
  app.post('/api/pedidos/excluir-lote', rota((req, res) => {
    const pedidos = Array.isArray(req.body && req.body.pedidos) ? req.body.pedidos.map(String) : [];
    const motivo = String((req.body && req.body.motivo) || '-').trim() || '-';
    const forcarBoleto = !!(req.body && req.body.forcar_boleto);
    if (!pedidos.length) return res.status(400).json({ erro: 'Nenhum pedido informado.' });
    const usr = req.usuario?.nome || 'sistema';
    let excluidos = 0;
    const ignorados = [];
    pedidos.forEach(pedido => {
      const info = queryOne('SELECT razao_social,cidade,valor_total,situacao FROM pedidos WHERE pedido_venda=?', [pedido]);
      if (!info) { ignorados.push({ pedido, motivo: 'não encontrado' }); return; }
      const nfe = queryOne(`SELECT numero FROM nfe_emitidas WHERE pedido_venda=? AND status='autorizado' AND ambiente='producao' LIMIT 1`, [pedido]);
      if (nfe) { ignorados.push({ pedido, motivo: 'tem NF-e autorizada' + (nfe.numero ? ' (nº ' + nfe.numero + ')' : '') }); return; }
      const boletos = queryAll('SELECT id FROM boletos_gerados WHERE pedido_venda=?', [pedido]);
      if (boletos.length && !forcarBoleto) { ignorados.push({ pedido, motivo: boletos.length + ' boleto(s) já gerado(s)' }); return; }
      if (boletos.length && forcarBoleto) db.run('DELETE FROM boletos_gerados WHERE pedido_venda=?', [pedido]);
      try { _devolverCargaAoPedido(pedido, usr, 'excluída em lote'); } catch(e) { console.warn('devolver carga (lote):', e && e.message); }   // v.412
      try { const _its = queryAll('SELECT produto, quantidade, vlr_unit FROM pedidos WHERE pedido_venda=?', [pedido]); registrarLog('ITENS DO PEDIDO EXCLUÍDO', `${pedido}: ` + _its.map(i => `${i.produto} ${+i.quantidade || 0} × ${(+i.vlr_unit || 0).toFixed(2)}`).join(' · '), motivo, '', usr); } catch(e) {}
      db.run('DELETE FROM pedidos WHERE pedido_venda=?', [pedido]);
      db.run('DELETE FROM pedido_itens WHERE pedido_venda=?', [pedido]);
      db.run('DELETE FROM boletos_fila WHERE pedido_venda=?', [pedido]);
      db.run('DELETE FROM boletos_dispensados WHERE pedido_venda=?', [pedido]);
      registrarLog('EXCLUSÃO PERMANENTE DE PEDIDO (lote)',
        `Pedido ${pedido} — ${info.razao_social||'?'} — ${info.cidade||'?'}`,
        motivo, `Situação: ${info.situacao} | Valor: R$ ${(info.valor_total||0).toFixed(2)}`, usr);
      excluidos++;
    });
    if (excluidos) salvarArquivo();
    res.json({ ok: true, excluidos, ignorados });
  }));

  // ═══ v.388: MANIFESTO ELETRÔNICO (MDF-e) ═══════════════════════════════════════
  /* O caminhão sai com várias NF-e para várias cidades: a lei exige um MDF-e por viagem
     (carga própria, modal rodoviário). O manifesto é emitido pela Focus NFe, com o mesmo
     token da NF-e do emitente; ao fim da viagem é ENCERRADO; se a viagem não aconteceu,
     CANCELADO. Tudo fica em mdfe_emitidos. Dados do veículo (tara, UF, RENAVAM, tipo) e do
     condutor (CPF) ficam no cadastro de caminhões/motoristas. Código IBGE das cidades de
     descarga sai do cadastro fiscal do cliente ou da API do IBGE (com cache). */
  try {
    db.exec(`CREATE TABLE IF NOT EXISTS mdfe_emitidos (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      ref TEXT UNIQUE NOT NULL, empresa_id TEXT DEFAULT '', ambiente TEXT DEFAULT '',
      status TEXT DEFAULT 'processando', status_sefaz TEXT DEFAULT '', mensagem_sefaz TEXT DEFAULT '',
      chave TEXT DEFAULT '', numero TEXT DEFAULT '', serie TEXT DEFAULT '', protocolo TEXT DEFAULT '',
      caminho_xml TEXT DEFAULT '', caminho_damdfe TEXT DEFAULT '', caminho_xml_encerramento TEXT DEFAULT '', caminho_xml_cancelamento TEXT DEFAULT '',
      motorista TEXT DEFAULT '', cpf_motorista TEXT DEFAULT '', caminhao TEXT DEFAULT '', data_prevista TEXT DEFAULT '',
      uf_inicio TEXT DEFAULT '', uf_fim TEXT DEFAULT '', municipios_json TEXT DEFAULT '[]', notas_json TEXT DEFAULT '[]', pedidos_json TEXT DEFAULT '[]',
      qtd_nfe INTEGER DEFAULT 0, peso_bruto REAL DEFAULT 0, valor_carga REAL DEFAULT 0,
      requisicao_json TEXT DEFAULT '', retorno_json TEXT DEFAULT '', unidade TEXT DEFAULT '',
      emitido_por TEXT DEFAULT '', encerrado_em TEXT DEFAULT '', cancelado_em TEXT DEFAULT '', justificativa TEXT DEFAULT '',
      criado_em TEXT DEFAULT (datetime('now','localtime')), atualizado_em TEXT DEFAULT (datetime('now','localtime'))
    )`);
    ['renavam TEXT DEFAULT \'\'', 'tara_kg INTEGER DEFAULT 0', 'uf_placa TEXT DEFAULT \'\'', 'tipo_rodado TEXT DEFAULT \'01\'', 'tipo_carroceria TEXT DEFAULT \'02\'']
      .forEach(c => { try { db.exec('ALTER TABLE caminhoes ADD COLUMN ' + c); } catch(e) {} });
    try { db.exec("ALTER TABLE motoristas ADD COLUMN cpf TEXT DEFAULT ''"); } catch(e) {}
  } catch(e) { console.warn('mdfe tabelas:', e && e.message); }

  const MDFE_CONFIG_PADRAO = { serie: '', tipo_carga: '05', descricao_produto: 'ARGAMASSAS, MASSAS E TINTAS', ncm_produto: '',
    seguro_ativo: 0, nome_seguradora: '', cnpj_seguradora: '', numero_apolice: '', numero_averbacao: '', rntrc: '', info_complementar: '' };
  function _mdfeConfig(){
    let c = {}; try { const r = queryOne("SELECT valor FROM fluxo_config WHERE chave='mdfe_config_json'"); if (r && r.valor) c = JSON.parse(r.valor) || {}; } catch(e) {}
    return Object.assign({}, MDFE_CONFIG_PADRAO, c);
  }
  const _normMun = s => String(s || '').toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
  // Código IBGE de um município: cadastro fiscal → API do IBGE (municipiosDaUF, já cacheada por UF)
  async function _codigoIbge(municipio, uf){
    const m = _normMun(municipio), u = String(uf || '').toUpperCase().trim();
    if (!m || u.length !== 2) return '';
    const cad = queryAll("SELECT municipio, uf, codigo_ibge FROM clientes_fiscais WHERE codigo_ibge IS NOT NULL AND codigo_ibge<>'' AND UPPER(uf)=?", [u])
      .find(c => _normMun(c.municipio) === m && /^\d{7}$/.test(String(c.codigo_ibge)));
    if (cad) return String(cad.codigo_ibge);
    try {
      const lista = await municipiosDaUF(u);
      const alvo = _normNome(municipio);
      let hit = lista.find(x => x.nome === alvo) || lista.find(x => x.nome.startsWith(alvo) || alvo.startsWith(x.nome));
      if (hit) return String(hit.id);
    } catch(e) { console.warn('IBGE:', e && e.message); }
    return '';
  }
  function _mdfeCfgEmitente(empresaId){
    return queryOne('SELECT * FROM nfe_config WHERE empresa_id=?', [empresaId]) || null;
  }
  function _mdfeFocus(cfg){
    const ambiente = cfg.ambiente || 'homologacao';
    const token = ambiente === 'producao' ? cfg.token_producao : cfg.token_homologacao;
    const base = ambiente === 'producao' ? 'https://api.focusnfe.com.br' : 'https://homologacao.focusnfe.com.br';
    return { ambiente, token, base, auth: 'Basic ' + Buffer.from(String(token || '') + ':').toString('base64') };
  }
  const _mdfeAbs = (base, p) => p ? (/^https?:/i.test(p) ? p : base + p) : '';

  // As CARGAS prontas: pedidos em CARREGANDO agrupados por motorista + caminhão + data prevista
  async function _mdfeCargas(req){
    const _fu = _filtroUnidade(req);
    const peds = queryAll(`SELECT pedido_venda, razao_social, cidade, motorista, caminhao, data_prevista, frete, situacao, COALESCE(empresa_id,'emp1') AS empresa_id
                             FROM pedidos WHERE UPPER(situacao)='CARREGANDO' AND COALESCE(cancelado,0)=0 AND pedido_venda IS NOT NULL AND pedido_venda<>''${_fu.sql}`, _fu.params);
    const grupos = new Map();
    peds.forEach(p => {
      const k = [p.motorista || '', p.caminhao || '', p.data_prevista || ''].join('|');
      if (!grupos.has(k)) grupos.set(k, { motorista: p.motorista || '', caminhao: p.caminhao || '', data_prevista: p.data_prevista || '', pedidos: new Map() });
      const g = grupos.get(k);
      if (!g.pedidos.has(p.pedido_venda)) g.pedidos.set(p.pedido_venda, { pedido_venda: p.pedido_venda, cliente: p.razao_social || '', cidade: p.cidade || '', frete: p.frete || 'CIF', empresa_id: p.empresa_id });
    });
    const jaManifestados = new Set();
    queryAll("SELECT notas_json FROM mdfe_emitidos WHERE status IN ('autorizado','processando','encerrado')").forEach(r => { try { (JSON.parse(r.notas_json || '[]') || []).forEach(n => jaManifestados.add(String(n.chave))); } catch(e) {} });
    const saida = [];
    for (const g of grupos.values()) {
      const cam = g.caminhao ? (queryOne('SELECT * FROM caminhoes WHERE placa=? COLLATE NOCASE', [g.caminhao]) || null) : null;
      const mot = g.motorista ? (queryOne('SELECT * FROM motoristas WHERE nome=? COLLATE NOCASE', [g.motorista]) || null) : null;
      const pedidos = [];
      for (const p of g.pedidos.values()) {
        const n = queryOne(`SELECT ref, numero, chave_nfe, valor_total, requisicao_json, empresa_id FROM nfe_emitidas
                             WHERE pedido_venda=? AND status='autorizado' AND COALESCE(ambiente,'producao')='producao' AND chave_nfe IS NOT NULL AND chave_nfe<>''
                               AND (ef_modo IS NULL OR ef_modo NOT IN ('devolucao','5922')) ORDER BY id DESC LIMIT 1`, [p.pedido_venda]);
        let rj = {}; try { rj = JSON.parse((n && n.requisicao_json) || '{}'); } catch(e) {}
        const peso = +(((rj.volumes || [])[0] || {}).peso_bruto || 0);
        const mun = String(rj.municipio_destinatario || p.cidade || '').trim();
        const uf = String(rj.uf_destinatario || '').toUpperCase().trim();
        const cli = queryOne('SELECT uf, municipio, codigo_ibge FROM clientes_fiscais WHERE razao_social=? COLLATE NOCASE LIMIT 1', [p.cliente]) || {};
        const ufFinal = uf || String(cli.uf || '').toUpperCase();
        const munFinal = mun || String(cli.municipio || '');
        const _tc = n ? (typeof totaisCobrancaNota === 'function' ? totaisCobrancaNota(n, rj) : {}) : {};
        pedidos.push({ pedido_venda: p.pedido_venda, cliente: p.cliente, frete: p.frete, empresa_id: p.empresa_id,
          nota: n ? { ref: n.ref, numero: n.numero || '', chave: n.chave_nfe, valor: +((+_tc.valor_nota > 0.009 ? +_tc.valor_nota : (+n.valor_total || 0))).toFixed(2), peso, empresa_id: n.empresa_id || 'emp1', ja_manifestada: jaManifestados.has(String(n.chave_nfe)) } : null,
          municipio: munFinal, uf: ufFinal, codigo_ibge: await _codigoIbge(munFinal, ufFinal) });
      }
      const comNota = pedidos.filter(p => p.nota && !p.nota.ja_manifestada);
      const muns = new Map();
      comNota.forEach(p => { const k = p.uf + '|' + _normMun(p.municipio); if (!muns.has(k)) muns.set(k, { municipio: p.municipio, uf: p.uf, codigo_ibge: p.codigo_ibge, notas: [] }); muns.get(k).notas.push(p.nota.chave); });
      const emps = {}; comNota.forEach(p => { emps[p.nota.empresa_id] = (emps[p.nota.empresa_id] || 0) + 1; });
      const emitente = Object.keys(emps).sort((a, b) => emps[b] - emps[a])[0] || (_unidadeAtiva(req) || 'emp1');
      const avisos = [];
      pedidos.filter(p => !p.nota).forEach(p => avisos.push(`Pedido ${p.pedido_venda} (${p.cliente}) ainda não tem NF-e autorizada — fica fora do manifesto.`));
      pedidos.filter(p => p.nota && p.nota.ja_manifestada).forEach(p => avisos.push(`A nota ${p.nota.numero} do pedido ${p.pedido_venda} já está em outro manifesto (em aberto ou encerrado) — não entra de novo.`));
      if (!cam) avisos.push(`Caminhão "${g.caminhao || '?'}" não está no cadastro de caminhões.`);
      else { if (!(+cam.tara_kg > 0)) avisos.push(`Caminhão ${cam.placa}: falta a TARA (kg) no cadastro.`); if (!cam.uf_placa) avisos.push(`Caminhão ${cam.placa}: falta a UF da placa no cadastro.`); }
      if (!mot) avisos.push(`Motorista "${g.motorista || '?'}" não está no cadastro de motoristas.`);
      else if (!/^\d{11}$/.test(String(mot.cpf || '').replace(/\D/g, ''))) avisos.push(`Motorista ${mot.nome}: falta o CPF no cadastro.`);
      [...muns.values()].filter(m => !m.codigo_ibge).forEach(m => avisos.push(`Cidade ${m.municipio}/${m.uf || '?'}: não achei o código IBGE — informe na hora de emitir.`));
      saida.push({ motorista: g.motorista, caminhao: g.caminhao, data_prevista: g.data_prevista,
        veiculo: cam ? { placa: cam.placa, modelo: cam.modelo || '', renavam: cam.renavam || '', tara_kg: +cam.tara_kg || 0, uf_placa: cam.uf_placa || '', tipo_rodado: cam.tipo_rodado || '01', tipo_carroceria: cam.tipo_carroceria || '02' } : null,
        condutor: mot ? { nome: mot.nome, cpf: String(mot.cpf || '').replace(/\D/g, '') } : null,
        emitente_sugerido: emitente, pedidos, municipios: [...muns.values()],
        qtd_nfe: comNota.length, peso_bruto: +comNota.reduce((t, p) => t + (p.nota.peso || 0), 0).toFixed(3),
        valor_carga: +comNota.reduce((t, p) => t + (p.nota.valor || 0), 0).toFixed(2),
        uf_fim: (comNota[comNota.length - 1] || {}).uf || '', pronto: comNota.length > 0 && !avisos.some(a => /TARA|UF da placa|CPF|IBGE|cadastro de/.test(a)), avisos });
    }
    saida.sort((a, b) => String(a.data_prevista).localeCompare(String(b.data_prevista)) || String(a.motorista).localeCompare(String(b.motorista)));
    return saida;
  }
  app.get('/api/mdfe/cargas', rota(async (req, res) => {
    try { res.json({ ok: true, cargas: await _mdfeCargas(req), config: _mdfeConfig(),
      emitentes: queryAll('SELECT empresa_id, nome_emitente, apelido, ambiente, cnpj_emitente FROM nfe_config ORDER BY empresa_id') }); }
    catch(e) { res.status(500).json({ erro: e.message }); }
  }));
  app.get('/api/mdfe/config', rota((req, res) => res.json({ ok: true, ..._mdfeConfig() })));
  app.put('/api/mdfe/config', rota((req, res) => {
    if (!ehDono(req.usuario)) return res.status(403).json({ erro: 'Só o administrador altera a configuração do MDF-e.' });
    const b = req.body || {}; const c = Object.assign({}, _mdfeConfig());
    Object.keys(MDFE_CONFIG_PADRAO).forEach(k => { if (b[k] !== undefined) c[k] = (k === 'seguro_ativo') ? (b[k] ? 1 : 0) : String(b[k] ?? '').trim(); });
    db.run("DELETE FROM fluxo_config WHERE chave='mdfe_config_json'");
    db.run("INSERT INTO fluxo_config (chave, valor) VALUES ('mdfe_config_json', ?)", [JSON.stringify(c)]);
    registrarLog('CONFIGURAÇÃO MDF-e', `série ${c.serie || 'auto'} · seguro ${c.seguro_ativo ? 'sim' : 'não'} · produto ${c.descricao_produto}`, '', '', req.usuario?.nome || 'sistema');
    salvarArquivo(); res.json({ ok: true, ...c });
  }));
  // dados do veículo e do condutor usados no manifesto (ficam no cadastro de caminhões/motoristas)
  app.put('/api/mdfe/veiculo', rota((req, res) => {
    const b = req.body || {}; const placa = String(b.placa || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
    if (!placa) return res.status(400).json({ erro: 'Informe a placa.' });
    const cam = queryOne("SELECT id FROM caminhoes WHERE REPLACE(REPLACE(UPPER(placa),'-',''),' ','')=?", [placa]);
    if (!cam) return res.status(404).json({ erro: 'Caminhão não está no cadastro (Motoristas / Caminhões).' });
    db.run('UPDATE caminhoes SET renavam=?, tara_kg=?, uf_placa=?, tipo_rodado=?, tipo_carroceria=? WHERE id=?',
      [String(b.renavam || '').replace(/\D/g, ''), Math.round(+b.tara_kg || 0), String(b.uf_placa || '').toUpperCase().slice(0, 2), String(b.tipo_rodado || '01'), String(b.tipo_carroceria || '02'), cam.id]);
    registrarLog('CAMINHÃO — DADOS DO MDF-e', `${placa}: tara ${b.tara_kg} kg · UF ${b.uf_placa} · RENAVAM ${b.renavam || '-'}`, '', '', req.usuario?.nome || 'sistema');
    salvarArquivo(); res.json({ ok: true });
  }));
  app.put('/api/mdfe/condutor', rota((req, res) => {
    const b = req.body || {}; const nome = String(b.nome || '').trim(); const cpf = String(b.cpf || '').replace(/\D/g, '');
    if (!nome) return res.status(400).json({ erro: 'Informe o motorista.' });
    if (cpf.length !== 11) return res.status(400).json({ erro: 'CPF deve ter 11 dígitos.' });
    const mot = queryOne('SELECT id FROM motoristas WHERE nome=? COLLATE NOCASE', [nome]);
    if (!mot) return res.status(404).json({ erro: 'Motorista não está no cadastro.' });
    db.run('UPDATE motoristas SET cpf=? WHERE id=?', [cpf, mot.id]);
    registrarLog('MOTORISTA — CPF (MDF-e)', `${nome}: CPF ***${cpf.slice(-4)}`, '', '', req.usuario?.nome || 'sistema');
    salvarArquivo(); res.json({ ok: true });
  }));
  app.get('/api/mdfe/ibge', rota(async (req, res) => {
    const cod = await _codigoIbge(req.query.municipio, req.query.uf);
    res.json({ ok: true, codigo_ibge: cod });
  }));

  // Monta o JSON do MDF-e no formato da Focus (carga própria, rodoviário)
  function _montarMdfe(cfg, c, b){
    const dig = s => String(s || '').replace(/\D/g, '');
    const m = {
      emitente: '2',                                   // transportador de carga própria
      uf_inicio: String(cfg.uf_emitente || '').toUpperCase(),
      uf_fim: String(b.uf_fim || cfg.uf_emitente || '').toUpperCase(),
      municipios_carregamento: [{ codigo: dig(cfg.codigo_ibge_emitente), nome: cfg.municipio_emitente || '' }],
      cnpj_emitente: dig(cfg.cnpj_emitente),
      inscricao_estadual_emitente: dig(cfg.ie_emitente),
      nome_emitente: cfg.nome_emitente || '',
      logradouro_emitente: cfg.logradouro_emitente || '', numero_emitente: cfg.numero_emitente || 'S/N',
      bairro_emitente: cfg.bairro_emitente || '', codigo_municipio_emitente: dig(cfg.codigo_ibge_emitente),
      municipio_emitente: cfg.municipio_emitente || '', uf_emitente: String(cfg.uf_emitente || '').toUpperCase(),
      modal_rodoviario: {
        placa_veiculo: String(b.veiculo.placa || '').toUpperCase().replace(/[^A-Z0-9]/g, ''),
        tara_veiculo: Math.round(+b.veiculo.tara_kg || 0),
        uf_licenciamento_veiculo: String(b.veiculo.uf_placa || cfg.uf_emitente || '').toUpperCase(),
        tipo_rodado_veiculo: String(b.veiculo.tipo_rodado || '01'),
        tipo_carroceria_veiculo: String(b.veiculo.tipo_carroceria || '02'),
        condutores: [{ nome: String(b.condutor.nome || '').slice(0, 60), cpf: dig(b.condutor.cpf) }]
      },
      municipios_descarregamento: (b.municipios || []).map(x => ({ codigo: dig(x.codigo_ibge), nome: x.municipio || '', notas_fiscais: (x.notas || []).map(ch => ({ chave_nfe: dig(ch) })) })),
      tipo_carga: c.tipo_carga || '05',
      descricao_produto: (c.descricao_produto || 'MERCADORIAS').slice(0, 120),
      quantidade_total_nfe: (b.municipios || []).reduce((t, x) => t + (x.notas || []).length, 0),
      valor_total_carga: +(+b.valor_carga || 0).toFixed(2),
      codigo_unidade_medida_peso_bruto: '01',
      peso_bruto: +(+b.peso_bruto || 0).toFixed(4)
    };
    if (cfg.nome_fantasia_emitente) m.nome_fantasia_emitente = cfg.nome_fantasia_emitente;
    if (cfg.cep_emitente) m.cep_emitente = dig(cfg.cep_emitente);
    if (cfg.telefone_emitente) m.telefone_emitente = dig(cfg.telefone_emitente);
    if (c.serie && String(c.serie).trim()) m.serie = String(c.serie).trim();
    if (b.veiculo.renavam) m.modal_rodoviario.renavam_veiculo = dig(b.veiculo.renavam);
    if (c.rntrc) m.modal_rodoviario.registro_nacional_transporte = dig(c.rntrc);
    if (c.ncm_produto) m.codigo_ncm_produto = dig(c.ncm_produto);
    if (Array.isArray(b.percursos) && b.percursos.length) m.percursos = b.percursos.map(u => ({ uf_percurso: String(u).toUpperCase() }));
    if (c.seguro_ativo) {
      const s = { responsavel_seguro: '1' };
      if (c.nome_seguradora) s.nome_seguradora = String(c.nome_seguradora).slice(0, 30);
      if (c.cnpj_seguradora) s.cnpj_seguradora = dig(c.cnpj_seguradora);
      if (c.numero_apolice) s.numero_apolice = String(c.numero_apolice).slice(0, 20);
      if (c.numero_averbacao) s.numero_averbacao = String(c.numero_averbacao).slice(0, 40);
      m.seguros_carga = [s];
    }
    const info = [c.info_complementar, b.info_complementar].filter(Boolean).join(' · ');
    if (info) m.informacao_complementar = info.slice(0, 5000);
    return m;
  }
  app.post('/api/mdfe/previa', rota((req, res) => {
    const b = req.body || {}; const cfg = _mdfeCfgEmitente(b.empresa_id || 'emp1');
    if (!cfg) return res.status(400).json({ erro: 'Emitente sem configuração de NF-e.' });
    try { res.json({ ok: true, mdfe: _montarMdfe(cfg, _mdfeConfig(), b) }); } catch(e) { res.status(400).json({ erro: e.message }); }
  }));
  app.post('/api/mdfe/emitir', rota(async (req, res) => {
    const b = req.body || {};
    const empresaId = String(b.empresa_id || 'emp1');
    const cfg = _mdfeCfgEmitente(empresaId);
    if (!cfg) return res.status(400).json({ erro: 'Emitente sem configuração de NF-e (Configuração NF-e).' });
    if (!b.veiculo || !b.veiculo.placa) return res.status(400).json({ erro: 'Informe o veículo (placa).' });
    if (!(+b.veiculo.tara_kg > 0)) return res.status(400).json({ erro: 'Informe a tara do veículo (kg).' });
    if (!b.condutor || String(b.condutor.cpf || '').replace(/\D/g, '').length !== 11) return res.status(400).json({ erro: 'Informe o condutor com CPF (11 dígitos).' });
    const muns = Array.isArray(b.municipios) ? b.municipios : [];
    const chaves = muns.flatMap(x => x.notas || []).map(k => String(k).replace(/\D/g, ''));
    if (!chaves.length) return res.status(400).json({ erro: 'Nenhuma NF-e para manifestar.' });
    if (chaves.some(k => k.length !== 44)) return res.status(400).json({ erro: 'Há chave de NF-e inválida (precisa ter 44 dígitos).' });
    const semIbge = muns.filter(x => !/^\d{7}$/.test(String(x.codigo_ibge || '').replace(/\D/g, '')));
    if (semIbge.length) return res.status(400).json({ erro: 'Cidade sem código IBGE: ' + semIbge.map(x => x.municipio).join(', ') });
    if (!/^\d{7}$/.test(String(cfg.codigo_ibge_emitente || '').replace(/\D/g, ''))) return res.status(400).json({ erro: 'Falta o código IBGE do município do emitente na Configuração NF-e.' });
    const emAberto = queryAll("SELECT ref, numero, notas_json FROM mdfe_emitidos WHERE status IN ('autorizado','processando')").find(r => { try { return (JSON.parse(r.notas_json || '[]') || []).some(n => chaves.includes(String(n.chave))); } catch(e) { return false; } });
    if (emAberto && !b.forcar) return res.status(409).json({ erro: `Uma dessas notas já está no manifesto ${emAberto.numero || emAberto.ref} (em aberto). Encerre ou cancele aquele antes.`, motivo: 'duplicado' });
    const f = _mdfeFocus(cfg);
    if (!f.token) return res.status(400).json({ erro: `Token de ${f.ambiente} não configurado para o emitente.` });
    const c = _mdfeConfig();
    let mdfe; try { mdfe = _montarMdfe(cfg, c, b); } catch(e) { return res.status(400).json({ erro: e.message }); }
    const ref = 'MDF' + Date.now().toString(36).toUpperCase() + Math.floor(Math.random() * 900 + 100);
    let retorno = {}, httpStatus = 0;
    try {
      const resp = await fetch(`${f.base}/v2/mdfe?ref=${encodeURIComponent(ref)}`, { method: 'POST', headers: { 'Authorization': f.auth, 'Content-Type': 'application/json' }, body: JSON.stringify(mdfe) });
      httpStatus = resp.status; retorno = await resp.json().catch(() => ({}));
    } catch(e) { return res.status(502).json({ erro: 'Falha ao contatar a Focus NFe: ' + e.message }); }
    const ok = httpStatus >= 200 && httpStatus < 300;
    const status = ok ? (retorno.status === 'autorizado' ? 'autorizado' : 'processando') : 'erro';
    const notas = muns.flatMap(x => (x.notas || []).map(ch => ({ chave: String(ch).replace(/\D/g, ''), municipio: x.municipio, uf: x.uf })));
    db.run(`INSERT INTO mdfe_emitidos (ref, empresa_id, ambiente, status, status_sefaz, mensagem_sefaz, chave, numero, serie, protocolo, caminho_xml, caminho_damdfe,
              motorista, cpf_motorista, caminhao, data_prevista, uf_inicio, uf_fim, municipios_json, notas_json, pedidos_json, qtd_nfe, peso_bruto, valor_carga, requisicao_json, retorno_json, unidade, emitido_por)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
      [ref, empresaId, f.ambiente, status, retorno.status_sefaz || '', retorno.mensagem_sefaz || retorno.mensagem || '', retorno.chave || '', retorno.numero || '', retorno.serie || '', retorno.protocolo || '',
       _mdfeAbs(f.base, retorno.caminho_xml), _mdfeAbs(f.base, retorno.caminho_damdfe),
       b.condutor.nome || '', String(b.condutor.cpf).replace(/\D/g, ''), b.veiculo.placa || '', b.data_prevista || '', mdfe.uf_inicio, mdfe.uf_fim,
       JSON.stringify(muns.map(x => ({ municipio: x.municipio, uf: x.uf, codigo_ibge: x.codigo_ibge, notas: (x.notas || []).length }))), JSON.stringify(notas), JSON.stringify(b.pedidos || []),
       chaves.length, +b.peso_bruto || 0, +b.valor_carga || 0, JSON.stringify(mdfe), JSON.stringify(retorno), _unidadeDeQuemLanca(req), req.usuario?.nome || 'sistema']);
    registrarLog(ok ? 'MDF-e ENVIADO' : 'MDF-e RECUSADO', `${ref} — ${b.condutor.nome || ''} · ${b.veiculo.placa || ''} · ${chaves.length} NF-e · ${(muns || []).map(x => x.municipio).join(', ')}`,
      ok ? '' : (retorno.mensagem || retorno.erro || JSON.stringify(retorno).slice(0, 300)), `R$ ${(+b.valor_carga || 0).toFixed(2)} · ${(+b.peso_bruto || 0).toFixed(0)} kg · ${f.ambiente}`, req.usuario?.nome || 'sistema');
    salvarArquivo();
    if (!ok) return res.status(400).json({ erro: retorno.mensagem || retorno.erro || ('Focus respondeu HTTP ' + httpStatus), codigo: retorno.codigo || '', ref, retorno, requisicao: mdfe });
    res.json({ ok: true, ref, status, ambiente: f.ambiente, retorno });
  }));
  async function _mdfeConsultar(reg){
    const cfg = _mdfeCfgEmitente(reg.empresa_id); if (!cfg) return null;
    const f = _mdfeFocus(Object.assign({}, cfg, { ambiente: reg.ambiente || cfg.ambiente }));
    const resp = await fetch(`${f.base}/v2/mdfe/${encodeURIComponent(reg.ref)}`, { headers: { 'Authorization': f.auth } });
    const r = await resp.json().catch(() => ({}));
    const st = String(r.status || '');
    const status = st === 'autorizado' ? 'autorizado' : st === 'encerrado' ? 'encerrado' : st === 'cancelado' ? 'cancelado' : st === 'processando_autorizacao' ? 'processando' : (st ? 'erro' : reg.status);
    db.run(`UPDATE mdfe_emitidos SET status=?, status_sefaz=?, mensagem_sefaz=?, chave=COALESCE(NULLIF(?,''),chave), numero=COALESCE(NULLIF(?,''),numero), serie=COALESCE(NULLIF(?,''),serie),
              protocolo=COALESCE(NULLIF(?,''),protocolo), caminho_xml=COALESCE(NULLIF(?,''),caminho_xml), caminho_damdfe=COALESCE(NULLIF(?,''),caminho_damdfe),
              caminho_xml_encerramento=COALESCE(NULLIF(?,''),caminho_xml_encerramento), caminho_xml_cancelamento=COALESCE(NULLIF(?,''),caminho_xml_cancelamento),
              retorno_json=?, atualizado_em=datetime('now','localtime') WHERE id=?`,
      [status, r.status_sefaz || '', r.mensagem_sefaz || r.mensagem || '', r.chave || '', r.numero || '', r.serie || '', r.protocolo || '',
       _mdfeAbs(f.base, r.caminho_xml), _mdfeAbs(f.base, r.caminho_damdfe), _mdfeAbs(f.base, r.caminho_xml_encerramento), _mdfeAbs(f.base, r.caminho_xml_cancelamento), JSON.stringify(r), reg.id]);
    return status;
  }
  app.get('/api/mdfe/lista', rota(async (req, res) => {
    const _fu = _filtroUnidade(req, 'unidade');
    if (req.query.consultar === '1') {
      const pend = queryAll(`SELECT * FROM mdfe_emitidos WHERE status='processando'${_fu.sql}`, _fu.params);
      for (const p of pend) { try { await _mdfeConsultar(p); } catch(e) {} }
      if (pend.length) salvarArquivo();
    }
    const rows = queryAll(`SELECT id, ref, empresa_id, ambiente, status, status_sefaz, mensagem_sefaz, chave, numero, serie, protocolo, caminho_xml, caminho_damdfe, caminho_xml_encerramento, caminho_xml_cancelamento,
                                  motorista, caminhao, data_prevista, uf_inicio, uf_fim, municipios_json, notas_json, pedidos_json, qtd_nfe, peso_bruto, valor_carga, emitido_por, encerrado_em, cancelado_em, criado_em, atualizado_em
                             FROM mdfe_emitidos WHERE 1=1${_fu.sql} ORDER BY id DESC LIMIT 300`, _fu.params);
    res.json(rows.map(r => { let m = [], p = []; try { m = JSON.parse(r.municipios_json || '[]'); } catch(e) {} try { p = JSON.parse(r.pedidos_json || '[]'); } catch(e) {} return Object.assign({}, r, { municipios: m, pedidos: p, municipios_json: undefined, notas_json: undefined, pedidos_json: undefined }); }));
  }));
  app.get('/api/mdfe/:ref/consultar', rota(async (req, res) => {
    const reg = queryOne('SELECT * FROM mdfe_emitidos WHERE ref=?', [req.params.ref]);
    if (!reg) return res.status(404).json({ erro: 'Manifesto não encontrado.' });
    try { const st = await _mdfeConsultar(reg); salvarArquivo(); const novo = queryOne('SELECT status, status_sefaz, mensagem_sefaz, numero, chave, caminho_damdfe FROM mdfe_emitidos WHERE id=?', [reg.id]); res.json({ ok: true, status: st, ...novo }); }
    catch(e) { res.status(502).json({ erro: 'Falha ao consultar a Focus: ' + e.message }); }
  }));
  app.get('/api/mdfe/:ref/json', rota((req, res) => {
    const reg = queryOne('SELECT requisicao_json, retorno_json FROM mdfe_emitidos WHERE ref=?', [req.params.ref]);
    if (!reg) return res.status(404).json({ erro: 'Manifesto não encontrado.' });
    let q = {}, r = {}; try { q = JSON.parse(reg.requisicao_json || '{}'); } catch(e) {} try { r = JSON.parse(reg.retorno_json || '{}'); } catch(e) {}
    res.json({ ok: true, requisicao: q, retorno: r });
  }));
  app.post('/api/mdfe/:ref/encerrar', rota(async (req, res) => {
    const reg = queryOne('SELECT * FROM mdfe_emitidos WHERE ref=?', [req.params.ref]);
    if (!reg) return res.status(404).json({ erro: 'Manifesto não encontrado.' });
    if (reg.status !== 'autorizado') return res.status(400).json({ erro: 'Só manifesto AUTORIZADO pode ser encerrado (este está "' + reg.status + '").' });
    const cfg = _mdfeCfgEmitente(reg.empresa_id); if (!cfg) return res.status(400).json({ erro: 'Emitente sem configuração.' });
    const f = _mdfeFocus(Object.assign({}, cfg, { ambiente: reg.ambiente || cfg.ambiente }));
    const b = req.body || {};
    const uf = String(b.sigla_uf || reg.uf_fim || cfg.uf_emitente || '').toUpperCase();
    let mun = String(b.nome_municipio || '').trim();
    if (!mun) { try { const ms = JSON.parse(reg.municipios_json || '[]'); mun = (ms[ms.length - 1] || {}).municipio || ''; } catch(e) {} }
    if (!mun) mun = cfg.municipio_emitente || '';
    const data = String(b.data || _hojeBR()).slice(0, 10);
    let r = {}, hs = 0;
    try { const resp = await fetch(`${f.base}/v2/mdfe/${encodeURIComponent(reg.ref)}/encerrar`, { method: 'POST', headers: { 'Authorization': f.auth, 'Content-Type': 'application/json' }, body: JSON.stringify({ data, sigla_uf: uf, nome_municipio: mun }) }); hs = resp.status; r = await resp.json().catch(() => ({})); }
    catch(e) { return res.status(502).json({ erro: 'Falha ao contatar a Focus: ' + e.message }); }
    const ok = (hs >= 200 && hs < 300) && (r.status === 'encerrado' || r.status === 'incluido' || /135|encerr/i.test(String(r.status_sefaz || '') + String(r.mensagem_sefaz || '')));
    if (ok || /ja_encerrado|já encerrado/i.test(JSON.stringify(r))) {
      db.run(`UPDATE mdfe_emitidos SET status='encerrado', status_sefaz=?, mensagem_sefaz=?, caminho_xml_encerramento=?, encerrado_em=datetime('now','localtime'), atualizado_em=datetime('now','localtime') WHERE id=?`,
        [r.status_sefaz || '', r.mensagem_sefaz || 'Encerrado', _mdfeAbs(f.base, r.caminho_xml), reg.id]);
      registrarLog('MDF-e ENCERRADO', `${reg.numero || reg.ref} — ${reg.motorista} · ${reg.caminhao} — em ${mun}/${uf} (${data})`, '', '', req.usuario?.nome || 'sistema');
      salvarArquivo(); return res.json({ ok: true, status: 'encerrado', mensagem: r.mensagem_sefaz || '' });
    }
    res.status(400).json({ erro: r.mensagem_sefaz || r.mensagem || r.erro || ('Focus respondeu HTTP ' + hs), retorno: r });
  }));
  app.post('/api/mdfe/:ref/cancelar', rota(async (req, res) => {
    const reg = queryOne('SELECT * FROM mdfe_emitidos WHERE ref=?', [req.params.ref]);
    if (!reg) return res.status(404).json({ erro: 'Manifesto não encontrado.' });
    const just = String((req.body || {}).justificativa || '').trim();
    if (just.length < 15) return res.status(400).json({ erro: 'A justificativa precisa ter pelo menos 15 caracteres.' });
    if (reg.status === 'erro' || reg.status === 'processando') {
      // nunca chegou a ser autorizado: só tira da lista
      db.run("UPDATE mdfe_emitidos SET status='descartado', justificativa=?, cancelado_em=datetime('now','localtime') WHERE id=?", [just, reg.id]);
      registrarLog('MDF-e DESCARTADO', `${reg.ref} — ${reg.motorista} · ${reg.caminhao}`, just, '', req.usuario?.nome || 'sistema');
      salvarArquivo(); return res.json({ ok: true, status: 'descartado' });
    }
    if (reg.status !== 'autorizado') return res.status(400).json({ erro: 'Só manifesto AUTORIZADO pode ser cancelado (este está "' + reg.status + '"). Manifesto encerrado não se cancela.' });
    const cfg = _mdfeCfgEmitente(reg.empresa_id); if (!cfg) return res.status(400).json({ erro: 'Emitente sem configuração.' });
    const f = _mdfeFocus(Object.assign({}, cfg, { ambiente: reg.ambiente || cfg.ambiente }));
    let r = {}, hs = 0;
    try { const resp = await fetch(`${f.base}/v2/mdfe/${encodeURIComponent(reg.ref)}`, { method: 'DELETE', headers: { 'Authorization': f.auth, 'Content-Type': 'application/json' }, body: JSON.stringify({ justificativa: just }) }); hs = resp.status; r = await resp.json().catch(() => ({})); }
    catch(e) { return res.status(502).json({ erro: 'Falha ao contatar a Focus: ' + e.message }); }
    if ((hs >= 200 && hs < 300) && r.status === 'cancelado') {
      db.run(`UPDATE mdfe_emitidos SET status='cancelado', status_sefaz=?, mensagem_sefaz=?, caminho_xml_cancelamento=?, justificativa=?, cancelado_em=datetime('now','localtime'), atualizado_em=datetime('now','localtime') WHERE id=?`,
        [r.status_sefaz || '', r.mensagem_sefaz || 'Cancelado', _mdfeAbs(f.base, r.caminho_xml_cancelamento), just, reg.id]);
      registrarLog('MDF-e CANCELADO', `${reg.numero || reg.ref} — ${reg.motorista} · ${reg.caminhao}`, just, '', req.usuario?.nome || 'sistema');
      salvarArquivo(); return res.json({ ok: true, status: 'cancelado' });
    }
    res.status(400).json({ erro: r.mensagem_sefaz || r.mensagem || r.erro || ('Focus respondeu HTTP ' + hs), retorno: r });
  }));

  // ═══ RASTREAMENTO DA FROTA (v.168) ═══════════════════════════════════════
  // O aparelho no caminhao NAO fala HTTP: ele abre um TCP e manda pacote binario no
  // protocolo do fabricante. Quem entende isso e o servidor Traccar (open source, fala
  // mais de 90 protocolos). O MASSATOP conversa com o Traccar por HTTP, e o token fica
  // AQUI no servidor - nunca vai para o navegador.
  function _rastCfg() {
    const g = k => { const r = queryOne('SELECT valor FROM rastreamento_config WHERE chave=?', [k]); return r ? String(r.valor || '') : ''; };
    return { url: g('url').replace(/\/+$/, ''), token: g('token'), usuario: g('usuario'), senha: g('senha') };
  }
  function _rastAuth(cfg) {
    if (cfg.token) return { Authorization: 'Bearer ' + cfg.token };
    if (cfg.usuario) return { Authorization: 'Basic ' + Buffer.from(cfg.usuario + ':' + cfg.senha).toString('base64') };
    return {};
  }
  async function _rastGet(caminho) {
    const cfg = _rastCfg();
    if (!cfg.url) { const e = new Error('Servidor de rastreamento não configurado.'); e.semConfig = 1; throw e; }
    const ctrl = new AbortController();
    const tid = setTimeout(() => ctrl.abort(), 15000);
    try {
      const r = await fetch(cfg.url + caminho, { headers: { Accept: 'application/json', ..._rastAuth(cfg) }, signal: ctrl.signal });
      const txt = await r.text();
      if (!r.ok) throw new Error(`O servidor de rastreamento respondeu ${r.status}. ${txt.slice(0, 180)}`);
      try { return JSON.parse(txt); } catch(e) { throw new Error('Resposta do servidor de rastreamento não é JSON.'); }
    } catch(e) {
      if (e.name === 'AbortError') throw new Error('O servidor de rastreamento não respondeu (15 s).');
      throw e;
    } finally { clearTimeout(tid); }
  }

  app.get('/api/rastreamento/config', rota((req, res) => {
    const c = _rastCfg();
    // a senha/token nunca voltam para a tela - so o aviso de que existem
    res.json({ ok: true, url: c.url, usuario: c.usuario, tem_token: !!c.token, tem_senha: !!c.senha,
               configurado: !!(c.url && (c.token || c.usuario)) });
  }));

  app.post('/api/rastreamento/config', rota((req, res) => {
    const set = (k, v) => { db.run('DELETE FROM rastreamento_config WHERE chave=?', [k]);
                            db.run('INSERT INTO rastreamento_config (chave,valor) VALUES (?,?)', [k, String(v || '')]); };
    if (req.body?.url !== undefined) set('url', String(req.body.url || '').trim().replace(/\/+$/, ''));
    if (req.body?.token !== undefined) set('token', String(req.body.token || '').trim());
    if (req.body?.usuario !== undefined) set('usuario', String(req.body.usuario || '').trim());
    if (req.body?.senha !== undefined) set('senha', String(req.body.senha || ''));
    registrarLog('CONFIGURACAO DO RASTREAMENTO', _rastCfg().url, '', '', req.usuario?.nome || 'sistema');
    salvarArquivo();
    res.json({ ok: true });
  }));

  // Testa a conexao e ja devolve os aparelhos que o servidor conhece
  app.get('/api/rastreamento/testar', rota(async (req, res) => {
    try {
      const devices = await _rastGet('/api/devices');
      res.json({ ok: true, quantidade: Array.isArray(devices) ? devices.length : 0,
                 aparelhos: (devices || []).map(d => ({ id: d.id, nome: d.name, identificador: d.uniqueId, status: d.status, ultima: d.lastUpdate })) });
    } catch(e) { res.status(e.semConfig ? 400 : 502).json({ erro: e.message }); }
  }));

  // Vinculo caminhao <-> aparelho
  app.get('/api/rastreamento/vinculos', rota((req, res) => {
    const cams = queryAll('SELECT placa, modelo FROM caminhoes ORDER BY placa');
    const vin = queryAll('SELECT * FROM rastreadores');
    res.json(cams.map(c => {
      const v = vin.find(x => String(x.placa).toUpperCase() === String(c.placa).toUpperCase()) || {};
      return { placa: c.placa, modelo: c.modelo || '', device_id: v.device_id || '', identificador: v.identificador || '',
               tanque_litros: +v.tanque_litros || 0, ativo: v.id ? !!v.ativo : true };
    }));
  }));

  app.post('/api/rastreamento/vincular', rota((req, res) => {
    const placa = String(req.body?.placa || '').trim();
    if (!placa) return res.status(400).json({ erro: 'Informe a placa.' });
    const device = String(req.body?.device_id || '').trim();
    const ident = String(req.body?.identificador || '').trim();
    const tanque = parseFloat(String(req.body?.tanque_litros).replace(',', '.')) || 0;
    db.run('DELETE FROM rastreadores WHERE placa=? COLLATE NOCASE', [placa]);
    if (device || ident) {
      db.run('INSERT INTO rastreadores (placa,device_id,identificador,tanque_litros,ativo) VALUES (?,?,?,?,1)',
        [placa, device, ident, tanque]);
    }
    registrarLog('VINCULO DE RASTREADOR', `${placa} -> ${device || ident || '(removido)'}`, '', '', req.usuario?.nome || 'sistema');
    salvarArquivo();
    res.json({ ok: true });
  }));

  // Onde está cada caminhão AGORA
  app.get('/api/rastreamento/frota', rota(async (req, res) => {
    let devices, posicoes;
    try {
      devices = await _rastGet('/api/devices');
      posicoes = await _rastGet('/api/positions');
    } catch(e) { return res.status(e.semConfig ? 400 : 502).json({ erro: e.message }); }
    const porId = new Map((posicoes || []).map(p => [p.deviceId, p]));
    const vin = queryAll('SELECT * FROM rastreadores WHERE ativo=1');
    const assoc = queryAll('SELECT motorista, caminhao FROM associacoes');
    const hoje = _isoHoje();

    const out = (devices || []).map(d => {
      const p = porId.get(d.id) || null;
      const v = vin.find(x => String(x.device_id) === String(d.id) || (x.identificador && x.identificador === d.uniqueId));
      const placa = v ? v.placa : '';
      const at = (p && p.attributes) || {};
      // litros: o Traccar entrega o nivel em 'fuel' (ou 'fuelLevel', em %) conforme o aparelho
      let litros = null, pct = null;
      if (at.fuel != null && isFinite(+at.fuel)) litros = +at.fuel;
      if (at.fuelLevel != null && isFinite(+at.fuelLevel)) pct = +at.fuelLevel;
      if (litros == null && pct != null && v && +v.tanque_litros > 0) litros = +(pct / 100 * +v.tanque_litros).toFixed(1);
      if (pct == null && litros != null && v && +v.tanque_litros > 0) pct = +(litros / +v.tanque_litros * 100).toFixed(1);

      const mot = placa ? (assoc.find(a => String(a.caminhao).toUpperCase() === String(placa).toUpperCase()) || {}).motorista || '' : '';
      const emRota = placa
        ? queryAll("SELECT pedido_venda FROM pedidos WHERE situacao='CARREGANDO' AND caminhao=? COLLATE NOCASE", [placa]).length
        : 0;
      return {
        device_id: d.id, identificador: d.uniqueId, nome_aparelho: d.name,
        placa, motorista: mot, pedidos_em_rota: emRota,
        online: String(d.status || '') === 'online' ? 1 : 0, status: d.status || '',
        ultima_comunicacao: d.lastUpdate || (p && p.deviceTime) || '',
        lat: p ? p.latitude : null, lon: p ? p.longitude : null,
        velocidade: p ? Math.round((+p.speed || 0) * 1.852) : null,   // nós -> km/h
        curso: p ? p.course : null,
        ignicao: at.ignition == null ? null : (at.ignition ? 1 : 0),
        odometro: at.totalDistance != null ? +(at.totalDistance / 1000).toFixed(1) : null,
        combustivel_litros: litros, combustivel_pct: pct,
        tanque_litros: v ? +v.tanque_litros || 0 : 0,
        endereco: p ? (p.address || '') : '', data_posicao: p ? p.fixTime : ''
      };
    });
    // caminhao com carga primeiro, depois online, depois o resto (mesma regra da sugestão)
    out.sort((a, b) => (b.pedidos_em_rota - a.pedidos_em_rota) || (b.online - a.online) || String(a.placa).localeCompare(String(b.placa)));
    res.json({ ok: true, hoje, quantidade: out.length,
               sem_vinculo: out.filter(x => !x.placa).length, frota: out });
  }));

  // Caminho percorrido por um caminhão num período
  app.get('/api/rastreamento/percurso/:placa', rota(async (req, res) => {
    const placa = String(req.params.placa || '').trim();
    const v = queryOne('SELECT * FROM rastreadores WHERE placa=? COLLATE NOCASE AND ativo=1', [placa]);
    if (!v || !v.device_id) return res.status(404).json({ erro: 'Este caminhão ainda não tem rastreador vinculado.' });
    const de = String(req.query.de || '') || (_isoHoje() + 'T00:00:00Z');
    const ate = String(req.query.ate || '') || (_isoHoje() + 'T23:59:59Z');
    const q = `?deviceId=${encodeURIComponent(v.device_id)}&from=${encodeURIComponent(de)}&to=${encodeURIComponent(ate)}`;
    let pos = [], viagens = [], paradas = [];
    try {
      pos = await _rastGet('/api/positions' + q);
      viagens = await _rastGet('/api/reports/trips' + q).catch(() => []);
      paradas = await _rastGet('/api/reports/stops' + q).catch(() => []);
    } catch(e) { return res.status(e.semConfig ? 400 : 502).json({ erro: e.message }); }

    const pontos = (pos || []).map(p => ({
      lat: p.latitude, lon: p.longitude, hora: p.fixTime,
      velocidade: Math.round((+p.speed || 0) * 1.852),
      combustivel: (p.attributes && p.attributes.fuel != null) ? +p.attributes.fuel : null,
      ignicao: (p.attributes && p.attributes.ignition != null) ? (p.attributes.ignition ? 1 : 0) : null
    }));
    // km rodado pelo odômetro do aparelho, com reserva no cálculo por coordenada
    let km = 0;
    const _kmEntre = (a, b) => { const R = 6371, rd = x => x * Math.PI / 180;
      const dLa = rd(b.lat - a.lat), dLo = rd(b.lon - a.lon);
      const h = Math.sin(dLa/2)**2 + Math.cos(rd(a.lat)) * Math.cos(rd(b.lat)) * Math.sin(dLo/2)**2;
      return 2 * R * Math.asin(Math.sqrt(h)); };
    for (let i = 1; i < pontos.length; i++) km += _kmEntre(pontos[i-1], pontos[i]);

    // combustível: quanto caiu (consumo) e quanto subiu (abastecimento)
    let consumo = 0, abastecido = 0;
    const comFuel = pontos.filter(p => p.combustivel != null);
    for (let i = 1; i < comFuel.length; i++) {
      const d = comFuel[i].combustivel - comFuel[i-1].combustivel;
      if (d < -0.5) consumo += -d;
      else if (d > 5) abastecido += d;    // subida grande = abastecimento
    }
    // O km do relatorio de viagens vem do odometro do aparelho e e mais confiavel que a
    // soma das coordenadas (que perde curva entre um ponto e outro). Usa ele quando existe.
    const kmViagens = +(viagens || []).reduce((a2, t) => a2 + (+t.distance || 0), 0) / 1000;
    const kmFinal = kmViagens > 0 ? +kmViagens.toFixed(1) : +km.toFixed(1);

    res.json({
      ok: true, placa, de, ate, pontos, quantidade: pontos.length,
      km_percorrido: kmFinal,
      km_por_coordenada: +km.toFixed(1), km_por_viagens: +kmViagens.toFixed(1),
      origem_km: kmViagens > 0 ? 'odômetro do rastreador' : 'soma das posições',
      combustivel: comFuel.length
        ? { inicial: comFuel[0].combustivel, final: comFuel[comFuel.length-1].combustivel,
            consumido: +consumo.toFixed(1), abastecido: +abastecido.toFixed(1),
            media_km_l: consumo > 0 ? +(kmFinal / consumo).toFixed(2) : null }
        : null,
      viagens: (viagens || []).map(t => ({ inicio: t.startTime, fim: t.endTime, km: +((t.distance || 0) / 1000).toFixed(1),
                                           partida: t.startAddress || '', chegada: t.endAddress || '',
                                           duracao_min: Math.round((t.duration || 0) / 60000), vel_media: Math.round((t.averageSpeed || 0) * 1.852) })),
      paradas: (paradas || []).map(t => ({ inicio: t.startTime, fim: t.endTime, endereco: t.address || '',
                                           duracao_min: Math.round((t.duration || 0) / 60000) }))
    });
  }));

  // Planejado x realizado de um carregamento
  app.get('/api/rastreamento/conferencia/:placa', rota(async (req, res) => {
    const placa = String(req.params.placa || '').trim();
    const linhas = queryAll("SELECT * FROM pedidos WHERE situacao='CARREGANDO' AND caminhao=? COLLATE NOCASE ORDER BY ordem_rota, id", [placa]);
    const paradasPlan = [];
    linhas.forEach(l => {
      const cli = String(l.razao_social || '').trim();
      if (!paradasPlan.some(x => x.cliente === cli)) paradasPlan.push({ cliente: cli, cidade: l.cidade || '', ordem: +l.ordem_rota || 0 });
    });
    res.json({ ok: true, placa, paradas_planejadas: paradasPlan, pedidos: linhas.length,
               motorista: (linhas[0] || {}).motorista || '', data_prevista: (linhas[0] || {}).data_prevista || '' });
  }));

  // ─── PONTOS DE ENTREGA (v.159) ──────────────────────────────────────────────\n  // Endereço da LOJA de cada cliente do roteiro. Serve para (1) marcar o ponto exato no
  // mapa em vez do centro da cidade e (2) montar o link do Google Maps que o motorista
  // abre no celular. A coordenada, quando achada, fica guardada no cadastro do cliente.
  app.post('/api/logistica/pontos-entrega', rota((req, res) => {
    const lista = Array.isArray(req.body?.clientes) ? req.body.clientes : [];
    const out = lista.map(item => {
      const nome = typeof item === 'string' ? item : String(item?.cliente || '');
      const cidade = typeof item === 'string' ? '' : String(item?.cidade || '');
      const c = dadosClienteCobranca(nome, { cidade }) || {};
      const rua = `${c.logradouro || ''}${c.numero ? (', ' + c.numero) : ''}`.trim();
      const cep = String(c.cep || '').replace(/\D/g, '');
      const partes = [rua, c.bairro || '', `${c.municipio || ''}${c.uf ? (' - ' + c.uf) : ''}`.trim(), cep]
        .map(x => String(x).trim()).filter(Boolean);
      const lat = (c.geo_lat != null && isFinite(+c.geo_lat)) ? +c.geo_lat : null;
      const lon = (c.geo_lon != null && isFinite(+c.geo_lon)) ? +c.geo_lon : null;
      return {
        cliente: nome,
        endereco: rua, bairro: c.bairro || '', cep,
        municipio: c.municipio || '', uf: c.uf || '',
        endereco_completo: partes.join(', '),
        tem_endereco: !!(rua && c.municipio),
        lat, lon,
        ambiguo: c._ambiguo || null
      };
    });
    res.json(out);
  }));

  // Guarda a coordenada da loja para não perguntar ao mapa toda vez
  app.post('/api/logistica/geo-cliente', rota((req, res) => {
    const nome = String(req.body?.cliente || '').trim();
    const lat = +req.body?.lat, lon = +req.body?.lon;
    if (!nome || !isFinite(lat) || !isFinite(lon)) return res.status(400).json({ erro: 'Dados incompletos.' });
    const c = dadosClienteCobranca(nome, { cidade: String(req.body?.cidade || '') }) || {};
    if (!c.id) return res.json({ ok: false, motivo: 'cliente não encontrado no cadastro fiscal' });
    db.run('UPDATE clientes_fiscais SET geo_lat=?, geo_lon=? WHERE id=?', [lat, lon, c.id]);
    salvarArquivo();
    res.json({ ok: true });
  }));

  // ROTA DE UM CARREGAMENTO (v.161) - so existe depois que o pedido vai para CARREGANDO.
  // Monta as paradas na ordem planejada, com o endereco da loja, e devolve o link do
  // Google Maps e o texto pronto para mandar ao motorista.
  const _GMAPS_MAX_WP = 9;
  app.get('/api/logistica/rota-link', rota((req, res) => {
    const motorista = String(req.query.motorista || '').trim();
    const caminhao = String(req.query.caminhao || '').trim();
    const dataPrev = String(req.query.data || '').trim();
    if (!motorista) return res.status(400).json({ erro: 'Informe o motorista.' });

    let sql = "SELECT * FROM pedidos WHERE situacao='CARREGANDO' AND motorista=? COLLATE NOCASE";
    const par = [motorista];
    if (caminhao && caminhao !== '-') { sql += ' AND caminhao=? COLLATE NOCASE'; par.push(caminhao); }
    if (dataPrev && dataPrev !== '-') { sql += ' AND data_prevista=?'; par.push(dataPrev); }
    const linhas = queryAll(sql + ' ORDER BY ordem_rota, id', par);
    if (!linhas.length) return res.status(404).json({ erro: 'Nenhum pedido em carregamento para este motorista.' });

    // Peso por unidade vem do cadastro de produtos (saco/caixa de 20 kg por padrao)
    const _normProd = x => String(x || '').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^A-Z0-9]+/g, ' ').trim();
    const _pesoMap = new Map();
    try {
      queryAll('SELECT descricao, peso_kg FROM produtos_fiscais').forEach(pr => {
        const n = _normProd(pr.descricao);
        if (n) _pesoMap.set(n, +pr.peso_kg > 0 ? +pr.peso_kg : 20);
      });
    } catch(e) {}
    const _pesoUnit = nome => {
      const n = _normProd(nome);
      if (!n) return 20;
      if (_pesoMap.has(n)) return _pesoMap.get(n);
      for (const [k, v] of _pesoMap) { if (k.length >= 4 && (k.startsWith(n) || n.startsWith(k))) return v; }
      return 20;
    };

    // Uma parada por CLIENTE, na ordem planejada
    const ordem = [], porParada = new Map();
    linhas.forEach(l => {
      const cli = String(l.razao_social || '').trim() || String(l.cidade || '').trim() || '?';
      const cid = String(l.cidade || '').trim();
      const k = cli + '||' + cid;
      if (!porParada.has(k)) { porParada.set(k, { cliente: cli, cidade: cid, pedidos: [], peso: 0, valor: 0, ordem: +l.ordem_rota || 9999 }); ordem.push(k); }
      const pa = porParada.get(k);
      if (!pa.pedidos.includes(String(l.pedido_venda))) pa.pedidos.push(String(l.pedido_venda));
      pa.peso += (+l.quantidade || 0) * _pesoUnit(l.produto);
      pa.valor += +l.valor_total || 0;
      pa.ordem = Math.min(pa.ordem, +l.ordem_rota || 9999);
    });

    let semEndereco = 0;
    const paradas = ordem.map(k => {
      const pa = porParada.get(k);
      const c = dadosClienteCobranca(pa.cliente, { cidade: pa.cidade }) || {};
      const rua = `${c.logradouro || ''}${c.numero ? (', ' + c.numero) : ''}`.trim();
      const cep = String(c.cep || '').replace(/\D/g, '');
      const completo = [rua, c.bairro || '', `${c.municipio || ''}${c.uf ? (' - ' + c.uf) : ''}`.trim(), cep]
        .map(x => String(x).trim()).filter(Boolean).join(', ');
      const lat = (c.geo_lat != null && isFinite(+c.geo_lat)) ? +c.geo_lat : null;
      const lon = (c.geo_lon != null && isFinite(+c.geo_lon)) ? +c.geo_lon : null;
      if (!completo) semEndereco++;
      return { cliente: pa.cliente, cidade: pa.cidade, pedidos: pa.pedidos,
               peso: +pa.peso.toFixed(0), valor: +pa.valor.toFixed(2),
               endereco: completo, lat, lon, tem_endereco: !!completo };
    });

    // Link do Google Maps: coordenada quando existe, senao o endereco por extenso
    const FAB = 'Usina MassaTop, Simoes Filho - BA';
    const ponto = p => encodeURIComponent((p.lat != null && p.lon != null)
      ? (p.lat.toFixed(6) + ',' + p.lon.toFixed(6))
      : (p.endereco || (p.cliente + ', ' + p.cidade)));
    const destino = paradas[paradas.length - 1];
    const meio = paradas.slice(0, -1);
    const usadas = meio.slice(0, _GMAPS_MAX_WP);
    const fora = meio.slice(_GMAPS_MAX_WP);
    let url = 'https://www.google.com/maps/dir/?api=1&travelmode=driving&origin='
            + encodeURIComponent(FAB) + '&destination=' + ponto(destino);
    if (usadas.length) url += '&waypoints=' + usadas.map(ponto).join('%7C');

    const pesoTot = paradas.reduce((s, p) => s + p.peso, 0);
    const T = [];
    T.push('*ROTEIRO DE ENTREGA* - ' + (caminhao || '') );
    T.push((dataPrev && dataPrev !== '-' ? (dataPrev + ' - ') : '') + paradas.length + ' parada(s) - ' + pesoTot.toLocaleString('pt-BR') + ' kg');
    T.push('Motorista: ' + motorista);
    T.push('');
    paradas.forEach((p, i) => {
      T.push((i + 1) + ') ' + p.cliente + ' - ' + p.cidade);
      T.push(p.endereco ? ('   ' + p.endereco) : '   (endereco nao cadastrado - confirmar no escritorio)');
      T.push('   Pedido(s): ' + p.pedidos.join(', '));
    });
    T.push('');
    T.push('Abrir a rota no Google Maps:');
    T.push(url);
    if (fora.length) T.push('(o link leva as ' + _GMAPS_MAX_WP + ' primeiras paradas - as demais estao na lista acima)');

    const mot = queryOne('SELECT telefone FROM motoristas WHERE nome=? COLLATE NOCASE', [motorista]);
    res.json({
      ok: true, motorista, caminhao, data_prevista: dataPrev,
      telefone: String(mot?.telefone || '').replace(/\D/g, ''),
      paradas, quantidade: paradas.length, peso_total: pesoTot,
      sem_endereco: semEndereco,
      fora_do_link: fora.map(p => p.cliente + ' (' + p.cidade + ')'),
      url_maps: url, texto: T.join('\n')
    });
  }));

  // ─── MOTORISTAS ─────────────────────────────────────────────────────────────
  app.get('/api/motoristas', rota((req, res) => {
    res.json(queryAll('SELECT * FROM motoristas ORDER BY nome'));
  }));

  app.post('/api/motoristas', rota((req, res) => {
    const { nome } = req.body;
    if (!nome) return res.status(400).json({ erro: 'Nome obrigatorio.' });
    try {
      db.run('INSERT INTO motoristas (nome) VALUES (?)', [nome.toUpperCase().trim()]);
      salvarArquivo();
      const id = queryOne('SELECT last_insert_rowid() as id');
      res.json({ id: id ? id.id : null });
    } catch(e) { res.status(409).json({ erro: 'Motorista ja cadastrado.' }); }
  }));

  // v.159: telefone do motorista — usado para mandar o roteiro pelo WhatsApp.
  // Aceita achar pelo id ou pelo nome (a tela do roteiro só conhece o nome).
  app.put('/api/motoristas/telefone', rota((req, res) => {
    const nome = String(req.body?.nome || '').trim().toUpperCase();
    const tel = String(req.body?.telefone || '').replace(/\D/g, '');
    if (!nome) return res.status(400).json({ erro: 'Informe o motorista.' });
    const m = queryOne('SELECT id FROM motoristas WHERE nome=? COLLATE NOCASE', [nome]);
    if (!m) return res.status(404).json({ erro: 'Motorista não encontrado.' });
    db.run('UPDATE motoristas SET telefone=? WHERE id=?', [tel, m.id]);
    salvarArquivo();
    res.json({ ok: true, telefone: tel });
  }));

  app.delete('/api/motoristas/:id', rota((req, res) => {
    const m = queryOne('SELECT nome FROM motoristas WHERE id=?', [req.params.id]);
    if (m) {
      registrarLog('EXCLUSÃO DE MOTORISTA', `Motorista: ${m.nome}`, req.body?.motivo||'-', '', req.usuario?.nome||'sistema');
      db.run('DELETE FROM associacoes WHERE motorista=?', [m.nome]);
    }
    db.run('DELETE FROM motoristas WHERE id=?', [req.params.id]);
    salvarArquivo(); res.json({ ok: true });
  }));

  // ─── CAMINHÕES ──────────────────────────────────────────────────────────────
  app.get('/api/caminhoes', rota((req, res) => {
    res.json(queryAll('SELECT * FROM caminhoes ORDER BY placa'));
  }));

  app.post('/api/caminhoes', rota((req, res) => {
    const { placa, modelo, capacidade_kg, hodometro_atual, tipo_combustivel, tanque_litros } = req.body;
    if (!placa) return res.status(400).json({ erro: 'Placa obrigatoria.' });
    try {
      db.run('INSERT INTO caminhoes (placa,modelo,capacidade_kg,hodometro_atual,tipo_combustivel,tanque_litros) VALUES (?,?,?,?,?,?)',
        [placa.toUpperCase().trim(), modelo||'', capacidade_kg||0, hodometro_atual||0, tipo_combustivel||'Diesel S10', tanque_litros||0]);
      salvarArquivo();
      const id = queryOne('SELECT last_insert_rowid() as id');
      res.json({ id: id ? id.id : null });
    } catch(e) { res.status(409).json({ erro: 'Caminhao ja cadastrado.' }); }
  }));

  app.delete('/api/caminhoes/:id', rota((req, res) => {
    const c = queryOne('SELECT placa,modelo FROM caminhoes WHERE id=?', [req.params.id]);
    if (c) {
      registrarLog('EXCLUSÃO DE CAMINHÃO', `Caminhão: ${c.placa} ${c.modelo||''}`, '', '', req.usuario?.nome||'sistema');
      db.run('DELETE FROM associacoes WHERE caminhao=?', [c.placa]);
    }
    db.run('DELETE FROM caminhoes WHERE id=?', [req.params.id]);
    salvarArquivo(); res.json({ ok: true });
  }));

  app.put('/api/caminhoes/:id', rota((req, res) => {
    const { modelo, capacidade_kg, hodometro_atual, tipo_combustivel, tanque_litros } = req.body;
    db.run('UPDATE caminhoes SET modelo=?,capacidade_kg=?,hodometro_atual=?,tipo_combustivel=?,tanque_litros=? WHERE id=?',
      [modelo||'', capacidade_kg||0, hodometro_atual||0, tipo_combustivel||'Diesel S10', tanque_litros||0, req.params.id]);
    salvarArquivo();
    res.json({ ok: true });
  }));

  // ─── ASSOCIAÇÕES ────────────────────────────────────────────────────────────
  app.get('/api/associacoes', rota((req, res) => {
    res.json(queryAll('SELECT * FROM associacoes'));
  }));

  app.post('/api/associacoes', rota((req, res) => {
    const { motorista, caminhao } = req.body;
    if (!motorista || !caminhao) return res.status(400).json({ erro: 'Dados incompletos.' });
    db.run('DELETE FROM associacoes WHERE motorista=?', [motorista]);
    db.run('INSERT INTO associacoes (motorista,caminhao) VALUES (?,?)', [motorista, caminhao]);
    salvarArquivo();
    res.json({ ok: true });
  }));

  app.delete('/api/associacoes/:id', rota((req, res) => {
    db.run('DELETE FROM associacoes WHERE id=?', [req.params.id]);
    salvarArquivo();
    res.json({ ok: true });
  }));

  // ─── REGIÕES ────────────────────────────────────────────────────────────────
  app.get('/api/regioes', rota((req, res) => {
    res.json(queryAll('SELECT * FROM regioes'));
  }));

  app.post('/api/regioes', rota((req, res) => {
    const { nome, lat, lon } = req.body;
    const ex = queryOne('SELECT id FROM regioes WHERE nome=?', [nome]);
    if (ex) return res.json({ id: ex.id });
    db.run('INSERT INTO regioes (nome,lat,lon) VALUES (?,?,?)', [nome, lat, lon]);
    salvarArquivo();
    const id = queryOne('SELECT last_insert_rowid() as id');
    res.json({ id: id ? id.id : null });
  }));

  // ─── ABASTECIMENTOS ──────────────────────────────────────────────────────────
  app.get('/api/abastecimentos', rota((req, res) => {
    const { caminhao_id, de, ate } = req.query;
    let sql = 'SELECT * FROM abastecimentos WHERE 1=1';
    const params = [];
    if (caminhao_id) { sql += ' AND caminhao_id=?'; params.push(caminhao_id); }
    if (de)  { sql += ' AND data>=?'; params.push(de); }
    if (ate) { sql += ' AND data<=?'; params.push(ate); }
    sql += ' ORDER BY data DESC, id DESC';
    res.json(queryAll(sql, params));
  }));

  app.post('/api/abastecimentos', rota((req, res) => {
    const { caminhao_id, placa, data, hodometro, litros, valor_litro, valor_total, tipo_combustivel, posto, motorista, observacao } = req.body;
    if (!caminhao_id || !data) return res.status(400).json({ erro: 'Caminhão e data obrigatórios.' });
    db.run(`INSERT INTO abastecimentos (caminhao_id,placa,data,hodometro,litros,valor_litro,valor_total,tipo_combustivel,posto,motorista,observacao)
            VALUES (?,?,?,?,?,?,?,?,?,?,?)`,
      [caminhao_id, placa||'', data, hodometro||0, litros||0, valor_litro||0, valor_total||0, tipo_combustivel||'Diesel S10', posto||'', motorista||'', observacao||'']);
    // Atualizar hodômetro atual do caminhão
    if (hodometro && parseFloat(hodometro) > 0) {
      db.run('UPDATE caminhoes SET hodometro_atual=? WHERE id=?', [hodometro, caminhao_id]);
    }
    salvarArquivo();
    res.json({ ok: true });
  }));

  app.put('/api/abastecimentos/:id', rota((req, res) => {
    const { data, hodometro, litros, valor_litro, valor_total, tipo_combustivel, posto, motorista, observacao } = req.body;
    db.run(`UPDATE abastecimentos SET data=?, hodometro=?, litros=?, valor_litro=?, valor_total=?, tipo_combustivel=?, posto=?, motorista=?, observacao=? WHERE id=?`,
      [data, hodometro||0, litros||0, valor_litro||0, valor_total||0, tipo_combustivel||'Diesel S10', posto||'', motorista||'', observacao||'', req.params.id]);
    salvarArquivo();
    res.json({ ok: true });
  }));

  app.delete('/api/abastecimentos/:id', rota((req, res) => {
    const info = queryOne('SELECT placa,data,litros,valor_total FROM abastecimentos WHERE id=?', [req.params.id]);
    if (info) {
      registrarLog('EXCLUSÃO DE ABASTECIMENTO',
        `${info.placa||'?'} — ${info.data||'?'} — ${info.litros||0}L`,
        req.headers['x-motivo']||'-',
        `Valor: R$ ${(info.valor_total||0).toFixed(2)}`,
        req.usuario?.nome||'sistema');
    }
    db.run('DELETE FROM abastecimentos WHERE id=?', [req.params.id]);
    salvarArquivo();
    res.json({ ok: true });
  }));

  // Resumo por caminhão (consumo, total gasto, etc)
  app.get('/api/abastecimentos/resumo', rota((req, res) => {
    const caminhoes = queryAll('SELECT * FROM caminhoes ORDER BY placa');
    const resumo = caminhoes.map(c => {
      const abasts = queryAll('SELECT * FROM abastecimentos WHERE caminhao_id=? ORDER BY data ASC, id ASC', [c.id]);
      const totalLitros = abasts.reduce((s,a)=>s+(a.litros||0), 0);
      const totalGasto = abasts.reduce((s,a)=>s+(a.valor_total||0), 0);
      let kmRodados = 0;
      if (abasts.length >= 2) {
        const hodInicial = abasts[0].hodometro || 0;
        const hodFinal = abasts[abasts.length-1].hodometro || 0;
        if (hodFinal > hodInicial) kmRodados = hodFinal - hodInicial;
      }
      const consumo = kmRodados > 0 && totalLitros > 0 ? (kmRodados / totalLitros) : 0;
      const custoKm = kmRodados > 0 ? (totalGasto / kmRodados) : 0;
      return {
        id: c.id, placa: c.placa, modelo: c.modelo,
        hodometro_atual: c.hodometro_atual || 0,
        tipo_combustivel: c.tipo_combustivel || 'Diesel S10',
        tanque_litros: c.tanque_litros || 0,
        total_abastecimentos: abasts.length,
        total_litros: totalLitros,
        total_gasto: totalGasto,
        km_rodados: kmRodados,
        consumo_km_l: consumo,
        custo_por_km: custoKm,
        ultimo_abast: abasts.length ? abasts[abasts.length-1].data : '-'
      };
    });
    res.json(resumo);
  }));

