    const equipamentos = queryAll('SELECT * FROM equipamentos WHERE ativo=1 ORDER BY nome');
    const hoje = new Date().toISOString().substring(0,10);
    const em30dias = new Date(Date.now()+30*24*60*60*1000).toISOString().substring(0,10);
    const out = equipamentos.map(e => {
      const ms = queryAll('SELECT * FROM manutencoes_equip WHERE equipamento_id=? ORDER BY data DESC', [e.id]);
      const total = ms.reduce((s,m) => s + (+m.valor||0), 0);
      const ultima = ms[0] || null;
      const proximas = ms.filter(m => m.proxima_data && m.proxima_data >= hoje && m.proxima_data <= em30dias);
      return {
        id: e.id, nome: e.nome, tipo: e.tipo, unidade: e.unidade, setor: e.setor,
        qtd: ms.length, total: +total.toFixed(2),
        ultima_data: ultima?.data || '', ultima_descricao: ultima?.descricao || '',
        horimetro: ultima?.horimetro || 0, alertas: proximas.length
      };
    });
    res.json(out);
