  // Resumo por caminhão
  app.get('/api/manutencoes/resumo', rota((req, res) => {
    const caminhoes = queryAll('SELECT * FROM caminhoes ORDER BY placa');
    const hoje = new Date().toISOString().substring(0,10);
    const em30dias = new Date(Date.now()+30*24*60*60*1000).toISOString().substring(0,10);
    const resumo = caminhoes.map(c => {
      const manuts = queryAll('SELECT * FROM manutencoes WHERE caminhao_id=? ORDER BY data DESC', [c.id]);
      const totalGasto = manuts.reduce((s,m)=>s+(m.valor||0), 0);
      const concluidas = manuts.filter(m=>m.status==='CONCLUIDA').length;
      const pendentes = manuts.filter(m=>m.status==='PENDENTE').length;
      // Próximas manutenções (data <= 30 dias OU km próximo do atual)
      const proximas = manuts.filter(m=>{
        if (m.proxima_data && m.proxima_data >= hoje && m.proxima_data <= em30dias) return true;
        if (m.proximo_hodometro > 0 && c.hodometro_atual > 0 && (m.proximo_hodometro - c.hodometro_atual) <= 1000 && (m.proximo_hodometro - c.hodometro_atual) >= 0) return true;
        return false;
      });
      // Vencidas (passou da data ou já passou do km)
      const vencidas = manuts.filter(m=>{
        if (m.proxima_data && m.proxima_data < hoje && m.status!=='CONCLUIDA') return true;
        if (m.proximo_hodometro > 0 && c.hodometro_atual > 0 && c.hodometro_atual > m.proximo_hodometro && m.status!=='CONCLUIDA') return true;
        return false;
      });
      const ultima = manuts[0];
      return {
        id: c.id, placa: c.placa, modelo: c.modelo,
        hodometro_atual: c.hodometro_atual||0,
        total: manuts.length, concluidas, pendentes,
        total_gasto: totalGasto,
        ultima_data: ultima?ultima.data:'-',
        ultima_descricao: ultima?ultima.descricao:'-',
        proximas: proximas.length,
        vencidas: vencidas.length
      };
    });
    res.json(resumo);
  }));

  // Alertas (próximas e vencidas)
  app.get('/api/manutencoes/alertas', rota((req, res) => {
    const caminhoes = queryAll('SELECT * FROM caminhoes');
    const hoje = new Date().toISOString().substring(0,10);
    const em30dias = new Date(Date.now()+30*24*60*60*1000).toISOString().substring(0,10);
    const alertas = [];
    caminhoes.forEach(c => {
      const manuts = queryAll('SELECT * FROM manutencoes WHERE caminhao_id=? AND (proxima_data!="" OR proximo_hodometro>0)', [c.id]);
      manuts.forEach(m => {
        let tipoAlerta = null, dias = null, km = null;
        if (m.proxima_data) {
          if (m.proxima_data < hoje && m.status!=='CONCLUIDA') tipoAlerta = 'VENCIDA';
          else if (m.proxima_data <= em30dias) tipoAlerta = 'PROXIMA';
          dias = Math.floor((new Date(m.proxima_data) - new Date(hoje))/86400000);
        }
        if (m.proximo_hodometro > 0 && c.hodometro_atual > 0) {
          const diff = m.proximo_hodometro - c.hodometro_atual;
          if (diff < 0 && m.status!=='CONCLUIDA') tipoAlerta = 'VENCIDA';
          else if (diff <= 1000) tipoAlerta = tipoAlerta || 'PROXIMA';
          km = diff;
        }
        if (tipoAlerta) {
          alertas.push({
            id: m.id, placa: c.placa, modelo: c.modelo,
            descricao: m.descricao, categoria: m.categoria,
            proxima_data: m.proxima_data, proximo_hodometro: m.proximo_hodometro,
            hodometro_atual: c.hodometro_atual,
            dias, km, tipo: tipoAlerta
          });
        }
      });
    });
    // Ordenar: vencidas primeiro, depois por proximidade
    alertas.sort((a,b)=>{
      if (a.tipo==='VENCIDA' && b.tipo!=='VENCIDA') return -1;
      if (b.tipo==='VENCIDA' && a.tipo!=='VENCIDA') return 1;
      return (a.dias||999) - (b.dias||999);
    });
    res.json(alertas);
  }));

