  // Helper: normaliza string para comparação (remove acentos, espaços extras, minúsculas)
  function normalizarTexto(s) {
    if (!s) return '';
    return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '')
      .toUpperCase().replace(/\s+/g, ' ').trim();
  }

  // Buscar preço de um produto específico (match por PALAVRAS — todas presentes)
  app.get('/api/precos-produtos/buscar', rota((req, res) => {
    const { produto } = req.query;
    if (!produto) return res.json({ preco_medio: 0 });
    const produtoNorm = normalizarTexto(produto);
    const produtoWords = new Set(produtoNorm.split(/\s+/).filter(Boolean));
    const todos = queryAll('SELECT * FROM precos_produtos');
    // 1º: match exato (normalizado)
    let exato = todos.find(p => normalizarTexto(p.produto) === produtoNorm);
    if (exato) return res.json(exato);
    // 2º: match por palavras — TODAS as palavras do preço cadastrado devem estar no produto
    let melhor = null, maiorMatch = 0;
    todos.forEach(p => {
      const pNorm = normalizarTexto(p.produto);
      const pWords = pNorm.split(/\s+/).filter(Boolean);
      if (pWords.length === 0) return;
      const todasPresentes = pWords.every(w => produtoWords.has(w));
      if (todasPresentes && pNorm.length > maiorMatch) {
        melhor = p;
        maiorMatch = pNorm.length;
      }
    });
    res.json(melhor || { preco_medio: 0 });
  }));

  app.post('/api/precos-produtos', rota((req, res) => {
    const { produto, preco_medio, custo } = req.body;
    if (!produto) return res.status(400).json({ erro: 'Produto é obrigatório.' });
    try {
      db.run(`INSERT INTO precos_produtos (produto,preco_medio,custo,atualizado_em)
              VALUES (?,?,?,datetime('now','localtime'))
              ON CONFLICT(produto) DO UPDATE SET preco_medio=excluded.preco_medio, custo=excluded.custo, atualizado_em=excluded.atualizado_em`,
        [produto, preco_medio||0, custo||0]);
      salvarArquivo();
      res.json({ ok: true });
    } catch(e) { res.status(500).json({ erro: e.message }); }
  }));

