    let sql = `SELECT m.*, e.nome, e.unidade FROM estoque_movimentos m
               LEFT JOIN estoque_materia_prima e ON e.chave = m.chave WHERE 1=1`;
    const params = [];
    if (chave) { sql += ' AND m.chave=?'; params.push(chave); }
    sql += ' ORDER BY m.id DESC LIMIT ' + lim;
